 30 pub enum FloorBearingConstructionError {
 31     #[error("floor binding has invalid building {0}")]
 32     InvalidBuilding(crate::scene_input::SceneBuildingId),
 33     #[error("floor regions must form a nonempty disjoint partition")]
 34     InvalidPartition,
 35     #[error(transparent)]
 36     Geometry(#[from] adventuresim_building_generator::spatial_geometry::GeometryError),
 37     #[error(transparent)]
 38     Plan(#[from] adventuresim_building_generator::plan_geometry::PlanGeometryError),
