 40 impl FloorBearing {
 41     fn admit(
 42         building: crate::scene_input::SceneBuildingId,
 43         regions: Vec<FloorRegion>,
 44         elevation: SupportElevation,
 45     ) -> Result<Self, FloorBearingConstructionError> {
 46         if building.0 == 0 {
 47             return Err(FloorBearingConstructionError::InvalidBuilding(building));
 48         }
 49         if regions.is_empty() {
 50             return Err(FloorBearingConstructionError::InvalidPartition);
 51         }
 52         let outlines: Vec<Vec<DVec2>> = regions
 53             .iter()
 54             .map(|region| {
 55                 region
 56                     .outline()
 57                     .vertices()
 58                     .iter()
 59                     .map(|p| p.metres().as_dvec2())
 60                     .collect()
 61             })
 62             .collect();
 63         for (index, region) in outlines.iter().enumerate() {
 64             if outlines[..index].iter().any(|other| {
 65                 has_positive_overlap(region, other) || has_partial_shared_edge(region, other)
 66             }) {
 67                 return Err(FloorBearingConstructionError::InvalidPartition);
 68             }
 69         }
 70         Ok(Self {
 71             building,
 72             regions,
 73             elevation,
 74         })
 75     }
 76     // Exact shared partition edges cancel; internal cuts add no tolerance.
 77     fn exterior_perimeter(&self) -> f64 {
 78         let mut edges = std::collections::BTreeMap::new();
 79         for region in &self.regions {
 80             let vertices = region.outline().vertices();
 81             for (a, b) in vertices
 82                 .iter()
 83                 .zip(vertices.iter().cycle().skip(1))
 84                 .take(vertices.len())
 85             {
 86                 let mut endpoints = [
 87                     a.metres().to_array().map(edge_coordinate_key),
 88                     b.metres().to_array().map(edge_coordinate_key),
 89                 ];
 90                 endpoints.sort();
 91                 let edge = edges
 92                     .entry(endpoints)
 93                     .or_insert((0_u32, a.metres().as_dvec2().distance(b.metres().as_dvec2())));
 94                 edge.0 += 1;
 95             }
 96         }
 97         edges
 98             .values()
 99             .filter(|(count, _)| *count == 1)
100             .map(|(_, length)| length)
101             .sum()
102     }
