200             if !self
201                 .property_bindings
202                 .iter()
203                 .any(|binding| binding.property == compound.id && binding.members.ids() == expected)
204             {
205                 return Err(CityGroundingProjectionError::PropertyMismatch {
206                     owners: self.owner_contexts(ProjectionBoundary::OccupiedBindings),
207                 });
