 41     /// Interpolate the nearest body triangle's skin, rather than copying a
 42     /// single vertex's rows. UVs belong to the garment's own construction.
 43     pub fn transfer(&self, positions: &[[f32; 3]]) -> Result<SkinWeights> {
 44         self.validate()?;
 45         let tree = TriangleBvh::new(
 46             self.positions.iter().copied().map(vector).collect(),
 47             self.faces.to_vec(),
 48         );
 49         let mut output = SkinWeights {
 50             indices: PackedRigSkin::empty(self.indices.joint_count()),
 51             weights: Vec::with_capacity(positions.len()),
 52         };
 53         for &position in positions {
 54             ensure!(
 55                 position.iter().all(|v| v.is_finite()),
 56                 "non-finite skin query"
 57             );
 58             let (triangle, point, _) = tree
 59                 .closest_point(vector(position), f32::MAX)
 60                 .context("no body surface for garment skin transfer")?;
 61             let face = self.faces[triangle as usize];
 62             let [a, b, c] = face.map(|i| vector(self.positions[i as usize]));
 63             let bary = barycentric(a, b, c, point);
 64             let mut influences = BTreeMap::new();
 65             for (vertex, factor) in face.into_iter().zip(bary) {
 66                 accumulate(
 67                     &mut influences,
 68                     self.indices.vertex(vertex as usize),
 69                     self.weights[vertex as usize],
 70                     factor.max(0.0),
 71                 );
 72             }
 73             let row = normalized(influences)?;
 74             output.indices.push(row.indices)?;
 75             output.weights.push(row.weights);
 76         }
 77         Ok(output)
 78     }
