 23 /// Give `design`'s rigid plates their single anatomical owner. `joints` are
 24 /// the wearer's global joint states, one per name.
 25 pub fn attach(
 26     design: &ParametricDesign,
 27     placement: FittingPlacement,
 28     joint_names: &fabelgeist_rig::RigJointTable<RigJointName>,
 29     joints: &fabelgeist_rig::RigJointTable<[f32; 8]>,
 30     armor: &mut GeneratedArmor,
 31 ) -> Result<()> {
 32     anyhow::ensure!(
 33         armor.joint_indices.joint_count() == joint_names.joint_count(),
 34         "rigid armor skin and wearer have different joint bounds"
 35     );
 36     let (joint, roles): (_, &[_]) = match design {
 37         ParametricDesign::Skirt(_) | ParametricDesign::Gown(_) => (
 38             RigJointName::ROOT,
 39             &[ArmorComponentRole::Boning, ArmorComponentRole::Hoops],
 40         ),
 41         ParametricDesign::WaistAssembly(_) => return waist(joint_names, joints, armor),
 42         ParametricDesign::Garment(garment)
 43             if matches!(
 44                 garment.kind,
 45                 GarmentArmorKind::Fauld | GarmentArmorKind::Tassets
 46             ) =>
 47         {
 48             return waist(joint_names, joints, armor);
 49         }
 50         ParametricDesign::Garment(garment) if garment.kind == GarmentArmorKind::Gorget => {
 51             // A gorget is seated on the cuirass. Its formed bib and collar
 52             // sheets share that rigid support; nearby clavicle and neck skin
 53             // must not fold metal or move the bib through its lower plate.
 54             (RigJointName::C_SPINE3, &[ArmorComponentRole::Plate])
 55         }
 56         ParametricDesign::Helmet(HelmetDesign::ArmingCap(_) | HelmetDesign::MailCoif(_)) => {
 57             return Ok(());
 58         }
 59         ParametricDesign::Helmet(_) => {
 60             // Every helmet plate, visors and bevors included, is rigid.
 61             let head = joint_index(joint_names, &RigJointName::C_HEAD)?;
 62             fill(armor, 0..armor.positions.len(), head)?;
 63             return Ok(());
 64         }
 65         ParametricDesign::Limb(limb) => match limb {
 66             // Keep the fitted saddle and courses coherent until an equipment
 67             // rig supplies independent plate transforms.
 68             LimbArmorDesign::Pauldron(_) => (
 69                 limb_joint(placement, RigJointPart::Uparm)?,
 70                 &[
 71                     ArmorComponentRole::Plate,
 72                     ArmorComponentRole::JointExtension,
 73                 ],
 74             ),
 75             LimbArmorDesign::Couter(_) => (
 76                 limb_joint(placement, RigJointPart::Lowarm)?,
 77                 &[
 78                     ArmorComponentRole::Plate,
 79                     ArmorComponentRole::JointExtension,
 80                 ],
 81             ),
 82             LimbArmorDesign::Poleyn(_) => (
 83                 limb_joint(placement, RigJointPart::Lowleg)?,
 84                 &[
 85                     ArmorComponentRole::Plate,
 86                     ArmorComponentRole::JointExtension,
 87                 ],
 88             ),
 89             LimbArmorDesign::Rerebrace(_) | LimbArmorDesign::Spaulder(_) => (
 90                 limb_joint(placement, RigJointPart::Uparm)?,
 91                 &[ArmorComponentRole::Plate],
 92             ),
 93             LimbArmorDesign::Cuisse(_) => (
 94                 limb_joint(placement, RigJointPart::Upleg)?,
 95                 &[ArmorComponentRole::Plate],
 96             ),
 97             _ => return Ok(()),
 98         },
 99         _ => return Ok(()),
100     };
101     let anchor = joint_index(joint_names, &joint)?;
102     let besagews = armor
103         .components
104         .iter()
105         .filter(|component| component.role == ArmorComponentRole::Besagew)
106         .map(|component| component.vertices.clone())
107         .collect::<Vec<_>>();
108     if !besagews.is_empty() {
109         let chest = joint_index(joint_names, &RigJointName::C_SPINE3)?;
110         for vertices in besagews {
111             fill(armor, vertices, chest)?;
112         }
113     }
114     // A piece without components is one plate.
115     if armor.components.is_empty() {
116         fill(armor, 0..armor.positions.len(), anchor)?;
117         return Ok(());
118     }
119     let plates = armor
120         .components
121         .iter()
122         .filter(|component| roles.contains(&component.role))
123         .map(|component| component.vertices.clone())
124         .collect::<Vec<_>>();
125     for vertices in plates {
126         fill(armor, vertices, anchor)?;
127     }
128     Ok(())
129 }
