131 /// The cuirass follows the chest as one rigid assembly. Separate horizontal
132 /// courses retain their constructed overlaps. Independent course motion needs
133 /// armor pivots and lap constraints; body-spine joints are not those pivots.
134 pub(crate) fn breastplate(
135     joint_names: &fabelgeist_rig::RigJointTable<RigJointName>,
136     armor: &mut GeneratedArmor,
137 ) -> Result<()> {
138     anyhow::ensure!(
139         armor.joint_indices.joint_count() == joint_names.joint_count(),
140         "cuirass skin and wearer have different joint bounds"
141     );
142     let chest = joint_index(joint_names, &RigJointName::C_SPINE3)?;
143     fill(armor, 0..armor.positions.len(), chest)?;
144     Ok(())
145 }
146 
147 /// Each separate sheet of a fauld follows the pelvis; each tasset, the hip
148 /// on its side of the pelvis.
149 fn waist(
150     joint_names: &fabelgeist_rig::RigJointTable<RigJointName>,
151     joints: &fabelgeist_rig::RigJointTable<[f32; 8]>,
152     armor: &mut GeneratedArmor,
153 ) -> Result<()> {
154     let pelvis = joint_index(joint_names, &RigJointName::ROOT)?;
155     let hips = [
156         joint_index(joint_names, &RigJointName::L_UPLEG)?,
157         joint_index(joint_names, &RigJointName::R_UPLEG)?,
158     ];
159     let center = joints.get(pelvis).context("missing pelvic joint state")?[0];
160     let tassets = armor
161         .components
162         .iter()
163         .filter(|component| component.role == ArmorComponentRole::Tassets)
164         .map(|component| component.vertices.clone())
165         .collect::<Vec<_>>();
166     for sheet in sheets(&armor.indices, armor.positions.len()) {
167         let anchor = if tassets.iter().any(|range| range.contains(&sheet[0])) {
168             let middle =
169                 sheet.iter().map(|&i| armor.positions[i][0]).sum::<f32>() / sheet.len() as f32;
170             // The wearer's left lies toward +x.
171             hips[usize::from(middle < center)]
172         } else {
173             pelvis
174         };
175         for vertex in sheet {
176             fill(armor, vertex..vertex + 1, anchor)?;
177         }
178     }
179     Ok(())
180 }
181 
182 /// The vertices of each connected sheet of triangles.
183 fn sheets(indices: &[u32], vertex_count: usize) -> Vec<Vec<usize>> {
184     fn root(parents: &mut [usize], mut vertex: usize) -> usize {
185         while parents[vertex] != vertex {
186             parents[vertex] = parents[parents[vertex]];
187             vertex = parents[vertex];
188         }
189         vertex
190     }
191     let mut parents = (0..vertex_count).collect::<Vec<_>>();
192     for triangle in indices.as_chunks::<3>().0 {
193         let a = root(&mut parents, triangle[0] as usize);
194         for &corner in &triangle[1..] {
195             let b = root(&mut parents, corner as usize);
196             parents[b] = a;
197         }
198     }
199     let mut sheets = std::collections::BTreeMap::<usize, Vec<usize>>::new();
200     for vertex in 0..vertex_count {
201         let sheet = root(&mut parents, vertex);
202         sheets.entry(sheet).or_default().push(vertex);
203     }
204     sheets.into_values().collect()
205 }
