281 impl DrapedGarment {
282     /// Show particle positions before the seams are welded. Averaging the
283     /// still-open seam copies would pull separated panels towards each other.
284     fn show_unsewn(
285         &mut self,
286         positions: Vec<[f32; 3]>,
287         triangles: &[[u32; 3]],
288         body: &fabelgeist_bvh::TriangleBvh,
289         stage: DrapeStage,
290     ) -> Result<()> {
291         anyhow::ensure!(
292             positions.len() == self.texcoords.len(),
293             "cloth particles do not match the garment's material vertices"
294         );
295         if positions.iter().flatten().any(|x| !x.is_finite()) {
296             bail!("cloth simulation produced non-finite positions");
297         }
298         let mut faces = triangles.to_vec();
299         orient_faces(&positions, &mut faces, body);
300         self.normals = normals(&positions, &faces);
301         self.faces = faces;
302         self.positions = positions;
303         self.stage = stage;
304         Ok(())
305     }
306 
307     /// Show the sewn surface: seam copies share one position, winding and
308     /// normal, so joined panels shade continuously.
309     fn show_sewn(
310         &mut self,
311         particles: &[[f32; 3]],
312         surface: &SewnSurface,
313         triangles: &[[u32; 3]],
314         body: &fabelgeist_bvh::TriangleBvh,
315         stage: DrapeStage,
316     ) -> Result<()> {
317         self.positions = surface.expand(&surface.positions(particles));
318         if self.positions.iter().flatten().any(|x| !x.is_finite()) {
319             bail!("cloth simulation produced non-finite positions");
320         }
321         let sewn = surface.positions(&self.positions);
322         let mut sewn_faces = surface.faces.clone();
323         orient_faces(&sewn, &mut sewn_faces, body);
324         self.faces = triangles.to_vec();
325         for (i, face) in sewn_faces.iter().enumerate() {
326             if *face != surface.faces[i] {
327                 self.faces[surface.render_faces[i]].swap(1, 2);
328             }
329         }
330         self.normals = surface.expand(&normals(&sewn, &sewn_faces));
331         self.stage = stage;
332         Ok(())
333     }
334 }

