  2 //! the studio. A new request cancels the running drape.
  3 use adventuresim_character_creator::garment::{
  4     DrapeCheckpoints, DrapeInput, DrapedGarment, OutfitOutcome, drape_outfit,
  5 };
  6 use std::sync::{
  7     Arc, Mutex,
  8     atomic::{AtomicBool, Ordering},
  9 };
 10 
 11 /// Drapes garments, each tagged with what it belongs to.
 12 pub(super) struct DrapeWorker<T> {
 13     handle: Option<std::thread::JoinHandle<OutfitOutcome>>,
 14     pending: Option<Vec<(T, DrapeInput)>>,
 15     /// The tag of each garment the running drape produces.
 16     draping: Vec<T>,
 17     cancel: Arc<AtomicBool>,
 18     latest: Arc<Mutex<Option<Vec<DrapedGarment>>>>,
 19     /// Completed stages of the most recent drape, reused by the next request.
 20     checkpoints: Vec<DrapeCheckpoints>,
 21 }
 22 
 23 impl<T> Default for DrapeWorker<T> {
 24     fn default() -> Self {
 25         Self {
 26             handle: None,
 27             pending: None,
 28             draping: Vec::new(),
 29             cancel: Arc::default(),
 30             latest: Arc::default(),
 31             checkpoints: Vec::new(),
 32         }
 33     }
 34 }
 35 
 36 impl<T> Drop for DrapeWorker<T> {
 37     fn drop(&mut self) {
 38         self.cancel.store(true, Ordering::Relaxed);
 39     }
 40 }
 41 
 42 /// What changed since the worker was last polled.
 43 #[derive(Default)]
 44 pub(super) struct DrapeProgress {
 45     /// A drape began; its garments are tagged by [`DrapeWorker::draping`].
 46     pub started: bool,
 47     /// Garments to show now, in drape order.
 48     pub preview: Option<Vec<DrapedGarment>>,
 49     /// The drape's result, once it finished without being cancelled.
 50     pub finished: Option<OutfitOutcome>,
 51 }
 52 
 53 impl<T: Send + 'static> DrapeWorker<T> {
 54     /// Drape garments, innermost first, cancelling any drape in progress.
 55     pub fn request(&mut self, input: Vec<(T, DrapeInput)>) {
 56         self.cancel.store(true, Ordering::Relaxed);
 57         self.pending = (!input.is_empty()).then_some(input);
 58         *self.latest.lock().unwrap() = None;
 59     }
 60 
 61     /// Make the next request simulate every stage again.
 62     pub fn restart_from_placement(&mut self) {
 63         self.checkpoints.clear();
 64     }
 65 
 66     /// Whether a drape is queued or running.
 67     pub fn running(&self) -> bool {
 68         self.handle.is_some() || self.pending.is_some()
 69     }
 70 
 71     /// The tags of the garments the latest drape produces.
 72     pub fn draping(&self) -> &[T] {
 73         &self.draping
 74     }
 75 
 76     /// Collect the running drape's progress, and start a queued one.
 77     pub fn poll(&mut self) -> DrapeProgress {
 78         let mut progress = DrapeProgress {
 79             preview: if self.cancel.load(Ordering::Relaxed) {
 80                 None
 81             } else {
 82                 self.latest.lock().unwrap().take()
 83             },
 84             ..DrapeProgress::default()
 85         };
 86         if self
 87             .handle
 88             .as_ref()
 89             .is_some_and(std::thread::JoinHandle::is_finished)
 90         {
 91             let mut outcome = self
 92                 .handle
 93                 .take()
 94                 .expect("checked above")
 95                 .join()
 96                 .unwrap_or_else(|_| OutfitOutcome {
 97                     garments: Vec::new(),
 98                     warnings: Vec::new(),
 99                     error: Some(anyhow::anyhow!("Drape worker failed")),
100                     checkpoints: Vec::new(),
101                 });
102             // Keep completed stages even from a failed or cancelled drape.
103             self.checkpoints = std::mem::take(&mut outcome.checkpoints);
104             if !self.cancel.load(Ordering::Relaxed) {
105                 // Whatever draped is shown and usable, even when some of it failed.
106                 progress.preview = Some(outcome.garments.clone());
107                 progress.finished = Some(outcome);
108             }
109         }
110         if self.handle.is_none()
111             && let Some(pending) = self.pending.take()
112         {
113             let (tags, input): (Vec<_>, Vec<_>) = pending.into_iter().unzip();
114             self.draping = tags;
115             let cancel = Arc::new(AtomicBool::new(false));
116             self.cancel = cancel.clone();
117             let latest = Arc::new(Mutex::new(None));
118             self.latest = latest.clone();
119             let previous = std::mem::take(&mut self.checkpoints);
120             self.handle = Some(std::thread::spawn(move || {
121                 drape_outfit(input, previous, &cancel, |garments| {
122                     if !cancel.load(Ordering::Relaxed) {
123                         *latest.lock().unwrap() = Some(garments);
124                     }
125                 })
126             }));
127             progress.started = true;
128         }
129         progress
130     }
131 }

