//! Corrective-array admission failures, distinct from archive/parser causes.

use std::{error::Error, fmt};

use fabelgeist_numpy_storage::{NpyDimension, NpyElementCount, NpyLayoutError, NpyShape};

use fabelgeist_rig::RigJointCount;

use super::{CorrectiveFeatureIndex, CorrectiveHiddenIndex};
use crate::character::MeshVertexCount;

pub type Result<T> = std::result::Result<T, CorrectiveImportError>;

/// The native tensor extent whose checked calculation overflowed.
#[derive(Debug, Clone, Copy)]
pub enum CorrectiveExtent {
    HiddenUnits,
    FeatureChannels,
    BasisColumns,
    BasisElements,
    DenseElements,
}

/// A rejected relationship in the corrective network's imported tensor data.
#[derive(Debug)]
pub enum CorrectiveImportError {
    BasisShape {
        shape: NpyShape,
    },
    VertexCount {
        basis: NpyDimension,
        mesh: MeshVertexCount,
    },
    JointCount {
        joints: RigJointCount,
    },
    Components {
        actual: NpyDimension,
        expected: NpyDimension,
    },
    ExtentOverflow {
        extent: CorrectiveExtent,
    },
    TensorLayout {
        extent: CorrectiveExtent,
        source: NpyLayoutError,
    },
    SparseCardinality {
        indices: NpyElementCount,
        weights: NpyElementCount,
    },
    SparseCoordinate {
        hidden: CorrectiveHiddenIndex,
        feature: CorrectiveFeatureIndex,
    },
}

impl fmt::Display for CorrectiveImportError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::BasisShape { shape } => write!(
                f,
                "{} has shape {shape:?}, expected [components, vertices, 3]",
                super::super::archive::CorrectiveArray::Basis.name()
            ),
            Self::VertexCount { basis, mesh } => write!(
                f,
                "corrective basis covers {basis} vertices but the mesh has {mesh}"
            ),
            Self::JointCount { joints } => write!(
                f,
                "corrective network has {joints} joints, fewer than the {} unposed joints",
                super::super::SKIPPED_JOINTS
            ),
            Self::Components { actual, expected } => write!(
                f,
                "corrective basis has {actual} components, expected {expected}"
            ),
            Self::ExtentOverflow { extent } | Self::TensorLayout { extent, .. } => {
                write!(f, "corrective tensor extent overflows for {extent:?}")
            }
            Self::SparseCardinality { indices, weights } => write!(
                f,
                "sparse activation has {indices} indices for {weights} weights"
            ),
            Self::SparseCoordinate { hidden, feature } => write!(
                f,
                "sparse activation index ({}, {}) is out of bounds",
                hidden.native_index(),
                feature.native_index()
            ),
        }
    }
}

impl Error for CorrectiveImportError {
    fn source(&self) -> Option<&(dyn Error + 'static)> {
        match self {
            Self::TensorLayout { source, .. } => Some(source),
            _ => None,
        }
    }
}

//! MHR's corrective archive schema and its fixed array roles.

use std::path::Path;

use anyhow::{Context, Result};
use fabelgeist_numpy_storage::{NpyArray, NpyFloat32Values, NpyIntegerValues, Npz, NpzArrayName};

use super::import::{CorrectiveLayout, SparseActivation};

/// Encoded corrective archives with explicit roles before NPZ admission.
/// Payload contents are checked when the archives and their members are read.
pub struct CorrectiveArchiveBytes {
    pub activation: Vec<u8>,
    pub basis: Vec<u8>,
}

pub(super) struct CorrectiveArchives {
    activation: Npz,
    basis: Npz,
}

pub(super) enum CorrectiveArray {
    Basis,
    SparseIndices,
    SparseWeights,
}

impl CorrectiveArray {
    pub(super) fn name(self) -> NpzArrayName {
        NpzArrayName::new(match self {
            Self::Basis => "corrective_blendshapes",
            Self::SparseIndices => "0.sparse_indices",
            Self::SparseWeights => "0.sparse_weight",
        })
    }
}

impl CorrectiveArchives {
    pub(super) fn open(activation: &Path, basis: &Path) -> Result<Self> {
        let basis = Npz::open(basis)?;
        let activation = Npz::open(activation)?;
        Ok(Self { activation, basis })
    }

    pub(super) fn from_bytes(archives: CorrectiveArchiveBytes) -> Result<Self> {
        let activation = Npz::from_bytes(archives.activation)?;
        let basis = Npz::from_bytes(archives.basis)?;
        Ok(Self { activation, basis })
    }

    pub(super) fn basis(&self) -> Result<Option<NpyArray>> {
        let name = CorrectiveArray::Basis.name();
        let Some(member) = self.basis.get(&name) else {
            return Ok(None);
        };
        member
            .array()
            .context("reading the corrective basis")
            .map(Some)
    }

    pub(super) fn activation<'layout>(
        &self,
        layout: &'layout CorrectiveLayout,
    ) -> Result<SparseActivation<'layout>> {
        let indices = NpyIntegerValues::from(
            &self
                .activation
                .array(&CorrectiveArray::SparseIndices.name())
                .context("reading the sparse activation indices")?,
        );
        let weights = NpyFloat32Values::from(
            &self
                .activation
                .array(&CorrectiveArray::SparseWeights.name())
                .context("reading the sparse activation weights")?,
        );
        Ok(SparseActivation::new(indices, weights, layout)?)
    }
}

