//! `.npy` array decoding.

pub use metadata::{
    NpyDimension, NpyElementCount, NpyElementWidth, NpyLayoutError, NpyPayloadLength, NpyRank,
    NpyShape,
};

pub use values::{NpyByteStates, NpyFloat32Values, NpyIntegerValues};

