//! Install products from one retained presentation owner.
use super::*;

impl PreparedProducts {
    pub(super) fn generated_scene(
        &self,
        input: &TacticalSceneInput,
    ) -> PreparationResult<PreparedStrategicScene> {
        let digest = input.digest()?;
        self.scene
            .as_ref()
            .filter(|scene| scene.digest == digest)
            .map(|scene| (**scene).clone())
            .ok_or(PreparationError::NotPrepared {
                product: ProductKind::Scene,
            })
    }
}

pub(in crate::presentation) fn take_venue_geometry(
    owner: PresentationOwner,
    program: &BuildingProgram,
) -> PreparationResult<Arc<VenueGeometry>> {
    active_products(owner)?
        .venues
        .iter_mut()
        .find(|v| v.recipe.program == *program)
        .and_then(|v| v.geometry.take())
        .ok_or(PreparationError::NotPrepared {
            product: ProductKind::VenueGeometry,
        })
}

pub(in crate::presentation) fn take_facade(
    owner: PresentationOwner,
    program: &BuildingProgram,
) -> PreparationResult<Arc<PreparedFacade>> {
    let mut products = active_products(owner)?;
    let index = products
        .facades
        .iter()
        .position(|facade| facade.program == *program)
        .ok_or(PreparationError::NotPrepared {
            product: ProductKind::Facade,
        })?;
    Ok(products.facades.swap_remove(index))
}

pub(in crate::presentation) fn release_unused_facades(
    owner: PresentationOwner,
) -> PreparationResult<()> {
    active_products(owner)?.facades.clear();
    Ok(())
}

//! Pure worker execution and ticket-checked product admission.
use super::*;

pub(super) fn generate(job_json: &str, dependencies: &[u8]) -> PreparationResult<Vec<u8>> {
    let job: GenerationJob = serde_json::from_str(job_json)?;
    let dependencies: Dependencies =
        ciborium::from_reader(dependencies).map_err(PreparationError::DependenciesDecode)?;
    let product = match job {
        GenerationJob::RegionalCity { input, graphics } => GenerationProduct::RegionalCity(
            Box::new(city::PreparedCityProduct::generate(*input, graphics)?),
        ),
        GenerationJob::Building(program) => {
            GenerationProduct::Building(Box::new(PreparedFacade::generate(*program)?))
        }
        GenerationJob::Venue(program) => GenerationProduct::Venue(Box::new(
            venue::PreparedVenue::generate(*program, dependencies.recipe)?,
        )),
    };
    let mut bytes = Vec::new();
    ciborium::into_writer(&product, &mut bytes).map_err(PreparationError::ProductEncode)?;
    Ok(bytes)
}

