            "Generation resolution changed its requested product address");
          if (!worker) {
            try { worker = createWorker(); }
            catch (cause) { throw new GenerationPoolError("worker-start-failed", "Scene generation worker could not start", cause); }
            workers[index] = worker; created++;
            const initializeStarted = performance.now();
            await exchange(worker, { kind: "initialize", module });
            initializationMilliseconds += performance.now() - initializeStarted;
          }
          if (phase === "closed") throw new GenerationPoolError("cancelled", "Scene generation cancelled");
          if (failed) break;
          const dependencies = jobOptions.dependencies?.(job);
          if (dependencies !== undefined && (!(dependencies instanceof Uint8Array)
            || !(dependencies.buffer instanceof ArrayBuffer))) {
            throw new GenerationPoolError("invalid-dependencies", "Generation dependencies require transferable bytes");
          }
          const result = await exchange(worker, { kind: "generate", job, dependencies });
          if (phase === "closed") throw new GenerationPoolError("cancelled", "Scene generation cancelled");
          await receive({ job, bytes: result.bytes, workerMilliseconds: result.milliseconds });
          if (phase === "closed") throw new GenerationPoolError("cancelled", "Scene generation cancelled");
        }
      }).map(promise => promise.catch(error => { failed = true; throw error; })));
    } catch (error) {
      close(); throw error;
    } finally {
      if (phase !== "closed") phase = "idle";
    }
    return { status: "completed", createdWorkers: created, initializationMilliseconds };
  }
  function close() {
    phase = "closed";
    if (!cancellation.signal.aborted) cancellation.abort(
      new GenerationPoolError("cancelled", "Scene generation cancelled"));
    for (const cancel of pending) cancel();
    for (const worker of workers.filter(Boolean)) worker.terminate();
    workers.length = 0;
  }
  return { run, close };
}

const CITY_INSTALLATION_DEADLINE_MS = 120_000;

// Only the small ticket is decoded in JavaScript. The canonical document stays
// opaque text; parsing its physical seeds here would lose integer precision.
export async function installRegionalCity(runtime, {request, document, preparation, signal}) {
  signal.throwIfAborted();
  const ticket = JSON.parse(preparation);
  const deadline = performance.now() + CITY_INSTALLATION_DEADLINE_MS;
  // Preparation and terrain publication run independently. Native city
  // admission needs an actual presented window for its geographic frame.
  while (true) {
    signal.throwIfAborted();
    const state = JSON.parse(runtime.wasm_regional_map_status());
    if (state.source === request.source && state.city_requested === request.place
      && state.environment_ready && state.presented && state.requested
      && state.presented.scale === state.requested.scale
      && state.presented.origin.latitude === state.requested.origin.latitude
      && state.presented.origin.longitude === state.requested.origin.longitude) break;
    if (performance.now() >= deadline) throw new Error("City detail terrain presentation timed out");
    await new Promise(resolve => requestAnimationFrame(resolve));
  }
  runtime.wasm_command(JSON.stringify({type:"regional-map", command:{
    type:"install-city", document_json:document, preparation:ticket,
  }}));
  while (true) {
    signal.throwIfAborted();
    const status = JSON.parse(runtime.wasm_regional_map_status()).city_installation;
    if (status?.preparation.owner === ticket.owner
      && status.preparation.sequence === ticket.sequence) {
      if (status.phase === "ready") return;
      if (status.phase === "failed") throw new Error(`City detail unavailable (${status.error})`);
    }
    if (performance.now() >= deadline) throw new Error("City detail installation timed out");
    await new Promise(resolve => requestAnimationFrame(resolve));
  }
}

//! Admit an opaque complete preparation at the native map installation boundary.
use super::*;
use crate::presentation::generation::activate_city;
use adventuresim_tactical_core::regional_city::RegionalCityInput;

enum Admission {
    Resident,
    Replacement(Box<InstalledCity>),
}

pub(in crate::presentation::regional_map) fn install(
    world: &mut World,
    json: &str,
    preparation: PreparationTicket,
) {
    let result = admit(world, json, preparation);
    let retired = {
        let mut state = world.resource_mut::<MapState>();
        match result {
            Ok(Admission::Resident) => {
                state.city.status = Some(InstallationStatus {
                    preparation,
                    phase: InstallationPhase::Ready,
                    error: None,
                });
                None
            }
            Ok(Admission::Replacement(city)) => {
                let old = state.city.pending.replace(*city);
                state.city.status = Some(InstallationStatus {
                    preparation,
                    phase: InstallationPhase::Preparing,
                    error: None,
                });
                state.city.settled_frames = 0;
                old.map(|old| old.root)
            }
            Err(error) => {
                state.city.status = Some(InstallationStatus::failed(preparation, error));
                None
            }
        }
    };
    if let Some(root) = retired
        && let Ok(entity) = world.get_entity_mut(root)
    {
        entity.despawn();
    }
}

fn admit(
    world: &mut World,
    json: &str,
    preparation: PreparationTicket,
) -> std::result::Result<Admission, InstallationFailure> {
    let document: RegionalCityInput = serde_json::from_str(json).map_err(|error| {
        warn!(%error, "Invalid focused city document");
        InstallationFailure::Input
    })?;
    let state = world.resource::<MapState>();
    let origin = state
        .presented
        .as_ref()
        .filter(|surface| &surface.source == document.source())
        .filter(|_| state.requested_city() == Some(document.place()))
        .map(|surface| surface.request.origin)
        .ok_or(InstallationFailure::Focus)?;
    let product = activate_city(preparation, &document).map_err(|error| {
        warn!(%error, "Could not activate focused city preparation");
        InstallationFailure::Preparation
    })?;
    let residency = &world.resource::<MapState>().city;
    if residency.pending.is_none()
        && residency
            .installed
            .as_ref()
            .is_some_and(|city| Arc::ptr_eq(&city.product, &product))
    {
        return Ok(Admission::Resident);
    }
    let frame = CityFrame::from_geographic_city(&document, origin);
    let owner = PresentationOwner::RegionalMap;
    let root = world
        .spawn((
            Name::new("Focused map city"),
            owner,
            owner.render_layers(),
            Transform::from_matrix(frame.world_from_city()),
            Visibility::Hidden,
        ))
        .id();
    let installation = FocusedGround::install(world, &product, root, frame)
        .map_err(|error| {
            warn!(%error, "Could not install canonical city ground");
            InstallationFailure::Ground
        })
        .and_then(|ground| {
            buildings::queue_focused_city(world, &document, root, origin).map_err(|error| {
                warn!(%error, "Could not queue complete focused city");
                InstallationFailure::Buildings
            })?;
            Ok(InstalledCity {
                root,
                product,
                ground,
                frame,
            })
        });
    if installation.is_err()
        && let Ok(entity) = world.get_entity_mut(root)
    {
        entity.despawn();
    }
    installation.map(|city| Admission::Replacement(Box::new(city)))
}

//! One focused city, published only after its exact GPU candidate is installed.
use super::{MapState, surface::SurfaceCoverage};
use crate::presentation::{
    buildings::{self, CityAssemblyFailure, CityAssemblyPublished, CityFrame},
    generation::{PreparationTicket, PreparedCityProduct},
    ownership::PresentationOwner,
    terrain::TacticalTerrainMaterial,
    vista::{CityGroundMaterial, focused::FocusedGround},
};
use adventuresim_tactical_core::{
    regional_terrain::REGIONAL_TERRAIN_SIDE, scene_coordinates::ScenePlanPoint,
};
use adventuresim_world_schema::coordinates::{
    Wgs84CoordinateMicrodegrees, terrain_projection::NativeTerrainCoordinate,
};
use bevy::prelude::*;
use serde::Serialize;
use std::sync::Arc;

mod installation;
pub(super) use installation::install;

const SETTLED_CITY_FRAMES: usize = 4;

#[derive(Default)]
pub(super) struct CityResidency {
    pending: Option<InstalledCity>,
    installed: Option<InstalledCity>,
    pub status: Option<InstallationStatus>,
    pub visible: bool,
    settled_frames: usize,
}

struct InstalledCity {
    root: Entity,
    product: Arc<PreparedCityProduct>,
    ground: FocusedGround,
    frame: CityFrame,
}

#[derive(Clone, Copy)]
pub(super) struct CitySurface<'a> {
    pub root: Entity,
    pub frame: CityFrame,
    pub support: &'a crate::presentation::vista::streets::GroundSupport,
}

#[derive(Clone, Copy, Serialize)]
pub(super) struct InstallationStatus {
    pub preparation: PreparationTicket,
    pub phase: InstallationPhase,
    pub error: Option<InstallationFailure>,
}

#[derive(Clone, Copy, Serialize)]
#[serde(rename_all = "kebab-case")]
pub(super) enum InstallationPhase {
    Preparing,
    Ready,
    Failed,
}

#[derive(Clone, Copy, Serialize)]
#[serde(rename_all = "kebab-case")]
pub(super) enum InstallationFailure {
    Input,
    Focus,
    Preparation,
    Ground,
    Buildings,
    Assembly,
}

impl InstallationStatus {
    fn failed(preparation: PreparationTicket, error: InstallationFailure) -> Self {
        Self {
            preparation,
            phase: InstallationPhase::Failed,
            error: Some(error),
        }
    }
}

impl MapState {
    pub(super) fn city_surface(&self) -> Option<CitySurface<'_>> {
        if !self.city.visible {
            return None;
        }
        let city = self.city.installed.as_ref()?;
        Some(CitySurface {
            root: city.root,
            frame: city.frame,
            support: &city.ground.support,
        })
    }

    pub(super) fn ground_position(&self, origin: NativeTerrainCoordinate) -> Option<Vec3> {
        if self.city.visible {
            return self.city_position(origin);
        }

pub(super) fn sync(world: &mut World) {
    world.resource_scope(|world, mut state: Mut<MapState>| {
        publish_candidate(world, &mut state.city);
        let mut draw_city = state
            .city
            .installed
            .as_ref()
            .is_some_and(|city| city.covers(&state));
        let origin = state
            .presented
            .as_ref()
            .map(|surface| surface.request.origin);
        let replaced = state
            .city
            .pending
            .as_ref()
            .is_some_and(|pending| world.get::<CityAssemblyPublished>(pending.root).is_some());
        if let (Some(city), Some(origin)) = (state.city.installed.as_mut(), origin) {
            // A staged replacement owns its frame once assembly publishes.
            // Do not reanchor old ground against the new candidate's buffers.
            if replaced {
                draw_city = false;
            } else if let Err(error) = city.reanchor(world, origin) {
                warn!(%error, "Could not reanchor map city");
                draw_city = false;
            }
            if let Some(mut visibility) = world.get_mut::<Visibility>(city.root) {
                *visibility = if draw_city {
                    Visibility::Inherited
                } else {
                    Visibility::Hidden
                };
            }
        }
        buildings::set_city_visible(world, PresentationOwner::RegionalMap, draw_city);
        // Keep the already-settled regional ground underneath while the first
        // fine-ground pipelines specialize. Height queries exchange only after
        // the candidate has rendered enough settled frames to replace it.
        let visible = draw_city && state.city.settled_frames >= SETTLED_CITY_FRAMES;
        if let Some(surface) = state.presented.as_ref()
            && let SurfaceCoverage::Drawn { entity, .. } = surface.coverage
            && let Some(mut visibility) = world.get_mut::<Visibility>(entity)
        {
            *visibility = if visible {
                Visibility::Hidden
            } else {
                Visibility::Inherited
            };
        }
        if state.city.visible != visible {
            state.city.visible = visible;
            state.settled_frames = 0;
        }
        if draw_city
            && state.city.pending.is_none()
            && state.city.installed.is_some()
            && crate::presentation::pipeline_readiness::waiting_pipelines() == 0
        {
            state.city.settled_frames = state
                .city
                .settled_frames
                .saturating_add(1)
                .min(SETTLED_CITY_FRAMES);
            if state.city.settled_frames == SETTLED_CITY_FRAMES
                && let Some(status) = &mut state.city.status
                && matches!(status.phase, InstallationPhase::Preparing)
            {
                status.phase = InstallationPhase::Ready;
            }
        } else {
            state.city.settled_frames = 0;
        }
    });
}

fn publish_candidate(world: &mut World, residency: &mut CityResidency) {
    let Some(pending) = residency.pending.as_ref() else {
        return;
    };
    if let Some(error) = world.get::<CityAssemblyFailure>(pending.root) {
        warn!(error = %error.0, "Could not assemble focused map city");
        let root = pending.root;
        residency.pending = None;
        if let Some(status) = &mut residency.status {
            *status = InstallationStatus::failed(status.preparation, InstallationFailure::Assembly);
        }
        if let Ok(entity) = world.get_entity_mut(root) {
            entity.despawn();
        }
        return;
    }
    if world.get::<CityAssemblyPublished>(pending.root).is_none()
        || !buildings::city_gpu_ready(PresentationOwner::RegionalMap)
    {
        return;
    }
    if let Some(pending) = residency.pending.take()
        && let Some(old) = residency.installed.replace(pending)
        && let Ok(entity) = world.get_entity_mut(old.root)
    {
        entity.despawn();
    }
    residency.settled_frames = 0;
}

