147:     time: Res<Time>,
148:     mut state: ResMut<MissionState>,
149:     mut exit: MessageWriter<AppExit>,
150: ) {
165:     if let Some(outcome) = state.advance_terminal_presentation(time.delta()) {
166:         info!(?outcome, "Terminal presentation complete; shutting down");
167:         exit.write(AppExit::Success);
168:     }
169: }
