59: async fn evidence_at_site(
60:     state: &AppState,
61:     character_id: u64,
62:     case_site_id: &str,
63: ) -> Result<Vec<EvidenceView>, StatusCode> {
64:     let character = super::data::character(state, character_id)
65:         .await
66:         .map_err(|_| StatusCode::SERVICE_UNAVAILABLE)?
67:         .ok_or(StatusCode::UNAUTHORIZED)?;
68:     if character.current_case_site_id.as_deref() != Some(case_site_id) {
69:         return Err(StatusCode::FORBIDDEN);
70:     }
71:     let mut evidence = state
72:         .db
73:         .query_sats::<BackendPhysicalEvidence>(&format!(
74:             "SELECT * FROM backend_physical_evidence WHERE owner_character_id = {character_id} AND case_site_id = {}",
75:             sql_string_literal(case_site_id)
76:         ))
77:         .await
78:         .map_err(|_| StatusCode::SERVICE_UNAVAILABLE)?;
79:     let inspections = state
80:         .db
81:         .query_sats::<BackendPhysicalEvidenceInspection>(&format!(
82:             "SELECT * FROM backend_physical_evidence_inspections WHERE owner_character_id = {character_id}"
83:         ))
84:         .await
85:         .map_err(|_| StatusCode::SERVICE_UNAVAILABLE)?;
86:     let deductions = state
87:         .db
88:         .query_sats::<BackendBestiaryDeduction>(&format!(
89:             "SELECT * FROM backend_bestiary_deductions WHERE owner_character_id = {character_id}"
90:         ))
91:         .await
92:         .map_err(|_| StatusCode::SERVICE_UNAVAILABLE)?;
93:     evidence.sort_by(|left, right| {
94:         (&left.label, &left.evidence_id).cmp(&(&right.label, &right.evidence_id))
95:     });
96:     Ok(evidence
97:         .into_iter()
98:         .map(|item| {
99:             let mut item_inspections = inspections
100:                 .iter()
101:                 .filter(|attempt| attempt.evidence_id == item.evidence_id)
102:                 .cloned()
103:                 .collect::<Vec<_>>();
104:             item_inspections.sort_by_key(|attempt| {
105:                 (
106:                     crate::spacetimedb::calendar_minute(&attempt.attempted_at),
107:                     attempt.attempt_id.clone(),
108:                 )
109:             });
110:             EvidenceView {
111:                 id: item.evidence_id,
112:                 label: item.label,
113:                 portrait_icon: item.portrait_icon,
114:                 description: item.description,
115:                 topics: serde_json::from_str(&item.topics_json).unwrap_or_default(),
116:                 deductions: deductions
117:                     .iter()
118:                     .filter(|deduction| deduction.case_id == item.case_id)
119:                     .map(|deduction| EvidenceDeductionView {
120:                         monster_kind: deduction.monster_kind.clone(),
121:                         support_band: deduction.support_band.clone(),
122:                         provenance: deduction.provenance(),
123:                     })
124:                     .collect(),
125:                 inspections: item_inspections
126:                     .into_iter()
127:                     .map(|attempt| EvidenceInspectionView {
128:                         attempt_id: attempt.attempt_id,
129:                         topic_id: attempt.topic_id,
130:                         stat_label: attempt.stat_label,
131:                         passed: attempt.passed,
132:                         narration: attempt.narration,
133:                     })
134:                     .collect(),
135:             }
136:         })
137:         .collect())
138: }
