158: async fn inspect(
159:     State(state): State<AppState>,
160:     Path(case_site_id): Path<String>,
161:     session: Session,
162:     Json(request): Json<InspectRequest>,
163: ) -> Result<Json<EvidenceView>, StatusCode> {
164:     let character_id = session.character_id_u64().ok_or(StatusCode::UNAUTHORIZED)?;
165:     // Validate location and observer-safe availability before invoking private
166:     // authority. The reducer repeats the position and topic checks.
167:     if !evidence_at_site(&state, character_id, &case_site_id)
168:         .await?
169:         .iter()
170:         .any(|item| item.id == request.evidence_id)
171:     {
172:         return Err(StatusCode::NOT_FOUND);
173:     }
174:     state
175:         .db
176:         .call(
177:             "inspect_physical_evidence",
178:             &[
179:                 json!(character_id),
180:                 json!(&request.evidence_id),
181:                 json!(&request.topic_id),
182:                 json!(&request.action_id),
183:             ],
184:         )
185:         .await
186:         .map_err(|error| {
187:             tracing::warn!(
188:                 %error,
189:                 character_id,
190:                 evidence_id = %request.evidence_id,
191:                 topic_id = %request.topic_id,
192:                 "physical-evidence inspection was rejected"
193:             );
194:             StatusCode::CONFLICT
195:         })?;
196:     evidence_at_site(&state, character_id, &case_site_id)
197:         .await?
198:         .into_iter()
199:         .find(|item| item.id == request.evidence_id)
200:         .map(Json)
201:         .ok_or(StatusCode::NOT_FOUND)
202: }
