247: pub fn backend_physical_evidence(ctx: &ViewContext) -> Vec<BackendPhysicalEvidence> {
248:     if !is_gateway(ctx) {
249:         return Vec::new();
250:     }
251:     let pins = backend_case_site_pins(ctx);
252:     let mut rows = Vec::new();
253:     for pin in pins {
254:         let mut authorities = ctx
255:             .db
256:             .quest_generation_authority()
257:             .public_case_id()
258:             .filter(&pin.case_id)
259:             .filter_map(|authority| validate_quest_generation_authority(&authority).ok())
260:             .collect::<Vec<_>>();
261:         authorities.sort_by(|left, right| {
262:             left.manifest
263:                 .canonical_case_id
264:                 .cmp(&right.manifest.canonical_case_id)
265:         });
266:         authorities.dedup_by(|left, right| {
267:             left.manifest.canonical_case_id == right.manifest.canonical_case_id
268:         });
269:         let [validated] = authorities.as_slice() else {
270:             continue;
271:         };
272:         for generated in &validated.manifest.evidence {
273:             if generated.site_id.0 != pin.case_site_id.as_str() {
274:                 continue;
275:             }
276:             let Some(authority) = ctx
277:                 .db
278:                 .investigation_evidence_authority()
279:                 .id()
280:                 .find(&generated.id.0)
281:                 .filter(|row| {
282:                     row.case_id == validated.manifest.canonical_case_id
283:                         && row.presentation_kind == EvidencePresentationKind::Physical
284:                 })
285:             else {
286:                 continue;
287:             };
288:             let topics = generated
289:                 .inspection_topics
290:                 .iter()
291:                 .map(|topic| {
292:                     serde_json::json!({
293:                         "id": topic.id,
294:                         "label": topic.label,
295:                     })
296:                 })
297:                 .collect::<Vec<_>>();
298:             let Ok(topics_json) = serde_json::to_string(&topics) else {
299:                 continue;
300:             };
301:             rows.push(BackendPhysicalEvidence {
302:                 owner_character_id: pin.owner_character_id,
303:                 evidence_id: authority.id,
304:                 case_id: pin.case_id.clone(),
305:                 case_site_id: pin.case_site_id.clone(),
306:                 label: generated.portrait_label.clone(),
307:                 portrait_icon: generated.portrait_icon.clone(),
308:                 description: generated.base_description.clone(),
309:                 topics_json,
310:             });
311:         }
312:     }
313:     rows.sort_by(|left, right| {
314:         (
315:             left.owner_character_id,
316:             &left.case_site_id,
317:             &left.evidence_id,
318:         )
319:             .cmp(&(
320:                 right.owner_character_id,
