86:             .query_sats_into::<DbItem, CatalogItemView>("SELECT * FROM item"),
87:     );
88:     let mut worn = worn.unwrap_or_default();
89:     let worn_ids = worn
90:         .iter()
91:         .map(|row| row.inventory_item_id)
