142:                 free_capacity: point.capacity.saturating_sub(used),
143:                 order: point.order,
144:             });
145:         }
146:     }
147:     attachment_targets.sort_by_key(|target| {
148:         (
149:             target.parent_inventory_item_id,
150:             target.order,
151:             target.attachment_point_id.clone(),
152:         )
153:     });
154:     vec![CharacterEquipmentGraph {
