168: pub(super) async fn finalize_merchant_offer(
169:     State(state): State<AppState>,
170:     Path((id, place)): Path<(String, String)>,
171:     session: Session,
172:     Form(form): Form<MerchantOfferForm>,
173: ) -> Redirect {
174:     let Some(service_id) = crate::location_urls::place_service(&place) else {
175:         return Redirect::to(&crate::location_urls::LocationKind::Settlement.path(&id));
176:     };
177:     let Some(location_id) = merchant_service_location(service_id) else {
178:         return Redirect::to(&paths::MERCHANTS.url([&id]));
179:     };
180:     let fallback = paths::SETTLEMENT_PLACE.url([&id, &place]);
181:     let mut trade_completed = false;
182:     if let Some((character, _)) = get_active_character(&state, session.character_id_u64()).await
183:         && let (Ok(buys), Ok(sells)) = (form.buys(), form.sells())
184:     {
185:         let (items, quantities): (Vec<_>, Vec<_>) = buys
186:             .into_iter()
187:             .map(|entry| (entry.id, entry.quantity))
188:             .unzip();
189:         let (sell_ids, sell_quantities): (Vec<_>, Vec<_>) = sells
190:             .into_iter()
191:             .map(|entry| (entry.id, entry.quantity))
192:             .unzip();
193:         let provider_resident_character_id =
194:             merchant_provider_id(&state, &id, service_id, location_id).await;
195:         if items.is_empty() && sell_ids.is_empty() {
196:             trade_completed = true;
197:         } else if let Some(provider_resident_character_id) = provider_resident_character_id {
198:             match state
199:                 .db
200:                 .call(
201:                     "finalize_storefront_trade",
202:                     &[
203:                         json!(character.id),
204:                         json!(&id),
205:                         json!(&service_id),
206:                         json!(provider_resident_character_id),
207:                         json!(items),
208:                         json!(quantities),
209:                         json!(sell_ids),
210:                         json!(sell_quantities),
211:                         json!(form.inventory_scope == "party"),
212:                     ],
213:                 )
214:                 .await
215:             {
216:                 Ok(()) => trade_completed = true,
217:                 Err(error) => {
218:                     tracing::warn!(%error, settlement_id = %id, "merchant offer was rejected");
219:                 }
220:             }
221:         }
222:     }
223:     if trade_completed {
224:         redirect_to_local(&form.return_to, &fallback)
225:     } else {
226:         Redirect::to(&fallback)
227:     }
228: }

