1: //! Dependency capture and job discovery within a preparation ticket.
2: use super::*;
3: 
4: pub(super) fn venue_jobs(
5:     ticket: PreparationTicket,
6:     input_json: &str,
7:     view_json: &str,
8: ) -> PreparationResult<Vec<String>> {
9:     ticket.require_owner(PresentationOwner::Scene)?;
10:     let input: TacticalSceneInput = serde_json::from_str(input_json)?;
11:     let request: venue::VenueRequest = serde_json::from_str(view_json)?;
12:     let mut products = staged_products(ticket)?;
13:     products.placements = request.placements(&input);
14:     // Retain semantic products independently of meshes, which live in Bevy's
15:     // asset cache. Bound CPU recipe retention across an extended journey.
16:     while products.venues.len() > RETAINED_VENUE_RECIPES {
17:         products.venues.remove(0);
18:     }
19:     let mut programs = Vec::new();
20:     for placement in &products.placements {
21:         if !programs.contains(&placement.program)
22:             && !products
23:                 .venues
24:                 .iter()
25:                 .any(|v| v.recipe.program == placement.program)
26:         {
27:             programs.push(placement.program.clone());
28:         }
29:     }
30:     programs
31:         .into_iter()
32:         .map(|p| {
33:             serde_json::to_string(&GenerationJob::Venue(Box::new(p)))
34:                 .map_err(PreparationError::from)
35:         })
36:         .collect()
37: }
38: 
39: pub(super) fn dependencies(
40:     ticket: PreparationTicket,
41:     job_json: &str,
42: ) -> PreparationResult<Vec<u8>> {
43:     let job: GenerationJob = serde_json::from_str(job_json)?;
44:     job.require_owner(ticket)?;
45:     let products = staged_products(ticket)?;
46:     let mut data = Dependencies::default();
47:     match job {
48:         GenerationJob::Venue(program) => {
49:             data.recipe = products
50:                 .scene
51:                 .iter()
52:                 .flat_map(|s| &s.buildings)
53:                 .find(|b| b.placement.program == *program)
54:                 .map(
55:                     |b| adventuresim_tactical_core::scene_input::GeneratedBuildingRecipe {
56:                         program: b.placement.program.clone(),
57:                         plan: b.plan.clone(),
58:                         collision: b.collision.clone(),
59:                     },
60:                 );
61:         }
62:         GenerationJob::Building(_) | GenerationJob::RegionalCity { .. } => {}
63:     }
64:     let mut bytes = Vec::new();
65:     ciborium::into_writer(&data, &mut bytes).map_err(PreparationError::DependenciesEncode)?;
66:     Ok(bytes)
67: }
