31:   signal?.throwIfAborted();
32:   const started = performance.now();
33:   const preparation = runtime.wasm_begin_generation(JSON.stringify(owner));
34:   let completed = false, cache, pool;
35:   const cancel = () => pool?.close();
36:   signal?.addEventListener("abort", cancel, { once: true });
37:   try {
38:     const metrics = { jobs: 0, workers: 0, bytes: 0, workerMilliseconds: 0,
