40:       milliseconds: 0, cacheHits: 0, cacheMisses: 0, cacheLookupMilliseconds: 0,
41:       jobDiscoveryMilliseconds: 0, finishMilliseconds: 0, workerInitializationMilliseconds: 0,
42:       cacheWritesAccepted: 0, cacheWritesReplaced: 0, cacheWriteRejections: {} };
43:     (window.strategicGenerationMetrics ||= {})[owner] = metrics;
44:     const discover = action => {
45:       const started = performance.now();
46:       const jobs = JSON.parse(action());
47:       metrics.jobDiscoveryMilliseconds += performance.now() - started;
48:       return jobs;
49:     };
50:     const receive = (job, bytes) => {
