57:     pool = createGenerationPool(runtime.generationModule);
58:     signal?.throwIfAborted();
59:     // A cache miss starts generation immediately; unrelated cache reads must
60:     // not postpone the destination's critical scene job. Workers are lazy, so
61:     // a completely cached destination never instantiates another Wasm runtime.
62:     const run = async jobs => {
63:       metrics.jobs += jobs.length;
64:       const result = await pool.run(jobs,
65:       ({ job, bytes, workerMilliseconds }) => {
66:         receive(job, bytes);
67:         metrics.workerMilliseconds += workerMilliseconds;
68:         const admission = cache.put(job, bytes);
69:         if (admission.status === "accepted") {
70:           metrics.cacheWritesAccepted++;
71:           if (admission.disposition === "replaced") metrics.cacheWritesReplaced++;
72:         } else {
73:           metrics.cacheWriteRejections[admission.reason] =
74:             (metrics.cacheWriteRejections[admission.reason] ?? 0) + 1;
