89:           catch (error) {
90:             signal.throwIfAborted();
91:             if (!invalidCachedProductCodes.has(error?.name)) throw error;
92:             await cache.remove(job);
93:           }
94:         }
95:         signal.throwIfAborted();
96:         metrics.cacheMisses++;
97:         return { status: "generate", job };
98:       } });
99:       metrics.workers += result.createdWorkers;
100:       metrics.workerInitializationMilliseconds += result.initializationMilliseconds;
