157: pub(super) fn begin(owner: PresentationOwner) -> PreparationResult<PreparationTicket> {
158:     let mut residency = residency()?;
159:     let sequence = residency
160:         .next_sequence
161:         .checked_add(1)
162:         .and_then(NonZeroU32::new)
163:         .ok_or(PreparationError::SequenceExhausted)?;
164:     residency.next_sequence = sequence.get();
165:     let ticket = PreparationTicket { owner, sequence };
166:     let slot = residency.owner_mut(owner);
167:     // Large immutable scene and geometry buffers are shared. Preparation owns
168:     // its mutable bindings; installed assets remain available until activation.
169:     slot.staged = slot.active.clone();
170:     slot.staged.begin_generation();
171:     slot.preparing = Some(ticket);
172:     Ok(ticket)
173: }
