175: pub(super) fn finish(
176:     ticket: PreparationTicket,
177:     input: &TacticalSceneInput,
178: ) -> PreparationResult<()> {
179:     ticket.require_owner(PresentationOwner::Scene)?;
180:     let input_document = input;
181:     let input = PreparationInputIdentity::from_input(input_document)?;
182:     let mut residency = residency()?;
183:     let slot = residency.owner_mut(ticket.owner);
184:     if slot.preparing != Some(ticket) {
185:         return Err(PreparationError::StalePreparation);
186:     }
187:     slot.staged.scene = Some(std::sync::Arc::new(PreparedStrategicScene::from_products(
188:         input_document,
189:         &slot.staged,
190:     )?));
191:     slot.finish(ticket, input)
192: }
