    pub fn requested_window(&self) -> Result<Option<RegionalTerrainRequest>> {
        let Some(rect) = self.rect else {
            return Ok(None);
        };
        let aspect = f64::from(rect.full_width.max(1)) / f64::from(rect.full_height.max(1));
        let width = f64::from(self.span.metres()) * aspect;
        let height = f64::from(self.span.metres()) / f64::from(MAP_PITCH_RADIANS.sin());
        let yaw = f64::from(self.yaw.radians());
        let east_extent = width * yaw.cos().abs() + height * yaw.sin().abs();
        let north_extent = width * yaw.sin().abs() + height * yaw.cos().abs();
        let needed = east_extent.max(north_extent) * WINDOW_COVERAGE_MARGIN;
        let scale = [
            RegionalTerrainScale::Neighborhood,
            RegionalTerrainScale::District,
            RegionalTerrainScale::Region,
            RegionalTerrainScale::Country,
            RegionalTerrainScale::Continent,
        ]
        .into_iter()
        .find(|scale| {
            f64::from(scale.spacing_metres()) * (REGIONAL_TERRAIN_SIDE - 1) as f64 >= needed
        })
        .unwrap_or(RegionalTerrainScale::Continent);
        let home = NativeTerrainCoordinate::from(self.home.to_e7());
        let offset = home.offset_to(self.origin);
        let step = f64::from(scale.spacing_metres()) * WINDOW_CENTER_STEP_CELLS as f64;
        let point = home.at_offset(
            (offset.east_metres / step).round() * step,
            (offset.north_metres / step).round() * step,
        );
        Ok(Some(RegionalTerrainRequest {
            origin: geographic_origin(point)?,
            scale,
        }))
    }
}

fn geographic_origin(point: NativeTerrainCoordinate) -> Result<Wgs84CoordinateMicrodegrees> {
    let point = bounded_origin(point)?;
    Wgs84CoordinateMicrodegrees::from_longitude_latitude_degrees(
        point.longitude_degrees,
        point.latitude_degrees,
    )
    .ok_or(MapProtocolError::Origin)
}

fn bounded_origin(point: NativeTerrainCoordinate) -> Result<NativeTerrainCoordinate> {
    if !point.longitude_degrees.is_finite() || !point.latitude_degrees.is_finite() {
        return Err(MapProtocolError::Origin);
    }
    Ok(NativeTerrainCoordinate {
        longitude_degrees: point.longitude_degrees.clamp(
            LongitudeMicrodegrees::MIN.degrees(),
            LongitudeMicrodegrees::MAX.degrees(),
        ),
        latitude_degrees: point.latitude_degrees.clamp(
            LatitudeMicrodegrees::MIN.degrees(),
            LatitudeMicrodegrees::MAX.degrees(),
        ),
    })
}

//! Read-only bounded terrain capture, independent of settlements and simulation.
use crate::terrain_sampling::environment_sample;
use adventuresim_tactical_core::regional_terrain::{
    REGIONAL_TERRAIN_SIDE, REGIONAL_TERRAIN_VERTICES, RegionalTerrain, RegionalTerrainError,
    RegionalTerrainRequest, RegionalTerrainVertex,
};
use adventuresim_terrain::TerrainPack;
use adventuresim_world_schema::ElevationMeters;
use adventuresim_world_schema::coordinates::terrain_projection::NativeTerrainCoordinate;
use adventuresim_world_schema::source_package::{SourcePackageDigest, SourcePackageDigestError};

pub type Result<T> = std::result::Result<T, RegionalTerrainCaptureError>;

#[derive(Debug, thiserror::Error)]
pub enum RegionalTerrainCaptureError {
    #[error(transparent)]
    Terrain(#[from] adventuresim_terrain::Error),
    #[error(transparent)]
    Admission(#[from] RegionalTerrainError),
    #[error(transparent)]
    Source(#[from] SourcePackageDigestError),
    #[error("terrain source elevation {metres} is outside the supported geographic range")]
    Elevation { metres: i16 },
}

pub fn capture(pack: &TerrainPack, request: RegionalTerrainRequest) -> Result<RegionalTerrain> {
    let source = SourcePackageDigest::from_hex(pack.digest())?;
    let center = (REGIONAL_TERRAIN_SIDE - 1) as f64 * 0.5;
    let spacing = f64::from(request.scale.spacing_metres());
    let origin = NativeTerrainCoordinate::from(request.origin.to_e7());
    let mut vertices = Vec::with_capacity(REGIONAL_TERRAIN_VERTICES);
    for row in 0..REGIONAL_TERRAIN_SIDE {
        for column in 0..REGIONAL_TERRAIN_SIDE {
            // TerrainPack's native numerical kernel takes continuous degrees and
            // scene-local east/north metres; no intermediate coordinate rounding.
            let point = origin.at_offset(
                (column as f64 - center) * spacing,
                (row as f64 - center) * spacing,
            );
            let vertex = pack
                .cell(point.latitude_degrees, point.longitude_degrees)?
                .map(|cell| -> Result<RegionalTerrainVertex> {
                    Ok(RegionalTerrainVertex {
                        elevation: ElevationMeters::new(cell.elevation_m).ok_or(
                            RegionalTerrainCaptureError::Elevation {
                                metres: cell.elevation_m,
                            },
                        )?,
                        environment: environment_sample(cell),
                    })
                })
                .transpose()?;
            vertices.push(vertex);
        }
    }
    Ok(RegionalTerrain::new(request, source, vertices)?)
}

