91: /// Correspondence read back to the host.
92: #[derive(Clone, Debug, Default, PartialEq)]
93: pub struct Skin {
94:     pub texcoords: Vec<[f32; 2]>,
95:     pub joint_indices: fabelgeist_rig::PackedRigSkin<8>,
