99: impl Skin {
100:     /// Add `other`'s points after this skin's, matching an appended part.
101:     pub fn append(&mut self, other: Skin) -> Result<(), GenerateError> {
102:         self.joint_indices.append(other.joint_indices)?;
103:         self.texcoords.extend(other.texcoords);
104:         self.joint_weights.extend(other.joint_weights);
105:         Ok(())
106:     }
107: }
108: 
109: impl Correspondence {
110:     /// Record, for each of `count` points, the nearest body vertex and its
111:     /// attributes.
112:     pub fn record(
113:         gpu: &ArmorGpu,
114:         batch: &mut KernelBatch,
115:         body: &GpuBody,
116:         points: &Buffer,
117:         count: u32,
118:     ) -> Result<Self, GenerateError> {
119:         let hits = QueryHits::new(gpu.context(), count).map_err(device_error)?;
120:         gpu.query()
121:             .record_nearest_points(
122:                 batch,
123:                 points,
124:                 count,
125:                 PointTargets {
126:                     positions: &body.positions,
127:                     candidates: None,
128:                     count: body.vertex_count,
129:                 },
130:                 &hits,
131:             )
132:             .map_err(device_error)?;
133:         let correspondence = Self {
134:             texcoords: gpu.scratch(count as u64 * 8, "armor texcoords")?,
135:             joint_indices: gpu.scratch(count as u64 * 32, "armor joint indices")?,
136:             joint_weights: gpu.scratch(count as u64 * 32, "armor joint weights")?,
137:             hits,
138:             count,
139:             joints: body.joint_count,
140:         };
141:         let mut gather = PassParameters::new();
142:         gather.insert("count", count);
143:         for pad in ["pad0", "pad1", "pad2"] {
144:             gather.insert(pad, 0u32);
145:         }
146:         gather.insert("nearest", correspondence.hits.nearest.clone());
147:         gather.insert("body_texcoords", body.texcoords.clone());
148:         gather.insert("body_joint_indices", body.joint_indices.clone());
149:         gather.insert("body_joint_weights", body.joint_weights.clone());
150:         gather.insert("texcoords", correspondence.texcoords.clone());
151:         gather.insert("joint_indices", correspondence.joint_indices.clone());
152:         gather.insert("joint_weights", correspondence.joint_weights.clone());
153:         batch
154:             .dispatch_items(&*gather_kernel(gpu)?, &gather, count)
155:             .map_err(device_error)?;
156:         Ok(correspondence)
157:     }
158: 
159:     /// Read back after the batch has been submitted.
160:     pub fn read(&self, gpu: &ArmorGpu) -> Result<Skin, GenerateError> {
161:         let mut staging = Staging::new();
162:         let slots = self.stage(&mut staging);
163:         self.finish(&gpu.read_staged(staging)?, slots)
164:     }
165: 
166:     /// Stage the skin for a shared readback.
167:     pub fn stage<'a>(&'a self, staging: &mut Staging<'a>) -> [Staged; 3] {
168:         [
169:             staging.stage(&self.texcoords),
170:             staging.stage(&self.joint_indices),
171:             staging.stage(&self.joint_weights),
172:         ]
173:     }
