15: pub(super) async fn profile(
16:     state: &AppState,
17:     settlement: &SettlementView,
18: ) -> Result<SettlementSceneProfile, StatusCode> {
19:     Ok(SettlementSceneProfile {
20:         operators: operators(state, &settlement.id).await?,
21:         id: settlement.id.clone(),
