28: async fn operators(
29:     state: &AppState,
30:     settlement: &str,
31: ) -> Result<Vec<SettlementBusinessOperatorProfile>, StatusCode> {
32:     let assignments = state
33:         .db
34:         .query_sats::<sdk::SettlementBusinessOperator>(&format!(
35:             "SELECT * FROM settlement_business_operator WHERE settlement_id = {}",
36:             spacetimedb::sql_string_literal(settlement),
37:         ))
38:         .await
39:         .map_err(unavailable)?;
40:     if assignments.is_empty() {
41:         return Ok(Vec::new());
42:     }
43:     let condition = assignments
44:         .iter()
45:         .map(|row| format!("id = {}", row.operator_character_id))
46:         .collect::<Vec<_>>()
47:         .join(" OR ");
48:     let people = state
49:         .db
50:         .query_sats_into::<sdk::Character, CharacterView>(&format!(
51:             "SELECT * FROM character WHERE {condition}"
52:         ))
53:         .await
54:         .map_err(unavailable)?;
55:     assignments
56:         .into_iter()
57:         .map(|row| {
58:             if row.business_id.settlement_id != settlement {
59:                 return Err(StatusCode::SERVICE_UNAVAILABLE);
60:             }
61:             let person = people
62:                 .iter()
63:                 .find(|person| person.id == row.operator_character_id)
64:                 .ok_or(StatusCode::SERVICE_UNAVAILABLE)?;
65:             Ok(SettlementBusinessOperatorProfile {
66:                 business_id: BusinessId::new(
67:                     settlement,
68:                     BusinessKey {
69:                         usage: building_use(&row.business_id.key.usage),
70:                         ordinal: row.business_id.key.ordinal,
71:                     },
72:                 ),
73:                 operator_character_id: adventuresim_tactical_core::player::CharacterId(person.id),
74:                 operator_name: RenderedPersonalName::try_from(person.name.clone())
75:                     .map_err(unavailable)?,
76:             })
77:         })
78:         .collect()
79: }
