81: pub(super) async fn scene_minute(
82:     state: &AppState,
83: ) -> Result<adventuresim_world_schema::calendar::StrategicMinute, StatusCode> {
84:     let clock = state
85:         .db
86:         .query_sats::<sdk::WorldClock>(&spacetimedb::world_clock_singleton())
87:         .await
88:         .map_err(unavailable)?
89:         .into_iter()
90:         .next()
91:         .ok_or(StatusCode::SERVICE_UNAVAILABLE)?;
92:     let now = std::time::SystemTime::now()
93:         .duration_since(std::time::UNIX_EPOCH)
94:         .map_err(unavailable)?
95:         .as_micros();
96:     let minute = adventuresim_core::strategic_time::official_minute(
97:         clock.epoch_micros,
98:         i64::try_from(now).map_err(unavailable)?,
99:     );
100:     Ok(minute)
101: }
