pub(crate) fn requires_stable_object(
    definition: Option<&Item>,
    food: bool,
    measured: bool,
) -> bool {
    food || measured
        || definition.is_some_and(|definition| {
            definition.repairable
                || definition.kind == CatalogItemKind::Medication
                || (definition.kind == CatalogItemKind::Weapon && definition.melee)
                || definition.container_capacity_ml > 0
                || !definition.attachment_points.is_empty()
        })
}

pub(crate) fn add_inventory_item_checked(
    ctx: &ReducerContext,
    character_id: u64,
    item_id: &str,
    quantity: u32,
) -> Result<Option<u64>, String> {
    if quantity == 0 {
        return Ok(None);
    }

    let definition = ctx.db.item().id().find(item_id.to_owned());
    let kind = definition.as_ref().map(|definition| definition.kind);
    let food_definition = inventory_food_definition(kind, item_id)?;
    let durable = definition
        .as_ref()
        .is_some_and(|definition| definition.repairable);
    let food = food_definition.is_some();
    let measured = crate::inventory_amount::is_measured_item(ctx, item_id);
    // Every food unit is its own non-fungible batch. A partly consumed unit
    // remains quantity one while its authoritative lot mass/value/provenance
    // shrink, so it can never be merged back into fresh stock.
    let individual = requires_stable_object(definition.as_ref(), food, measured);
    let count = if individual { quantity } else { 1 };
    let mut first = None;
    for _ in 0..count {
        let item = ctx.db.inventory_item().insert(InventoryItem {
            id: 0,
            character_id,
            item_id: item_id.to_string(),
            quantity: if individual { 1 } else { quantity },
        });
        if individual {
            crate::inventory_container::insert_personal_object(ctx, &item)?;
        }
        if durable {
            crate::repair::initialize_item_condition(ctx, &item);
        }
        crate::weapon_instance::initialize_personal_weapon(ctx, &item)?;
        if measured {
            crate::inventory_amount::initialize_personal(ctx, item.id);
        }
        if food {
            crate::food::create_personal_food_lot(
                ctx,
                character_id,
                item.id,
                item_id,
                if individual { 1 } else { quantity },
            )
            .map_err(|error| format!("Could not create food lot: {error}"))?;
        }
        first.get_or_insert(item.id);
    }
    if food {
        let _ = crate::capability::refresh_character_capability(ctx, character_id);
    }
    Ok(first)
}

/// Foraging receipts bind every concrete harvested unit to an object and
/// material lot. Preserve the shared grant helper's stacking semantics for
/// every other caller while intentionally issuing one validated unit here.
pub(crate) fn add_foraged_inventory_item_checked_rows(
    ctx: &ReducerContext,
    character_id: u64,
    ctx: &ReducerContext,
    custody: &OperationalCustody,
) -> Result<(), String> {
    let mut waterskins = ctx
        .db
        .inventory_object()
        .item_id()
        .filter(STANDARD_WATERSKIN_ID)
        .collect::<Vec<_>>();
    waterskins.sort_by_key(|object| object.id);
    for object in waterskins {
        if crate::object_custody::resolve_object_custody(ctx, &object)?.root != *custody {
            continue;
        }
        require_mutable(ctx, object.id)?;
        let existing = ctx
            .db
            .container_liquid()
            .container_object_id()
            .find(object.id);
        if existing
            .as_ref()
            .is_some_and(|liquid| liquid.liquid_item_id != WATER_ITEM_ID)
        {
            continue;
        }
        let added_ml = remaining_container_capacity_ml(ctx, object.id)?;
        if added_ml == 0 {
            continue;
        }
        if let Some(mut liquid) = existing {
            liquid.water_ml = liquid
                .water_ml
                .checked_add(added_ml)
                .ok_or("Water volume overflow")?;
            ctx.db
                .container_liquid()
                .container_object_id()
                .update(liquid);
        } else {
            ctx.db.container_liquid().insert(ContainerLiquid {
                container_object_id: object.id,
                liquid_item_id: WATER_ITEM_ID.into(),
                water_ml: added_ml,
            });
        }
    }
    Ok(())
}

pub(crate) fn consume_contained_water(
    ctx: &ReducerContext,
    consumer_character_id: u64,
    expected_custody: &OperationalCustody,
    requested_ml: u64,
) -> Result<u64, String> {
    let mut liquids = Vec::new();
    for liquid in ctx
        .db
        .container_liquid()
        .iter()
        .filter(|liquid| liquid.liquid_item_id == WATER_ITEM_ID)
    {
        let object = ctx
            .db
            .inventory_object()
            .id()
            .find(liquid.container_object_id)
            .ok_or("Contained water has no physical container object")?;
        let resolved = crate::object_custody::resolve_object_custody(ctx, &object)?;
        if resolved.root == *expected_custody {
            liquids.push(liquid);
        }
    }
    liquids.sort_by_key(|liquid| liquid.container_object_id);
    let mut remaining = requested_ml;
    for mut liquid in liquids {
        let consumed = remaining.min(liquid.water_ml);
        crate::outbreak::consume_container_water_contributions(
            ctx,
            liquid.container_object_id,
            liquid.water_ml,
            consumed,
            consumer_character_id,
        )?;
        liquid.water_ml -= consumed;
        remaining -= consumed;
        if liquid.water_ml == 0 {
            ctx.db
                .container_liquid()
                .container_object_id()
                .delete(liquid.container_object_id);
            merge_empty_container(ctx, liquid.container_object_id)?;
        } else {
            ctx.db
                .container_liquid()
                .container_object_id()
                .update(liquid);
        }
        if remaining == 0 {
            break;
        }
    }
    Ok(requested_ml - remaining)
}

