/// Drape inputs for worn cloth, innermost first. Cloth worn under plate
/// lies under `lining`, each garment far enough in for those pressed over it.
pub(super) fn drape_inputs(
    model: &BodyModel,
    generated: &GeneratedCharacter,
    loadout: &Loadout<'_>,
    lining: Option<&Arc<PlateLining>>,
) -> Vec<(InventoryItemId, DrapeInput)> {
    let mut over = LINING_CLEARANCE_M;
    let mut inputs = loadout
        .draped
        .iter()
        .rev()
        .map(|piece| {
            let mut input = drape_preview::input(model, generated, piece.selection.clone());
            input.settled = piece.drape.cloned().map(Arc::new);
            if let Some(lining) = lining.filter(|_| UnderPlate::covers(piece.selection.channel())) {
                let half = piece.selection.fabric.fabric().particle_radius();
                input.under_plate = Some(UnderPlate {
                    lining: lining.clone(),
                    standoff: over + half,
                });
                over += 2.0 * half;
            }
            (piece.id, input)
        })
        .collect::<Vec<_>>();
    inputs.reverse();
    inputs
}

/// The lining of the worn rigid plate among `pieces`.
pub(super) fn lining<'a>(
    pieces: impl IntoIterator<Item = (&'a FittedPiece<'a>, &'a GeneratedArmor)>,
) -> Option<Arc<PlateLining>> {
    PlateLining::new(
        pieces
            .into_iter()
            .filter(|(piece, _)| parametric_equipment::is_rigid(piece))
            .map(|(_, armor)| armor),
    )
    .map(Arc::new)
}

fn clothing_specifications(loadout: &Loadout<'_>) -> Result<Vec<GarmentSpecification>> {
    loadout
        .clothing
        .iter()
        .map(|piece| {
            Ok(GarmentSpecification::from_catalog(
                format!(
                    "{} · {}",
                    piece.selection.item().display_name,
                    piece.selection.id
                )
                .into(),
                piece.selection,
            )?)

    /// small plates, so that only a change of fit moves the cloth under it.
    pub(super) fn lining(&mut self, loadout: &Loadout<'_>) -> Result<Option<Arc<PlateLining>>> {
        let (_, fit_keys) = fit_keys(loadout)?;
        let keys = loadout
            .fitted
            .iter()
            .enumerate()
            .filter(|(_, piece)| parametric_equipment::is_rigid(piece))
            .map(|(index, _)| fit_keys[index].clone())
            .collect::<Vec<_>>();
        if let Some((cached, lining)) = &self.lining
            && *cached == keys
        {
            return Ok(lining.clone());
        }
        let lining =
            PlateLining::new(keys.iter().filter_map(|key| self.fits.get(key))).map(Arc::new);
        self.lining = Some((keys, lining.clone()));
        Ok(lining)
    }

    /// Whether the drape of `loadout` on the cached body under `lining`
    /// differs from the last one requested; records it when it does.
    pub(super) fn drape_changed(&mut self, loadout: &Loadout<'_>) -> Result<bool> {
        let draped = loadout
            .draped
            .iter()
            .map(|piece| serde_json::to_vec(&(piece.id, piece.selection, piece.drape)))
            .collect::<serde_json::Result<Vec<_>>>()?;
        let key = serde_json::to_vec(&(
            self.body.as_ref().map(|(key, _)| key),
            self.lining.as_ref().map(|(keys, _)| keys),
            draped,
        ))?;
        let changed = self.drape.as_ref() != Some(&key);
        self.drape = Some(key);
        Ok(changed)
    }

    /// Forget the last drape, so the next regeneration drapes again.
    pub(super) fn forget_drape(&mut self) {
        self.drape = None;
    }
}

/// What a piece's fit depends on besides the body.
fn fit_keys(
    loadout: &Loadout<'_>,
) -> Result<(
    adventuresim_character_creator::equipment_layers::LayerPlan,
    Vec<Key>,
)> {
    use adventuresim_character_creator::equipment_layers::LayerPlan;
    let placements = loadout
        .fitted
        .iter()
        .map(|piece| piece.piece.selection.definition())
        .collect::<Vec<_>>();
    let plan = LayerPlan::new(&placements)?;
    let mut keys = vec![Vec::new(); placements.len()];
    for &index in plan.order() {
        let piece = &loadout.fitted[index];
        // The support's finished geometry is used, so changes to construction
        // and trim underneath also invalidate the outer fit.
        let supports = plan
            .supports(index)
            .map(|inner| finish_key(&keys[inner], &loadout.fitted[inner]))
            .collect::<Result<Vec<_>>>()?;
        let bytes = serde_json::to_vec(&(
            &piece.piece.selection.item().id,
            &piece.piece.selection.id,
            &piece.design,
            supports,
        ))?;
        keys[index] = blake3::hash(&bytes).as_bytes().to_vec();
    }
    Ok((plan, keys))
}

