fn normalized_curriculum(entries: &[TrainingEntry]) -> Vec<TrainingEntry> {
    let total = entries
        .iter()
        .map(|entry| entry.weight.max(0.0))
        .sum::<f32>();
    if total <= 0.0 {
        return Vec::new();
    }
    entries
        .iter()
        .map(|entry| TrainingEntry {
            weight: entry.weight.max(0.0) / total,
            target: entry.target.clone(),
        })
        .collect()
}

