            status: OrganizationMembershipStatus::Active,
            apprenticeship_minutes_accrued: 0,
            practice_minutes_accrued: 0,
        });
    crate::social_roles::ensure_character_organization_role(
        ctx,
        character_id,
        &organization_id,
        &entry_role_id,
    )?;
    Ok(())
}

