    for (ordinal, profession, role, presence) in [
        (0, "householder", "resident", DefaultPresence::Default),
        (
            1,
            "domestic worker",
            "neighbor",
            DefaultPresence::Additional,
        ),
    ] {
        drafts.push(ResidentDraft::resident(
            resident_seed(settlement_id, "residences", ordinal),
            "residences",
            profession,
            role,
            presence,
        ));
    }
    if urban {
        for (ordinal, profession, role, presence) in [
