            (1, "servant", "keep servant", DefaultPresence::Additional),
        ] {
            drafts.push(ResidentDraft::resident(
                resident_seed(settlement_id, "keep", ordinal),
                "keep",
                profession,
                role,
                presence,
            ));
        }
    }
    drafts
