197: pub struct DurabilityProfile {
198:     /// Stress below this only produces negligible cosmetic wear.
199:     pub yield_threshold: f32,
200:     /// A single-hit stress at which cracking, tearing, or gross deformation occurs.
201:     pub catastrophic_threshold: f32,
202:     /// Condition lost per unit of ordinary over-stress.
203:     pub wear_rate: f32,
204:     /// Fraction of the whole item's function represented by the struck component.
205:     pub failure_share: f32,
206:     /// Quality 1..5. Better work retains performance but its deepest damage is
207:     /// correspondingly harder to restore completely.
208:     pub quality: u8,
209: }
