211: #[derive(Clone, Copy, Debug, PartialEq)]
212: pub struct DamageEvent {
213:     pub amount: f32,
214:     pub tier: u8,
215:     pub catastrophic: bool,
216: }
217: 
218: /// Physical endurance supplied by craftsmanship, with munition-grade work as
219: /// the neutral baseline. Better tempering and fit raise the stress needed to
220: /// yield or fracture the item and reduce ordinary wear at the same stress.
221: pub fn quality_durability_multiplier(quality: u8) -> f32 {
222:     match quality.clamp(1, 5) {
223:         1 => 0.65,
224:         2 => 0.80,
225:         3 => 1.00,
226:         4 => 1.25,
227:         5 => 1.60,
228:         _ => unreachable!(),
229:     }
230: }
231: 
232: pub fn damage_from_impact(profile: DurabilityProfile, stress: f32) -> DamageEvent {
233:     let stress = stress.max(0.0);
234:     let durability = quality_durability_multiplier(profile.quality);
235:     let yield_threshold = profile.yield_threshold * durability;
236:     let catastrophic_threshold = profile.catastrophic_threshold * durability;
237:     let wear_rate = profile.wear_rate / durability;
238:     if stress < yield_threshold {
239:         return DamageEvent {
240:             amount: 0.0,
241:             tier: 1,
242:             catastrophic: false,
243:         };
244:     }
245:     if stress >= catastrophic_threshold {
246:         let overload = if catastrophic_threshold > 0.0 {
247:             stress / catastrophic_threshold - 1.0
248:         } else {
249:             0.0
250:         };
251:         return DamageEvent {
252:             amount: (profile.failure_share * (1.0 + overload * 0.35)).clamp(0.0, 1.0),
253:             tier: (3 + (overload * 2.0).floor() as u8 + profile.quality.saturating_sub(3) / 2)
254:                 .min(5),
255:             catastrophic: true,
256:         };
257:     }
258:     let span = catastrophic_threshold - yield_threshold;
259:     let severity = (stress - yield_threshold) / span;
260:     DamageEvent {
261:         amount: (severity * wear_rate).clamp(0.0, profile.failure_share.max(0.01)),
262:         tier: if severity < 0.55 { 1 } else { 2 },
263:         catastrophic: false,
264:     }
265: }
