541: const PROFESSION_ACCRUAL_SCALE: u64 = MINUTES_PER_DAY;
542: 
543: impl ProfessionActivityPreview {
544:     fn reward_delta(&self, allocation_name: &str, minutes: u16) -> [f32; 2] {
545:         let (accrued, threshold, sign, reward) = match allocation_name {
546:             "apprenticeship_minutes" => return [0.0, 0.0],
547:             "profession_practice_minutes" => (
548:                 self.practice_accrued,
549:                 self.practice_threshold,
550:                 1.0,
551:                 self.practice_reward,
552:             ),
553:             _ => return [0.0, 0.0],
554:         };
555:         let weight = if allocation_name == "profession_practice_minutes" {
556:             self.practice_weight
557:         } else {
558:             1
559:         };
560:         let after = accrued.saturating_add(
561:             u64::from(minutes)
562:                 .saturating_mul(PROFESSION_ACCRUAL_SCALE)
563:                 .saturating_mul(weight),
564:         );
565:         let delta = (after / threshold).saturating_sub(accrued / threshold) as f32 * sign;
566:         if reward == "fame" {
567:             [0.0, delta * self.reputation_multiplier]
568:         } else {
569:             [delta, 0.0]
570:         }
571:     }
572: }
