181:     /// Distance along the ray at which it enters `bounds`, if it enters within
182:     /// `[0, max_distance]`. Zero when the origin is already inside.
183:     pub fn hits(&self, bounds: &Aabb, max_distance: f32) -> Option<f32> {
184:         let t0 = (bounds.min - self.origin) * self.inverse_direction;
185:         let t1 = (bounds.max - self.origin) * self.inverse_direction;
186:         let near = t0.min(t1);
187:         let far = t0.max(t1);
188:         let enter = near.max_component().max(0.0);
189:         let exit = far.min_component().min(max_distance);
190:         // `<=` so that a ray grazing a flat box -- a triangle's own bounds --
191:         // still counts as a hit.
192:         (enter <= exit).then_some(enter)
193:     }
194: }
