19:     /// Converts chromaticity to XYZ tristimulus values given luminance Y (typically 1.0).
20:     pub fn to_xyz(&self, y_lum: f64) -> [f64; 3] {
21:         if self.y.abs() < 1e-12 {
22:             [0.0, 0.0, 0.0]
