155:     pub fn to_xyz_matrix(&self) -> [f64; 9] {
156:         let xr = self.red.x;
157:         let yr = self.red.y;
158:         let xg = self.green.x;
159:         let yg = self.green.y;
160:         let xb = self.blue.x;
161:         let yb = self.blue.y;
