164: 
165:         let rx = xr / yr;
166:         let ry = 1.0;
167:         let rz = (1.0 - xr - yr) / yr;
168: 
169:         let gx = xg / yg;
170:         let gy = 1.0;
171:         let gz = (1.0 - xg - yg) / yg;
172: 
173:         let bx = xb / yb;
174:         let by = 1.0;
175:         let bz = (1.0 - xb - yb) / yb;
176: 
177:         // Invert P = [[rx, gx, bx], [ry, gy, by], [rz, gz, bz]]
