183:         let sg = p_inv[3] * xw + p_inv[4] * yw + p_inv[5] * zw;
184:         let sb = p_inv[6] * xw + p_inv[7] * yw + p_inv[8] * zw;
185: 
186:         [
187:             sr * rx,
188:             sg * gx,
189:             sb * bx,
190:             sr * ry,
191:             sg * gy,
192:             sb * by,
193:             sr * rz,
194:             sg * gz,
