79: /// Computes a 3x3 chromatic adaptation matrix between source and destination white points
80: /// using the Bradford transform method.
81: pub fn bradford_adaptation(src: WhitePoint, dst: WhitePoint) -> Matrix3x3 {
82:     if src == dst {
83:         return Matrix3x3::IDENTITY;
84:     }
85: 
86:     let src_xyz = src.xyz();
87:     let dst_xyz = dst.xyz();
88: 
89:     let src_cone = M_BRADFORD.transform_vec(src_xyz);
90:     let dst_cone = M_BRADFORD.transform_vec(dst_xyz);
91: 
92:     let scale = Matrix3x3([
93:         dst_cone[0] / src_cone[0],
94:         0.0,
95:         0.0,
96:         0.0,
97:         dst_cone[1] / src_cone[1],
98:         0.0,
99:         0.0,
100:         0.0,
101:         dst_cone[2] / src_cone[2],
102:     ]);
103: 
104:     M_BRADFORD_INV.mul(&scale).mul(&M_BRADFORD)
105: }
