115: impl ColorTransform {
116:     /// Creates a transformation between two arbitrary primaries/white-points.
117:     pub fn new(src_primaries: &ColorPrimaries, dst_primaries: &ColorPrimaries) -> Self {
118:         let src_to_xyz = Matrix3x3(src_primaries.to_xyz_matrix());
119:         let dst_from_xyz = Matrix3x3(dst_primaries.from_xyz_matrix());
120:         let adapt = bradford_adaptation(src_primaries.white, dst_primaries.white);
121: 
122:         let matrix = dst_from_xyz.mul(&adapt).mul(&src_to_xyz);
123: 
124:         Self {
125:             matrix,
126:             src_transfer: TransferFunction::Linear,
127:             dst_transfer: TransferFunction::Linear,
128:         }
129:     }
