131:     /// Creates a color transformation between two standard `ColorSpace` definitions,
132:     /// including transfer curves.
133:     pub fn between_spaces(src: ColorSpace, dst: ColorSpace) -> Self {
134:         let src_prim = src.primaries();
135:         let dst_prim = dst.primaries();
136:         let mut transform = Self::new(&src_prim, &dst_prim);
137:         transform.src_transfer = src.transfer_function();
138:         transform.dst_transfer = dst.transfer_function();
139:         transform
140:     }
