153: #[inline]
154: pub fn convert_color(rgb: [f32; 3], src: ColorSpace, dst: ColorSpace) -> [f32; 3] {
155:     if src == dst {
156:         return rgb;
157:     }
158:     let transform = ColorTransform::between_spaces(src, dst);
159:     transform.convert(rgb)
