85:         if distances.iter().all(|d| *d > 0.0) || distances.iter().all(|d| *d < 0.0) {
86:             continue;
87:         }
88: 
89:         let mut crossings = Vec::with_capacity(2);
90:         for edge in 0..3 {
91:             let next = (edge + 1) % 3;
92:             let (from, to) = (distances[edge], distances[next]);
93:             if (from > 0.0) == (to > 0.0) {
94:                 continue;
95:             }
96:             let t = from / (from - to);
97:             let (a, b) = (points[edge], points[next]);
98:             crossings.push([
99:                 a[0] + (b[0] - a[0]) * t,
100:                 a[1] + (b[1] - a[1]) * t,
101:                 a[2] + (b[2] - a[2]) * t,
102:             ]);
103:         }
104:         if let [a, b] = crossings[..]
105:             && key(a) != key(b)
