/// Whether finite geographic coordinates fall inside inclusive WGS84 bounds.
pub fn coordinates_in_bounds(longitude: f64, latitude: f64, bounds: [f64; 4]) -> bool {
    let [west, south, east, north] = bounds;
    longitude.is_finite()
        && latitude.is_finite()
        && longitude >= west
        && longitude <= east
        && latitude >= south
        && latitude <= north
