25:             "event",
26:             &witness.id.0,
27:             &index.to_string(),
28:         ]))?,
29:         proposition: AtomicProposition::new(
30:             PropositionId::new(draft.proposition_id.clone())?,
31:             witness.resident_character_id.to_string(),
32:             "reported",
33:             &draft.truthful_text,
34:         )?,
35:         observer_ref: witness.resident_character_id.to_string(),
36:         speaker_ref: witness.resident_character_id.to_string(),
37:         receipt_identity: receipt_id.clone(),
38:         recollection_revision: 1,
39:         perceived_text: draft.truthful_text.clone(),
40:         recalled_text: match draft.reliability {
41:             Reliability::Truthful | Reliability::PartlyTruthful => draft.truthful_text.clone(),
42:             _ => draft.spoken_text.clone(),
43:         },
44:         disclosed_text: Some(draft.spoken_text.clone()),
45:         transmitted_text: draft.spoken_text.clone(),
46:         perception: match context.incident_weather {
47:             crate::weather::Precipitation::Clear => {
48:                 if matches!(witness.circumstance, Circumstance::NightWindow) {
49:                     PerceptionCondition::Darkness
50:                 } else {
51:                     PerceptionCondition::Clear
52:                 }
53:             }
54:             crate::weather::Precipitation::Rain | crate::weather::Precipitation::Snow => {
55:                 PerceptionCondition::PoorPerception
56:             }
57:         },
58:         memory: if draft.reliability == Reliability::Mistaken {
59:             MemoryCondition::Confused
60:         } else {
61:             MemoryCondition::Accurate
62:         },
63:         disclosure: match draft.reliability {
64:             Reliability::Deceptive => DisclosureMode::Distort,
65:             Reliability::Evasive => DisclosureMode::Conceal,
66:             _ => DisclosureMode::Disclose,
67:         },
68:         transmission: TransmissionCondition::Clear,
69:         received_at,
70:     };
71:     Ok((receipt_id, pipeline))
72: }
