71: pub(crate) fn validate_quest_generation_authority(
72:     authority: &QuestGenerationAuthority,
73: ) -> Result<ValidatedQuestGenerationAuthority, String> {
74:     use adventuresim_core::quest_generation as qg;
75:     if authority.context_commitment
76:         != quest_generation_context_commitment(&authority.context_snapshot_json)?
77:     {
78:         return Err("Quest generation context commitment mismatch".into());
79:     }
80:     let developer_context = serde_json::from_str::<
81:         adventuresim_core::developer_quest::DeveloperGenerationContext,
82:     >(&authority.context_snapshot_json)
83:     .ok();
84:     let context: qg::GenerationContext = if let Some(developer) = &developer_context {
85:         developer.base.clone()
86:     } else {
87:         serde_json::from_str(&authority.context_snapshot_json)
88:             .map_err(|_| "Quest generation context is invalid")?
89:     };
90:     let manifest: qg::GeneratedCase = serde_json::from_str(&authority.manifest_json)
91:         .map_err(|_| "Quest generation manifest is invalid")?;
92:     let trace: Vec<qg::FactorTrace> = serde_json::from_str(&authority.factor_trace_json)
93:         .map_err(|_| "Quest generation factor trace is invalid")?;
94:     let scope_matches = matches!(
95:         &context.scope,
96:         adventuresim_core::local_problem::Scope::Settlement { settlement_id }
97:             if settlement_id == &context.settlement_id
98:     );
99:     if authority.case_id != manifest.canonical_case_id
100:         || authority.public_case_id != manifest.public_case_id
101:         || authority.seed != context.seed
102:         || authority.seed != manifest.generation_seed
103:         || authority.catalog_revision != qg::CATALOG_REVISION
104:         || authority.catalog_revision != manifest.catalog_revision
105:         || manifest.catalog_revision != qg::CATALOG_REVISION
106:         || trace != manifest.factor_trace
107:         || authority.settlement_id != context.settlement_id
108:         || authority.settlement_name != context.settlement_name
109:         || context.settlement_id.is_empty()
110:         || context.settlement_name.is_empty()
111:         || !scope_matches
112:     {
113:         return Err("Quest generation authority metadata is inconsistent".into());
114:     }
115:     qg::validate(&manifest).map_err(|errors| {
116:         format!(
117:             "Quest generation manifest failed validation: {}",
118:             errors.join("; ")
119:         )
120:     })?;
121:     let regenerated = if let Some(developer) = &developer_context {
122:         adventuresim_core::developer_quest::compile(developer).map_err(|diagnostics| {
123:             format!(
124:                 "Developer quest replay failed: {}",
125:                 serde_json::to_string(&diagnostics)
126:                     .unwrap_or_else(|_| "invalid diagnostics".into())
127:             )
128:         })?
129:     } else {
130:         qg::generate(&context)
131:             .map_err(|error| format!("Quest generation replay failed: {error:?}"))?
132:     };
133:     if regenerated != manifest {
134:         return Err("Quest generation replay does not match stored manifest".into());
135:     }
136:     Ok(ValidatedQuestGenerationAuthority { context, manifest })
137: }
