457:         other.milli_points
458:     } else {
459:         0
460:     };
461:     RefreshableMorale {
462:         milli_points: min_u32(
463:             refreshed.milli_points,
464:             LEISURE_MORALE_STACK_CAP_MILLI.saturating_sub(other_live),
465:         ),
466:         expires_at_minute: refreshed.expires_at_minute,
467:     }
468: }
