31: impl ThreatId {
32:     const fn from_static(value: &str) -> Self {
33:         let source = value.as_bytes();
34:         let mut bytes = [0; 63];
35:         let mut index = 0;
36:         while index < source.len() {
37:             bytes[index] = source[index];
38:             index += 1;
39:         }
40:         Self {
41:             len: source.len() as u8,
42:             bytes,
43:         }
44:     }
45:     pub fn try_new(value: &str) -> Result<Self, UnknownThreatId> {
46:         if value.is_empty()
47:             || value.len() > 63
48:             || !value.bytes().all(|byte| {
49:                 byte.is_ascii_lowercase()
50:                     || byte.is_ascii_digit()
51:                     || matches!(byte, b'_' | b'-' | b'.' | b':')
52:             })
53:         {
54:             return Err(UnknownThreatId);
55:         }
56:         let mut bytes = [0; 63];
57:         bytes[..value.len()].copy_from_slice(value.as_bytes());
58:         Ok(Self {
59:             len: value.len() as u8,
60:             bytes,
61:         })
62:     }
63:     pub fn as_str(&self) -> &str {
64:         core::str::from_utf8(&self.bytes[..usize::from(self.len)]).expect("validated ASCII ID")
65:     }
