601: /// Applies source-idempotent custody transitions while enforcing one current
602: /// holder per asset or subject.
603: pub fn apply_custody(
604:     records: &mut BTreeMap<CustodyObject, CustodyRecord>,
605:     next: CustodyRecord,
606: ) -> Result<bool, &'static str> {
607:     if let Some(current) = records.get(&next.object) {
608:         if current.source_id == next.source_id {
609:             return Ok(false);
610:         }
611:         if next.version != current.version.saturating_add(1) {
612:             return Err("custody transition has stale or skipped version");
613:         }
614:         if current.case_id != next.case_id {
615:             return Err("custody object cannot move between cases");
616:         }
617:     } else if next.version != 0 {
618:         return Err("initial custody version must be zero");
619:     }
620:     records.insert(next.object.clone(), next);
621:     Ok(true)
622: }
