868: fn participant_language_compatibility(
869:     target_effective_hours: f32,
870:     instinct: f32,
871: ) -> (&'static str, bool) {
872:     let effective = if target_effective_hours.is_finite() {
873:         target_effective_hours.max(0.0)
874:     } else {
875:         0.0
876:     };
877:     let aptitude = if instinct.is_finite() {
878:         instinct.clamp(0.0, 5.0)
879:     } else {
880:         0.0
881:     };
882:     let coefficient =
883:         effective.min(aptitude * 1_000.0) / adventuresim_world_schema::ORAL_FLUENCY_HOURS;
884:     if coefficient >= 0.75 {
885:         ("fluent", true)
886:     } else if coefficient >= 0.35 {
887:         ("limited", true)
888:     } else {
889:         ("poor", false)
890:     }
891: }
