858: fn reconcile_party_pool_ledger(ctx: &ReducerContext, party_id: &str) -> Result<(), String> {
859:     let remaining_value = ctx
860:         .db
861:         .party_inventory_item()
862:         .party_id()
863:         .filter(party_id)
864:         .try_fold(0_u64, |total, row| {
865:             Ok::<_, String>(total.saturating_add(
866:                 objective_item_value(ctx, &row.item_id)?.saturating_mul(u64::from(row.quantity)),
867:             ))
868:         })?;
869:     let mut stakes: Vec<_> = ctx.db.party_stake().party_id().filter(party_id).collect();
870:     stakes.sort_by_key(|stake| stake.id);
871:     let prior_reserve = ctx
872:         .db
873:         .party_inventory_state()
874:         .party_id()
875:         .find(party_id.to_string())
876:         .map_or(0, |state| state.reserve_value);
877:     let total_claims = stakes.iter().fold(prior_reserve, |total, stake| {
878:         total.saturating_add(stake.value)
879:     });
880:     let mut allocated = 0_u64;
881:     for mut stake in stakes {
882:         stake.value = if total_claims == 0 {
883:             0
884:         } else {
885:             ((u128::from(stake.value) * u128::from(remaining_value)) / u128::from(total_claims))
886:                 as u64
887:         };
888:         allocated = allocated.saturating_add(stake.value);
889:         ctx.db.party_stake().id().update(stake);
890:     }
891:     let reserve_value = remaining_value.saturating_sub(allocated);
892:     if let Some(mut state) = ctx
893:         .db
894:         .party_inventory_state()
895:         .party_id()
896:         .find(party_id.to_string())
897:     {
898:         state.reserve_value = reserve_value;
899:         ctx.db.party_inventory_state().party_id().update(state);

