1024: pub(crate) fn resolve_narrative_combat_followup(
1025:     ctx: &ReducerContext,
1026:     encounter: &StrategicEncounter,
1027: ) -> Result<(), String> {
1028:     let Some(followup) = ctx
1029:         .db
1030:         .narrative_combat_followup_authority()
1031:         .encounter_id()
1032:         .find(&encounter.encounter_id)
1033:     else {
1034:         return Ok(());
1035:     };
1036:     let outcome = encounter
1037:         .outcome
1038:         .as_deref()
1039:         .ok_or("Narrative combat resolved without an outcome")?;
1040:     if let Some(receipt) = ctx
1041:         .db
1042:         .narrative_combat_followup_receipt()
1043:         .encounter_id()
1044:         .find(&encounter.encounter_id)
1045:     {
1046:         return if receipt.occurrence_id == followup.occurrence_id
1047:             && receipt.party_id == encounter.party_id
1048:             && receipt.initiating_character_id == followup.initiating_character_id
1049:             && receipt.outcome == outcome
1050:         {
1051:             Ok(())
1052:         } else {
1053:             Err("Conflicting narrative combat follow-up retry".into())
1054:         };
1055:     }
1056:     let outcomes = serde_json::from_str::<
1057:         adventuresim_core::road_encounter_catalog::CombatOutcomeSet,
1058:     >(&followup.outcome_payloads_json)
1059:     .map_err(|_| "Narrative combat outcome payloads are invalid")?;
1060:     let outcome_kind = adventuresim_core::road_encounter_catalog::resolved_combat_outcome(outcome)?;
1061:     let payload = outcomes.payload(outcome_kind).clone();
1062:     let now = crate::time::refresh_clock(ctx)?;
1063:     for effect in &payload.effects {
1064:         apply_narrative_effect(
1065:             ctx,
1066:             &followup.occurrence_id,
1067:             &encounter.party_id,
1068:             now,
1069:             effect,
1070:         )?;
1071:     }
1072:     let recognized_virtue =
1073:         adventuresim_core::road_encounter_catalog::exemplified_virtue(&payload.personality)
1074:             ;
1075:     for development in &payload.personality {
1076:         let virtue = development.virtue;
1077:         crate::personality::apply_personality_development(
1078:             ctx,
1079:             &format!(
1080:                 "narrative-combat:{}:{}",
1081:                 followup.encounter_id, development.axis as u8
1082:             ),
1083:             followup.initiating_character_id,
1084:             narrative_axis(development.axis),
1085:             development.delta,
1086:             "prevail_in_authored_road_combat",
1087:             virtue,
1088:             now,
1089:         )?;
1090:     }

