254: pub(super) fn descendants_including(root: Entity, children: &Query<&Children>) -> Vec<Entity> {
255:     let mut found = Vec::new();
256:     let mut pending = vec![root];
257:     while let Some(entity) = pending.pop() {
258:         found.push(entity);
259:         if let Ok(entity_children) = children.get(entity) {
260:             pending.extend(entity_children.iter());
261:         }
262:     }
263:     found
264: }
265: 
266: pub(super) fn find_named_descendant(
267:     root: Entity,
268:     target: &str,
269:     children: &Query<&Children>,
270:     names: &Query<&Name>,
271: ) -> Option<Entity> {
272:     descendants_including(root, children)
273:         .into_iter()
274:         .find(|entity| names.get(*entity).is_ok_and(|name| name.as_str() == target))
275: }
