33: pub(super) fn select_species(hash: Seed, habitat: UnderstoryHabitat) -> UnderstorySpecies {
34:     // This temporary habitat model intentionally uses only scene data already
35:     // available to the client. Hazel favors shaded, mesic woodland; blackthorn
36:     // favors brighter, drier scrub; hawthorn gains weight at open/cultivated
37:     // edges. A later world-data source can replace these weights without
38:     // changing species geometry or scatter identity.
39:     let dry = 1.0 - habitat.moisture;
40:     let open = 1.0 - habitat.canopy;
41:     let hazel = 0.25 + habitat.canopy * 1.55 + habitat.moisture * 0.35;
42:     let blackthorn = (0.2 + open * 0.82 + dry * 0.34 + habitat.cultivation * 0.22)
43:         * (1.0 - habitat.wetland * 0.55);
44:     let hawthorn =
45:         (0.24 + open * 0.48 + habitat.cultivation * 0.88) * (1.0 - habitat.wetland * 0.38);
46:     let weights = [hazel, blackthorn, hawthorn].map(|weight| {
47:         (weight * f32::from(adventuresim_world_schema::BASIS_POINTS_PER_WHOLE)).round() as u64
48:     });
49:     let index = streams::SPECIES
50:         .rng(hash, &[])
51:         .weighted_index(&weights)
52:         .expect("habitat base weights are positive and bounded");
53:     [
54:         UnderstorySpecies::CommonHazel,
55:         UnderstorySpecies::Blackthorn,
56:         UnderstorySpecies::CommonHawthorn,
57:     ][index]
58: }
