31:     let recipe = GeneratedBuildingRecipe::generate(placement.program.clone())?;
32:     let origin = recipe.collision.bounds.centre()?.metres().xz();
33:     let contact = recipe
34:         .collision
35:         .ground_floor_contact_bounds()?
36:         .ok_or("missing bearing")?;
37:     let bearing = CityPlotBounds::new(
