39:             placement.centre_metres.metres()
40:                 + placement
41:                     .orientation
42:                     .local_to_world(contact.centre()?.metres().xz() - origin),
43:         )?,
44:         adventuresim_building_generator::spatial_geometry::PlanDimensions::from_metres(
45:             contact.plan_half_extents()?.metres() * 2.0,
46:         )?,
47:         placement.orientation,
48:     )?;
49:     let entries: Vec<_> = adventuresim_building_generator::compile_ground_entrances(&recipe.plan)?.into_iter().map(|entry| {
50:         json!({"id":entry.id,"support":entry.support,"threshold_m":placement.centre_metres.metres()+placement.orientation.local_to_world(entry.threshold_metres.metres()-origin),"outward":placement.orientation.local_to_world(entry.outward.vector())})
51:     }).collect();
52:     let point = diagnostic.location_metres.attempted_metres();
53:     let mut streets: Vec<_> = layout
54:         .streets
55:         .iter()
