77: 
78:     pub fn unit_f64(&mut self) -> f64 {
79:         crate::unit_f64(self.next_u64())
80:     }
81: 
82:     pub fn inclusive_unit_f32(&mut self) -> f32 {
83:         crate::inclusive_unit_f32(self.next_u64())
84:     }
85: 
86:     pub fn inclusive_unit_f64(&mut self) -> f64 {
87:         crate::inclusive_unit_f64(self.next_u64())
88:     }
89: 
90:     /// Scaling has interval semantics but no downstream bitwise guarantee.
91:     pub fn range_f32(&mut self, minimum: f32, maximum: f32) -> f32 {
92:         assert!(minimum.is_finite() && maximum.is_finite() && minimum <= maximum);
93:         minimum + self.unit_f32() * (maximum - minimum)
94:     }
95: 
96:     /// Descending Fisher–Yates. Every swap uses the same u64 sampler.
97:     pub fn shuffle<T>(&mut self, values: &mut [T]) {
98:         for index in (1..values.len()).rev() {
99:             let selected = self.index(index + 1);
100:             values.swap(index, selected);
101:         }
102:     }
103: 
104:     /// The input order must be authored or canonicalized by stable identity.
105:     pub fn weighted_index(&mut self, weights: &[u64]) -> Result<usize, SamplingError> {
106:         use rand::distr::weighted::Error;
107:         let distribution = WeightedIndex::<u64>::new(weights).map_err(|error| match error {
108:             Error::InvalidInput => SamplingError::EmptyCandidates,
109:             Error::InsufficientNonZero => SamplingError::ZeroTotalWeight,
110:             Error::Overflow => SamplingError::WeightOverflow,
111:             Error::InvalidWeight => unreachable!("u64 weights are nonnegative"),
112:             _ => unreachable!("pinned weighted sampler error"),
113:         })?;
114:         Ok(distribution.sample(&mut self.0))
115:     }
116: 
117:     /// Proportional draws without replacement; zero-weight entries are omitted.
118:     pub fn weighted_order(&mut self, weights: &[u64]) -> Result<Vec<usize>, SamplingError> {
119:         let mut remaining = weights.to_vec();
120:         let mut result = Vec::new();
121:         let count = remaining.iter().filter(|weight| **weight != 0).count();
122:         if count == 0 {
123:             return self.weighted_index(weights).map(|_| result);
124:         }
125:         for _ in 0..count {
126:             let index = self.weighted_index(&remaining)?;
127:             result.push(index);
128:             remaining[index] = 0;
129:         }
130:         Ok(result)

