43:             (WeaponHolderKind::BladeSheath, "scabbard")
44:                 | (WeaponHolderKind::HaftLoop, "weapon_loop")
45:         )
46:     {
47:         return Err(vec![ValidationError::Holder("kind")]);
48:     }
