64:                             | SolidRole::BeamJoist
65:                             | SolidRole::FrameJoist
66:                             | SolidRole::FrameGirder
67:                             | SolidRole::RoofPlate
68:                     ))
69:             {
70:                 continue;
71:             }
72:             let wall = wall_for_solid(plan, solid);
73:             // Gable compilers select individual faces; they retain their own
74:             // geometry until the component representation supports face masks.
75:             if wall.is_some_and(|wall| matches!(wall.source, crate::WallSourceId::RoofGable { .. }))
76:                 || solid.role == SolidRole::FrameGableMember
