96: /// Where hair parts: a plane through the head (the part line is where it
97: /// meets the scalp) over the front of the head. Roots on either side are
98: /// kept apart; behind `until` (a `z`, towards the back) the part has ended
99: /// and roots take from both sides.
100: #[derive(Clone, Debug, Default, Serialize, Deserialize)]
101: pub enum Parting {
102:     #[default]
103:     None,
104:     Plane {
105:         normal: [f32; 3],
106:         offset: f32,
107:         until: f32,
108:     },
109:     /// Sectors round the head, the front one in the middle: a braid's
110:     /// lanes, gathered from the left, the top and the right.
111:     Lanes { count: u32 },
112:     /// A fringe: the front of the scalp (in front of `front`, within
113:     /// `half_width` of the middle) apart from the rest, whose front is
114:     /// split left from right -- hair combed to either side of a fringe must
115:     /// not be averaged into hair combed down the face.
116:     Fringe { front: f32, half_width: f32 },
117: }
118: 
119: impl Parting {
120:     /// A part along the head from front to crown, `offset` metres to the
121:     /// side (0 in the middle).
122:     pub fn line(offset: f32, until: f32) -> Self {
123:         Parting::Plane {
124:             normal: [1.0, 0.0, 0.0],
125:             offset,
126:             until,
127:         }
128:     }
129: 
130:     /// The group of a root: 0 or 1 on either side of the part, -1 where
131:     /// there is none.
132:     pub fn group(&self, p: Vec3) -> PartingGroup {
133:         let word = match self {
134:             Parting::None => -1,
135:             Parting::Plane {
136:                 normal,
137:                 offset,
138:                 until,
139:             } => {
140:                 if p.z < *until {
141:                     -1
142:                 } else if Vec3::from_array(*normal).dot(p) > *offset {
143:                     1
144:                 } else {
145:                     0
146:                 }
147:             }
148:             Parting::Fringe { front, half_width } => {
149:                 if p.z > *front && p.x.abs() < *half_width {
150:                     1
151:                 } else if p.z > -0.03 {
152:                     if p.x >= 0.0 { 2 } else { 0 }
153:                 } else {
154:                     -1
155:                 }
156:             }
157:             Parting::Lanes { count } => {
158:                 let a = p.x.atan2(p.z + 0.02);
159:                 let t = (a + std::f32::consts::PI) / std::f32::consts::TAU;
160:                 ((t * *count as f32) as i32).clamp(0, *count as i32 - 1)
161:             }
162:         };
163:         PartingGroup::from_gpu_word(word)
164:     }
165: }
