167: /// Whether a strand of group `own` may take its shape from a guide of group
168: /// `guide`: the same side, or either has no side.
169: pub fn compatible(own: PartingGroup, guide: PartingGroup) -> bool {
170:     own.is_unassigned() || guide.is_unassigned() || own == guide
170:     own.is_unassigned() || guide.is_unassigned() || own == guide
171: }
