176: #[derive(Clone, Debug, Default, Serialize, Deserialize)]
177: pub enum DensityMask {
178:     #[default]
179:     Uniform,
180:     /// Male-pattern loss: a thinned crown, temples receding, the top
181:     /// thinning between them. Each amount from 0 (none) to 1.
182:     Balding { crown: f32, temples: f32, top: f32 },
183:     /// A mask image over the UV square, row-major from `v = 0`, values 0 to 1.
184:     Image {
185:         width: usize,
186:         height: usize,
187:         values: Vec<f32>,
188:     },
189: }
190: 
191: impl DensityMask {
192:     pub fn at(&self, uv: [f32; 2]) -> f32 {
193:         match self {
194:             DensityMask::Uniform => 1.0,
195:             DensityMask::Balding {
196:                 crown,
197:                 temples,
198:                 top,
199:             } => {
200:                 let (x, y) = (uv[0] - 0.5, uv[1] - 0.5);
201:                 let r = (x * x + y * y).sqrt() * 2.0;
202:                 // The crown whorl sits a little behind the top.
203:                 let cx = x;
204:                 let cy = y + 0.08;
205:                 let crown_r = (cx * cx + cy * cy).sqrt() * 2.0;
206:                 let crown_loss =
207:                     crown * (1.0 - super::smoothstep(0.1, 0.1 + 0.35 * crown, crown_r));
208:                 // Temples: towards the front at either side.
209:                 let angle = x.atan2(y);
210:                 let temple = (-((angle.abs() - 0.55) / 0.3).powi(2)).exp();
211:                 let temple_loss =
212:                     temples * temple * super::smoothstep(0.62 - 0.35 * temples, 0.8, r);
213:                 // The top: a band from the front hairline back to the crown.
214:                 let band = (-(x / 0.16).powi(2)).exp() * super::smoothstep(-0.2, 0.3, y);
215:                 let top_loss = top * band * super::smoothstep(0.0, 0.5, r);
216:                 (1.0 - crown_loss.max(temple_loss).max(top_loss)).clamp(0.0, 1.0)
217:             }
218:             DensityMask::Image {
219:                 width,
220:                 height,
221:                 values,
222:             } => {
223:                 if *width == 0 || *height == 0 {
224:                     return 1.0;
