218:     /// Converts role coordinates to a native dense offset only after membership
219:     /// in this layout. The admitted dense product proves the arithmetic fits.
220:     fn dense_offset(&self, coordinate: SparseCoordinate) -> Result<CorrectiveDenseOffset> {
221:         let SparseCoordinate { hidden, feature } = coordinate;
222:         let hidden_width = usize::from(self.hidden);
223:         if hidden.native_index >= hidden_width || feature.native_index >= usize::from(self.features)
224:         {
225:             return Err(CorrectiveImportError::SparseCoordinate { hidden, feature });
226:         }
227:         Ok(CorrectiveDenseOffset {
228:             native_index: feature.native_index * hidden_width + hidden.native_index,
229:         })
230:     }
231: 
232:     fn scaled(
233:         dimension: NpyDimension,
234:         factor: NpyDimension,
235:         extent: CorrectiveExtent,
236:     ) -> Result<NpyDimension> {
237:         dimension
238:             .checked_mul(factor)
239:             .ok_or(CorrectiveImportError::ExtentOverflow { extent })
240:     }
241: }
242: 
243: impl<'layout> SparseActivation<'layout> {
244:     pub(super) fn new(
245:         indices: NpyIntegerValues,
246:         weights: NpyFloat32Values,
247:         layout: &'layout CorrectiveLayout,
248:     ) -> Result<Self> {
249:         if weights.element_count().checked_mul(SPARSE_COLUMNS) != Some(indices.element_count()) {
250:             return Err(CorrectiveImportError::SparseCardinality {
251:                 indices: indices.element_count(),
252:                 weights: weights.element_count(),
253:             });
254:         }
255:         let (rows, columns) = indices.values().split_at(weights.values().len());
256:         let contributions = rows
257:             .iter()
258:             .zip(columns)
259:             .zip(weights.values())
260:             .map(|((hidden, feature), weight)| {
261:                 let coordinate = SparseCoordinate {
262:                     hidden: CorrectiveHiddenIndex::from(*hidden),
263:                     feature: CorrectiveFeatureIndex::from(*feature),
264:                 };
265:                 Ok(SparseContribution {
266:                     offset: layout.dense_offset(coordinate)?,
267:                     weight: *weight,
268:                 })
269:             })
270:             .collect::<Result<_>>()?;
271:         Ok(Self {
272:             layout,
273:             contributions,
274:         })
275:     }
276: 
277:     /// Densifies in Burn's transposed `[features, hidden]` order. Only the
278:     /// checked dense offset, allocation length and coefficient reach native storage.
279:     pub(super) fn into_tensor(self, device: &Device) -> Tensor<2> {
280:         // Every offset and the allocation extent were admitted together.
281:         let mut dense = vec![0.0f32; usize::from(self.layout.activation.element_count())];
282:         for contribution in self.contributions {
283:             // Ordered writes intentionally let the last duplicate replace earlier ones.
284:             dense[contribution.offset.native_index] = contribution.weight;
285:         }
286:         Tensor::from_data(
287:             TensorData::new(dense, self.layout.activation_dimensions()),
288:             device,
289:         )
290:     }
291: }
