293: impl CorrectiveHiddenIndex {
294:     /// Native-width coordinate for structured diagnostics, not layout membership.
295:     pub const fn native_index(self) -> usize {
296:         self.native_index
297:     }
298: }
299: 
300: impl CorrectiveFeatureIndex {
301:     /// Native-width coordinate for structured diagnostics, not layout membership.
302:     pub const fn native_index(self) -> usize {
303:         self.native_index
304:     }
305: }
306: 
307: impl From<i64> for CorrectiveHiddenIndex {
308:     fn from(value: i64) -> Self {
309:         // Preserve cast-before-bounds, including rejected negative diagnostics.
310:         Self {
311:             native_index: value as usize,
312:         }
313:     }
314: }
315: 
316: impl From<i64> for CorrectiveFeatureIndex {
317:     fn from(value: i64) -> Self {
318:         Self {
319:             native_index: value as usize,
320:         }
321:     }
322: }

