12: pub type Result<T> = std::result::Result<T, CorrectiveImportError>;
13: 
14: /// The native tensor extent whose checked calculation overflowed.
15: #[derive(Debug, Clone, Copy)]
16: pub enum CorrectiveExtent {
17:     HiddenUnits,
18:     FeatureChannels,
19:     BasisColumns,
20:     BasisElements,
21:     DenseElements,
22: }
23: 
24: /// A rejected relationship in the corrective network's imported tensor data.
25: #[derive(Debug)]
26: pub enum CorrectiveImportError {
27:     BasisShape {
28:         shape: NpyShape,
29:     },
30:     VertexCount {
31:         basis: NpyDimension,
32:         mesh: MeshVertexCount,
33:     },
34:     JointCount {
35:         joints: RigJointCount,
36:     },
37:     Components {
38:         actual: NpyDimension,
39:         expected: NpyDimension,
40:     },
41:     ExtentOverflow {
42:         extent: CorrectiveExtent,
43:     },
44:     TensorLayout {
45:         extent: CorrectiveExtent,
46:         source: NpyLayoutError,
47:     },
48:     SparseCardinality {
49:         indices: NpyElementCount,
50:         weights: NpyElementCount,
51:     },
52:     SparseCoordinate {
53:         hidden: CorrectiveHiddenIndex,
54:         feature: CorrectiveFeatureIndex,
55:     },
56: }
57: 
58: impl fmt::Display for CorrectiveImportError {
59:     fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
60:         match self {
61:             Self::BasisShape { shape } => write!(
62:                 f,
63:                 "{} has shape {shape:?}, expected [components, vertices, 3]",
64:                 super::super::archive::CorrectiveArray::Basis.name()
65:             ),
66:             Self::VertexCount { basis, mesh } => write!(
67:                 f,
68:                 "corrective basis covers {basis} vertices but the mesh has {mesh}"
69:             ),
70:             Self::JointCount { joints } => write!(
71:                 f,
72:                 "corrective network has {joints} joints, fewer than the {} unposed joints",
73:                 super::super::SKIPPED_JOINTS
74:             ),
75:             Self::Components { actual, expected } => write!(
76:                 f,
77:                 "corrective basis has {actual} components, expected {expected}"
78:             ),
79:             Self::ExtentOverflow { extent } | Self::TensorLayout { extent, .. } => {
80:                 write!(f, "corrective tensor extent overflows for {extent:?}")
81:             }
82:             Self::SparseCardinality { indices, weights } => write!(
83:                 f,
84:                 "sparse activation has {indices} indices for {weights} weights"
85:             ),
86:             Self::SparseCoordinate { hidden, feature } => write!(
87:                 f,
88:                 "sparse activation index ({}, {}) is out of bounds",
89:                 hidden.native_index(),
90:                 feature.native_index()
91:             ),
92:         }
93:     }
94: }
95: 
96: impl Error for CorrectiveImportError {
97:     fn source(&self) -> Option<&(dyn Error + 'static)> {
98:         match self {
99:             Self::TensorLayout { source, .. } => Some(source),
100:             _ => None,
101:         }
102:     }
103: }

