107: impl CorrectiveLayout {
108:     pub(super) fn new(
109:         basis: &NpyShape,
110:         joints: RigJointCount,
111:         vertices: MeshVertexCount,
112:     ) -> Result<Self> {
113:         // Rig membership count becomes an array extent here; this is not a rig ordinal.
114:         let joint_extent = NpyDimension::from(joints.native_joint_count());
115:         let &[components, basis_vertices, coordinates] = basis.dimensions() else {
116:             return Err(CorrectiveImportError::BasisShape {
117:                 shape: basis.clone(),
118:             });
119:         };
120:         if coordinates != VERTEX_COORDINATES {
121:             return Err(CorrectiveImportError::BasisShape {
122:                 shape: basis.clone(),
123:             });
124:         }
125:         // Mesh quantity becomes a generic axis only at this array-layout boundary.
126:         let vertex_extent = NpyDimension::from(vertices.native_vertex_count());
127:         if basis_vertices != vertex_extent {
128:             return Err(CorrectiveImportError::VertexCount {
129:                 basis: basis_vertices,
130:                 mesh: vertices,
131:             });
132:         }
133:         let posed_joints = joint_extent
134:             .checked_sub(SKIPPED_JOINTS)
135:             .ok_or(CorrectiveImportError::JointCount { joints })?;
136:         let hidden = Self::scaled(
137:             posed_joints,
138:             HIDDEN_PER_JOINT,
139:             CorrectiveExtent::HiddenUnits,
140:         )?;
141:         if components != hidden {
142:             return Err(CorrectiveImportError::Components {
143:                 actual: components,
144:                 expected: hidden,
145:             });
146:         }
147:         let features = Self::scaled(
148:             posed_joints,
149:             FEATURES_PER_JOINT,
150:             CorrectiveExtent::FeatureChannels,
151:         )?;
152:         let basis_columns = Self::scaled(
153:             vertex_extent,
154:             VERTEX_COORDINATES,
155:             CorrectiveExtent::BasisColumns,
156:         )?;
157:         let basis = NpyTensorLayout::try_from([hidden, basis_columns]).map_err(|source| {
158:             CorrectiveImportError::TensorLayout {
159:                 extent: CorrectiveExtent::BasisElements,
160:                 source,
161:             }
162:         })?;
163:         let activation = NpyTensorLayout::try_from([features, hidden]).map_err(|source| {
164:             CorrectiveImportError::TensorLayout {
165:                 extent: CorrectiveExtent::DenseElements,
166:                 source,
167:             }
168:         })?;
169:         Ok(Self {
170:             joints,
171:             posed_joints,
172:             vertices,
173:             features,
174:             hidden,
175:             basis,
176:             activation,
177:         })
178:     }

