40: impl PoseCorrectives {
41:     /// Loads the corrective network for one level of detail, or `None` when the
42:     /// LOD ships no corrective basis.
43:     ///
44:     /// `activation_path` holds the sparse mask and weights shared by every LOD;
45:     /// `basis_path` holds this LOD's corrective basis.
46:     pub fn load(
47:         activation_path: &Path,
48:         basis_path: &Path,
49:         num_joints: RigJointCount,
50:         num_vertices: MeshVertexCount,
51:         device: &Device,
52:     ) -> Result<Option<Self>> {
53:         Self::from_archives(
54:             CorrectiveArchives::open(activation_path, basis_path)?,
55:             num_joints,
56:             num_vertices,
57:             device,
58:         )
59:     }
60: 
61:     /// Loads corrective archives already held in memory (for web/streamed assets).
62:     pub fn from_bytes(
63:         archives: CorrectiveArchiveBytes,
64:         num_joints: RigJointCount,
65:         num_vertices: MeshVertexCount,
66:         device: &Device,
67:     ) -> Result<Option<Self>> {
68:         Self::from_archives(
69:             CorrectiveArchives::from_bytes(archives)?,
70:             num_joints,
71:             num_vertices,
72:             device,
73:         )
74:     }
75: 
76:     fn from_archives(
77:         archives: CorrectiveArchives,
78:         num_joints: RigJointCount,
79:         num_vertices: MeshVertexCount,
80:         device: &Device,
81:     ) -> Result<Option<Self>> {
82:         let Some(array) = archives.basis()? else {
83:             return Ok(None);
84:         };
85:         let basis = CorrectiveBasis::new(array, num_joints, num_vertices)?;
86:         let activation = archives.activation(basis.layout())?.into_tensor(device);
87:         let tensor = basis.to_tensor(device)?;
88:         Ok(Some(Self {
89:             activation,
90:             basis: tensor,
91:             layout: basis.into_layout(),
92:         }))
