60:     /// itself, not just its rigid frame.
61:     pub normals: Tensor<3>,
62:     /// Global joint transforms `[tx, ty, tz, qx, qy, qz, qw, s]`, `[batch, joints, 8]`.
63:     pub skeleton_state: Tensor<3>,
