246:         if line.starts_with('[') && line.ends_with(']') {
247:             current = Some(line[1..line.len() - 1].to_string());
248:             sections
249:                 .entry(line[1..line.len() - 1].to_string())
250:                 .or_default();
251:             continue;
252:         }
253:         if let Some(section) = &current {
