9: pub(crate) type Result<T> = std::result::Result<T, ParameterLayoutError>;
10: 
11: /// Row-major coefficients; the entire native allocation extent is admitted.
12: #[derive(Debug, Clone)]
13: pub(crate) struct ParameterMatrix {
14:     values: Vec<f32>,
15:     joints: RigJointCount,
16:     layout: NpyTensorLayout<2>,
17: }
18: 
19: #[derive(Debug, Display, Error)]
20: pub enum ParameterLayoutError {
21:     #[display("joint-channel row count overflows for {joints} joints")]
22:     JointRows { joints: RigJointCount },
23:     #[display("parameter matrix layout is not representable: {source}")]
24:     Matrix { source: NpyLayoutError },
25:     #[display("parameter matrix allocation is not representable: {source}")]
26:     Allocation { source: std::alloc::LayoutError },
27:     #[display("model parameter column count overflows")]
28:     ColumnCount,
29:     #[display("requested {columns} parameter columns from a matrix with {available}")]
30:     ColumnPrefix {
31:         columns: NpyDimension,
32:         available: NpyDimension,
33:     },
34:     #[display("joint-channel row is outside the parameter matrix")]
35:     RowMembership,
36:     #[display("model parameter column is outside the parameter matrix")]
37:     ColumnMembership,
38: }
39: 
40: impl ParameterMatrix {
41:     pub(crate) fn zeros(joints: RigJointCount, columns: NpyDimension) -> Result<Self> {
42:         let rows = NpyDimension::from(joints.native_joint_count())
43:             .checked_mul(NpyDimension::from(PARAMETERS_PER_JOINT))
44:             .ok_or(ParameterLayoutError::JointRows { joints })?;
45:         let layout = NpyTensorLayout::try_from([rows, columns])
46:             .map_err(|source| ParameterLayoutError::Matrix { source })?;
47:         let elements = usize::from(layout.element_count());
48:         std::alloc::Layout::array::<f32>(elements)
49:             .map_err(|source| ParameterLayoutError::Allocation { source })?;
50:         Ok(Self {
51:             values: vec![0.0; elements],
52:             joints,
53:             layout,
54:         })
55:     }
56: 
57:     pub(crate) fn columns(&self) -> NpyDimension {
58:         self.layout.dimensions()[1]
59:     }
60: 
61:     /// An external candidate is checked against both the actual joint bound and
62:     /// the retained buffer. A zero-column matrix still checks joint membership.
63:     pub(crate) fn row(&self, row: JointParameterRow) -> Option<&[f32]> {
64:         if usize::from(row.joint) >= self.joints.native_joint_count() {
65:             return None;
66:         }
67:         let columns = usize::from(self.columns());
68:         let start = row.offset().checked_mul(columns)?;
69:         self.values.get(start..start.checked_add(columns)?)
70:     }
71: 
72:     /// Each yielded block comes from the admitted matrix's own ordered extent.
73:     pub(crate) fn joints(&self) -> impl Iterator<Item = JointChannels<&[f32]>> {
74:         self.joints.ordinals().map(move |joint| {
75:             let columns = usize::from(self.columns());
76:             JointChannels::from_fn(|channel| {
77:                 let row = JointParameterRow::new(joint, channel);
78:                 let start = row.offset() * columns;
79:                 &self.values[start..start + columns]
80:             })
81:         })
82:     }
83: 
84:     pub(crate) fn add(
85:         &mut self,
86:         row: JointParameterRow,
87:         column: ModelParameterColumn,
88:         value: f32,
89:     ) -> Result<()> {
90:         let columns = usize::from(self.columns());
91:         let selected = self.row(row).ok_or(ParameterLayoutError::RowMembership)?;
92:         let length = selected.len();
93:         let start = row.offset() * columns;
94:         let entry = self
95:             .values
96:             .get_mut(start..start + length)
97:             .and_then(|values| values.get_mut(column.0))
98:             .ok_or(ParameterLayoutError::ColumnMembership)?;
99:         *entry += value;
100:         Ok(())
101:     }
102: 
103:     pub(crate) fn append_columns(&mut self, columns: NpyDimension) -> Result<()> {
104:         let previous = self.columns();
105:         if usize::from(columns) < usize::from(previous) {
106:             return Err(ParameterLayoutError::ColumnPrefix {
107:                 columns: previous,
108:                 available: columns,
109:             });
110:         }
111:         let mut expanded = Self::zeros(self.joints, columns)?;
112:         for (joint, rows) in self.joints().enumerate() {
113:             for channel in JointChannel::ALL {
114:                 let row = JointParameterRow::new(RigJointOrdinal::from(joint), channel);
115:                 let start = row.offset() * usize::from(columns);
116:                 expanded.values[start..start + usize::from(previous)]
117:                     .copy_from_slice(rows[channel]);
118:             }
119:         }
120:         *self = expanded;
121:         Ok(())
122:     }
123: 
124:     /// Transpose the selected leading columns for native `parameters @ transform`.
125:     pub(crate) fn tensor_transpose(&self, columns: NpyDimension) -> Result<Vec<f32>> {
126:         if usize::from(columns) > usize::from(self.columns()) {
127:             return Err(ParameterLayoutError::ColumnPrefix {
128:                 columns,
129:                 available: self.columns(),
130:             });
131:         }
132:         let mut transposed = Self::zeros(self.joints, columns)?.values;
133:         let rows = usize::from(self.layout.dimensions()[0]);
134:         for (joint, channels) in self.joints().enumerate() {
135:             for channel in JointChannel::ALL {
136:                 let row = JointParameterRow::new(RigJointOrdinal::from(joint), channel);
137:                 for column in 0..usize::from(columns) {
138:                     transposed[column * rows + row.offset()] = channels[channel][column];
139:                 }
140:             }
141:         }
142:         Ok(transposed)
143:     }
144: }

