378: fn parse_parameter_sets(lines: &[String], transform: &mut ParameterTransform) {
379:     for line in lines {
380:         let tokens = tokenize(line, " \t");
381:         if tokens.len() < 2 || tokens[0] != "parameterset" {
382:             continue;
383:         }
384:         let mut set = ModelParameterTable::filled(transform.num_parameters(), false);
385:         for name in &tokens[2..] {
386:             if let Some(index) = transform.parameter_index(&ModelParameterName::from(*name)) {
387:                 set[index] = true;
388:             }
389:         }
390:         transform
391:             .parameter_sets
392:             .insert(ParameterSetName::from(tokens[1]), set);
393:     }
394: }
395: 
396: fn parse_limits(lines: &[String], transform: &mut ParameterTransform) {
397:     for line in lines {
398:         let tokens = tokenize(line, " \t");
399:         // `limit <parameter> minmax [min, max]`; momentum's other limit kinds
400:         // (minmaxjoint, linear, ellipsoid, halfplane) are unused by MHR.
401:         if tokens.len() < 4 || tokens[0] != "limit" || tokens[2] != "minmax" {
402:             continue;
403:         }
404:         let Some(parameter) = transform.parameter_index(&ModelParameterName::from(tokens[1]))
405:         else {
406:             continue;
407:         };
408:         // `[min, max]`, optionally followed by a weight.
409:         let (Some(open), Some(close)) = (line.find('['), line.find(']')) else {
410:             continue;
411:         };
412:         let bounds: Vec<f32> = tokenize(&line[open + 1..close], ",")
413:             .iter()
414:             .filter_map(|t| t.parse::<f32>().ok())
415:             .collect();
416:         if bounds.len() == 2 {
417:             transform.limits.push(ParameterLimit {
418:                 parameter,
419:                 min: bounds[0],
420:                 max: bounds[1],
421:                 weight: line[close + 1..].trim().parse().unwrap_or(1.0),
422:             });
423:         }
424:     }
425: }
