24: impl SurfaceContacts {
25:     pub fn new(count: usize, faces: Vec<[u32; 3]>) -> Self {
26:         let seam_copies = vec![BTreeSet::new(); count];
27:         let mut edges = BTreeSet::new();
28:         for face in &faces {
29:             for k in 0..3 {
