61:         if pair_index >= FORAGE_FORM_MAX_PAIRS {
62:             return Err(());
63:         }
64:         match key.as_ref() {
65:             // Preserve duplicates so the reducer can reject malformed requests.
66:             "source" => {
67:                 if source.len() >= FORAGE_FORM_MAX_SOURCES
68:                     || value.len() > FORAGE_FORM_MAX_SOURCE_LEN
69:                 {
70:                     return Err(());
