1: //! Full host list cardinality and native allocation targets retain distinct roles.
2: use crate::collider::COLLIDER_BYTES;
3: use fabelgeist_gpu::prelude::{BufferByteLength, PassParameters};
4: 
5: /// Full host length, retained through update admission and its diagnostics.
6: #[derive(Clone, Copy, Debug, PartialEq, Eq)]
7: pub(super) struct ColliderCount(usize);
8: impl From<usize> for ColliderCount {
9:     fn from(colliders: usize) -> Self {
10:         Self(colliders)
11:     }
12: }
13: impl std::fmt::Display for ColliderCount {
14:     fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
15:         self.0.fmt(f)
16:     }
17: }
18: impl ColliderCount {
19:     pub(super) const EMPTY: Self = Self(0);
20:     pub(super) fn bind(self, parameters: &mut PassParameters) {
21:         parameters.insert("collider_count", self.0 as u32);
22:     }
23: }
24: 
25: /// Native capacity selected by allocation policy, without proving a live buffer.
26: /// Growth retains host rounding followed by unsigned-word truncation.
27: #[derive(Clone, Copy, Debug, PartialEq, Eq)]
28: pub(super) struct ColliderCapacity(u32);
29: impl ColliderCapacity {
30:     // Reserve 16 collider slots (1 KiB). Larger lists grow the buffer
31:     // to the next power of two.
32:     pub(super) const INITIAL: Self = Self(16);
33:     pub(super) fn for_count(count: ColliderCount) -> Self {
34:         Self(count.0.next_power_of_two() as u32)
35:     }
36:     pub(super) fn fit(self, count: ColliderCount) -> ColliderCapacityFit {
37:         if count.0 as u32 > self.0 {
38:             ColliderCapacityFit::GrowthRequired
39:         } else {
40:             ColliderCapacityFit::Retained
41:         }
42:     }
43:     pub(super) fn byte_length(self) -> BufferByteLength {
44:         (u64::from(self.0) * COLLIDER_BYTES as u64).into()
45:     }
46: }
47: 
48: #[derive(Clone, Copy, Debug, PartialEq, Eq)]
49: pub(super) enum ColliderCapacityFit {
50:     Retained,
51:     GrowthRequired,
52: }
