630: fn case_site_recovery_notice(
631:     members: &[CharacterView],
632:     conditions: &[CharacterStrategicCondition],
633:     site_id: &str,
634:     nearest_settlement: Option<&TravelDestination>,
635: ) -> Option<CaseSiteRecoveryNotice> {
636:     let incapacitated = members
637:         .iter()
638:         .filter_map(|member| {
639:             let condition = conditions.iter().find(|row| {
640:                 row.character_id == member.id
641:                     && row.status == adventuresim_stdb_client::IncapacitationStatus::Incapacitated
642:             })?;
643:             Some((member, condition))
644:         })
645:         .collect::<Vec<_>>();
646:     if incapacitated.is_empty() {
647:         return None;
648:     }
649:     let member_names = incapacitated
650:         .iter()
651:         .map(|(member, _)| member.name.as_str())
652:         .collect::<Vec<_>>()
653:         .join(", ");
654:     let has = |select: fn(&CharacterStrategicCondition) -> f32| {
655:         incapacitated
656:             .iter()
657:             .any(|(_, condition)| select(condition) > 0.001)
658:     };
659:     let mut causes = Vec::new();
660:     if has(|condition| condition.hunger) {
661:         causes.push("hunger");
662:     }
663:     if has(|condition| condition.thirst) {
664:         causes.push("thirst");
665:     }
666:     if has(|condition| condition.pain) {
667:         causes.push("pain");
668:     }
669:     if has(|condition| condition.blood_loss) {
670:         causes.push("blood loss");
671:     }
672:     if has(|condition| condition.fatigue) {
673:         causes.push("fatigue");
674:     }
675:     if has(|condition| condition.fear) {
676:         causes.push("fear");
677:     }
678:     let resource_blocked = causes.contains(&"hunger") || causes.contains(&"thirst");
679:     let (withdrawal_destination, withdrawal_href) = nearest_settlement.map_or_else(
680:         || ("a settlement".to_owned(), paths::CASE_SITE.url([&site_id])),
