1048:     commit_autoresolve_outcome(
1049:         ctx,
1050:         &encounter.encounter_id,
1051:         &encounter.party_id,
1052:         &member_ids,
1053:         5.0 + f32::from(encounter.enemy_count),
1054:         &outcome,
1055:     )?;
1056:     crate::corpse::persist_autoresolve_enemy_corpses(
1057:         ctx,
1058:         &encounter.encounter_id,
1059:         &encounter.party_id,
1060:         "",
1061:         None,
1062:         &encounter.archetype,
1063:         &outcome,
1064:     )?;
1065:     if outcome.resolution == BattleResolution::AlliesVictory {
1066:         let authored_followup = ctx
1067:             .db
1068:             .narrative_combat_followup_authority()
1069:             .encounter_id()
1070:             .find(&encounter.encounter_id)
1071:             .is_some();
1072:         if !authored_followup && let Some(item_id) = autoresolve_drop(&encounter.archetype)? {
1073:             add_to_party_inventory(
1074:                 ctx,
1075:                 &encounter.party_id,
1076:                 item_id,
1077:                 u32::from(encounter.enemy_count),
1078:             );
1079:         }
1080:         for member_id in &member_ids {
1081:             crate::condition::record_morale_event(
1082:                 ctx,
1083:                 *member_id,
1084:                 adventuresim_core::morale::MoraleEventKind::Victory,
1085:                 5.0 + f32::from(encounter.enemy_count),
1086:                 Some(encounter.encounter_id.clone()),
1087:             )?;
1088:         }
1089:     }
