1091:         BattleResolution::AlliesVictory => "victory",
1092:         BattleResolution::EnemiesVictory => "defeat",
1093:         BattleResolution::MutualIncapacitation => "mutual_incapacitation",
1094:         BattleResolution::Timeout => "timeout",
