14:     positions: Vec<[f32; 3]>,
15:     normals: Vec<[f32; 3]>,
16:     texcoords: Option<Vec<[f32; 2]>>,
17:     faces: Vec<[u32; 3]>,
18:     joints: fabelgeist_rig::PackedRigSkin<8>,
19:     weights: Vec<[f32; 8]>,
20:     targets: Vec<Target>,
21: }
22: 
23: impl<'a> CompactShell<'a> {
24:     pub(super) fn new(body: &RiggedMesh<'_>, shell: &'a RiggedShell<'a>) -> Self {
25:         let used = shell
26:             .faces
27:             .iter()
28:             .flatten()
29:             .copied()
30:             .collect::<std::collections::BTreeSet<_>>();
31:         let mut remap = vec![0; shell.positions.len()];
32:         for (index, vertex) in used.iter().enumerate() {
33:             remap[*vertex as usize] = index as u32;
34:         }
35:         let pick = |values: &[[f32; 3]]| {
36:             used.iter()
37:                 .map(|index| values[*index as usize])
38:                 .collect::<Vec<_>>()
39:         };
40:         let joints = shell.joint_indices.unwrap_or(body.joint_indices);
41:         let weights = shell.joint_weights.unwrap_or(body.joint_weights);
42:         Self {
43:             source: shell,
44:             plate_edges: shell
45:                 .plate_edges
46:                 .iter()
47:                 .filter(|edge| edge.iter().all(|i| used.contains(i)))
48:                 .map(|edge| edge.map(|i| remap[i as usize]))
49:                 .collect(),
50:             texcoords: shell
51:                 .texcoords
52:                 .map(|uv| used.iter().map(|i| uv[*i as usize]).collect()),
53:             positions: pick(shell.positions),
54:             normals: pick(shell.normals),
55:             faces: shell
56:                 .faces
57:                 .iter()
58:                 .map(|face| face.map(|vertex| remap[vertex as usize]))
59:                 .collect(),
60:             joints: joints.select(used.iter().map(|index| *index as usize)),
61:             weights: used.iter().map(|index| weights[*index as usize]).collect(),
62:             targets: shell
63:                 .morph_targets
64:                 .iter()
65:                 .map(|target| Target {
66:                     name: target.name.to_owned(),
67:                     positions: pick(target.position_deltas),
68:                     normals: pick(target.normal_deltas),
69:                 })
70:                 .collect(),
71:         }
72:     }
73: 
74:     pub(super) fn targets(&self) -> Vec<RiggedMorphTarget<'_>> {
75:         self.targets
76:             .iter()
77:             .map(|target| RiggedMorphTarget {
78:                 name: &target.name,
79:                 position_deltas: &target.positions,
80:                 normal_deltas: &target.normals,
81:             })
82:             .collect()
83:     }
84: 
85:     pub(super) fn rigged<'b>(&'b self, targets: &'b [RiggedMorphTarget<'b>]) -> RiggedShell<'b> {
86:         RiggedShell {
87:             textile_finish: self.source.textile_finish,
88:             surface: self.source.surface,
89:             plate_edges: &self.plate_edges,
90:             textures: self.source.textures.clone(),
91:             texcoords: self.texcoords.as_deref(),
92:             hinge: self.source.hinge,
93:             name: self.source.name,
94:             positions: &self.positions,
95:             normals: &self.normals,
96:             faces: &self.faces,
97:             joint_indices: Some(&self.joints),
98:             joint_weights: Some(&self.weights),
99:             morph_targets: targets,
100:             base_color: self.source.base_color,
101:             metallic: self.source.metallic,
102:             roughness: self.source.roughness,
103:         }
104:     }
105: }

