45: fn segment_intersects<F: GeometryFrame>(
46:     rect: SpatialBounds<F>,
47:     start: Position<F>,
48:     end: Position<F>,
49: ) -> bool {
50:     let min = Vec2::new(rect.min().metres().x, rect.min().metres().z);
51:     let max = Vec2::new(rect.max().metres().x, rect.max().metres().z);
52:     let start = Vec2::new(start.metres().x, start.metres().z);
53:     let end = Vec2::new(end.metres().x, end.metres().z);
54:     let delta = end - start;
55:     let (mut enter, mut leave) = (0.0_f32, 1.0_f32);
56:     for axis in 0..2 {
57:         if delta[axis] == 0.0 {
58:             if start[axis] < min[axis] || start[axis] > max[axis] {
59:                 return false;
60:             }
61:         } else {
62:             let a = (min[axis] - start[axis]) / delta[axis];
63:             let b = (max[axis] - start[axis]) / delta[axis];
64:             enter = enter.max(a.min(b));
65:             leave = leave.min(a.max(b));
66:             if enter > leave {
67:                 return false;
68:             }
69:         }
70:     }
71:     true
72: }
