1: use super::{CoordinateAxis, CuboidDimensions, GeometryError, GeometryFrame, Position};
2: use bevy::reflect::Reflect;
3: use serde::{Deserialize, Serialize};
4: 
5: /// Finite ordered bounds in one metre frame. Zero extents are permitted.
6: #[derive(Clone, Copy, Debug, PartialEq, Serialize, Reflect)]
7: #[serde(bound = "")]
8: #[reflect(opaque)]
9: pub struct SpatialBounds<F: GeometryFrame> {
10:     min: Position<F>,
11:     max: Position<F>,
12: }
13: impl<F: GeometryFrame> SpatialBounds<F> {
14:     /// Checked admission at native-vector production boundaries.
15:     pub fn from_metres(
16:         min: bevy::math::Vec3,
17:         max: bevy::math::Vec3,
18:     ) -> Result<Self, GeometryError> {
19:         Self::new(Position::from_metres(min)?, Position::from_metres(max)?)
20:     }
21:     pub fn new(min: Position<F>, max: Position<F>) -> Result<Self, GeometryError> {
22:         for (axis, (lower, upper)) in [CoordinateAxis::X, CoordinateAxis::Y, CoordinateAxis::Z]
23:             .into_iter()
24:             .zip(
25:                 min.metres()
26:                     .to_array()
27:                     .into_iter()
28:                     .zip(max.metres().to_array()),
29:             )
30:         {
31:             if lower > upper {
32:                 return Err(GeometryError::ReversedBounds { axis });
33:             }
34:         }
35:         Ok(Self { min, max })
36:     }
37:     pub fn at(point: Position<F>) -> Self {
38:         Self {
39:             min: point,
40:             max: point,
41:         }
42:     }
43:     pub fn min(self) -> Position<F> {
44:         self.min
45:     }
46:     pub fn max(self) -> Position<F> {
47:         self.max
48:     }
49:     /// Original f32 midpoint arithmetic; overflow is a construction error.
50:     pub fn centre(self) -> Result<Position<F>, GeometryError> {
51:         let metres = (self.min.metres() + self.max.metres()) * 0.5;
52:         super::error::finite(metres, super::GeometryRole::BoundsCentre)?;
53:         Position::from_metres(metres)
54:     }
55:     pub fn extent(self) -> Result<CuboidDimensions, GeometryError> {
56:         let metres = self.max.metres() - self.min.metres();
57:         super::error::finite(metres, super::GeometryRole::BoundsExtent)?;
58:         CuboidDimensions::from_metres(metres)
59:     }
60:     pub fn plan_half_extents(self) -> Result<super::PlanExtents, GeometryError> {
61:         let min = self.min.metres();
62:         let max = self.max.metres();
63:         super::PlanExtents::from_metres(bevy::math::Vec2::new(max.x - min.x, max.z - min.z) * 0.5)
64:     }
65:     /// Inclusive overlap, including face, edge and point tangency.
66:     pub fn overlaps(self, other: Self) -> bool {
67:         self.min.metres().cmple(other.max.metres()).all()
68:             && other.min.metres().cmple(self.max.metres()).all()
69:     }
70:     pub fn union(self, other: Self) -> Self {
71:         // min/max select already-admitted coordinates without arithmetic.
72:         Self {
73:             min: Position {
74:                 metres: self.min.metres().min(other.min.metres()),
75:                 frame: std::marker::PhantomData,
76:             },
77:             max: Position {
78:                 metres: self.max.metres().max(other.max.metres()),
79:                 frame: std::marker::PhantomData,
80:             },
81:         }
82:     }
83:     pub fn including(self, point: Position<F>) -> Self {
84:         self.union(Self::at(point))
85:     }
86: }
87: impl<'de, F: GeometryFrame> Deserialize<'de> for SpatialBounds<F> {
88:     fn deserialize<D: serde::Deserializer<'de>>(deserializer: D) -> Result<Self, D::Error> {
89:         #[derive(Deserialize)]
90:         #[serde(bound = "")]
91:         struct Bounds<F: GeometryFrame> {
92:             min: Position<F>,
93:             max: Position<F>,
94:         }
95:         let value = Bounds::deserialize(deserializer)?;
96:         Self::new(value.min, value.max).map_err(serde::de::Error::custom)
97:     }
98: }

