4: fn derive_walls(
5:     footprint: &[Cell],
6:     assignments: &BTreeMap<Cell, RoomIndex>,
7: ) -> Result<Vec<crate::WallSegment>, GenerationError> {
8:     let occupied = footprint.iter().copied().collect::<HashSet<_>>();
9:     let mut walls = Vec::new();
10:     for cell in footprint.iter().copied() {
11:         let assignment = |cell| {
12:             assignments
13:                 .get(&cell)
14:                 .copied()
15:                 .ok_or(GenerationError::RoomAllocation(
16:                     room_allocation::AllocationFailure::MissingCellAssignment { cell },
17:                 ))
18:         };
19:         let inside_room = assignment(cell)?.serialized_ordinal();
20:         for direction in Direction::ALL {
21:             let neighbour = cell.neighbour(direction);
22:             if !occupied.contains(&neighbour) {
23:                 walls.push(crate::WallSegment {
24:                     cell,
25:                     direction,
26:                     inside_room,
27:                     outside_room: None,
28:                 });
29:             } else if matches!(direction, Direction::North | Direction::East) {
30:                 let other_room = assignment(neighbour)?.serialized_ordinal();
31:                 if inside_room != other_room {
32:                     walls.push(crate::WallSegment {
33:                         cell,
34:                         direction,
35:                         inside_room,
36:                         outside_room: Some(other_room),
37:                     });
38:                 }
39:             }
40:         }
41:     }
42:     Ok(walls)
43: }
