45: fn derive_openings(
46:     walls: &[crate::WallSegment],
47:     requirements: &[RoomRequirement],
48:     archetype: BuildingArchetype,
49:     seed: Seed,
50:     level: StoreyIndex,
51:     straight_stair_core: Option<&StraightStairCore>,
52: ) -> Result<Vec<Opening>, GenerationError> {
53:     let storey = level;
54:     let serialized_level = storey.serialized_ordinal()?;
55:     let mut openings = Vec::new();
56:     let exterior_extent = GridEnvelope::from_walls(walls);
57:     let mut occupied_walls = HashSet::new();
58:     let mut required_room_connections = Vec::new();
59: 
60:     if let Some(core) = straight_stair_core.filter(|core| core.serves(serialized_level)) {
61:         let landing = core.landing_opening(walls, requirements, storey)?;
62:         occupied_walls.insert(landing.opening.wall);
63:         required_room_connections.push(room_connections::RoomConnection {
64:             left: landing.stair_hall,
65:             right: landing.neighbour,
66:         });
67:         openings.push(landing.opening);
68:     }
69: 
70:     if level == StoreyIndex::GROUND {
71:         entrances::append(
72:             walls,
73:             requirements,
74:             archetype,
75:             &mut openings,
76:             &mut occupied_walls,
77:         )?;
78:     }
79: 
80:     let edges = room_connections::shared_boundaries(walls, requirements, storey)?;
81:     let mut sets = DisjointSets::new(requirements.len());
82:     for connection in required_room_connections {
83:         sets.union(connection.left.index(), connection.right.index());
84:     }
85:     for edge in edges {
86:         if sets.union(edge.connection.left.index(), edge.connection.right.index()) {
87:             let wall_index = edge.candidates[edge.candidates.len() / 2];
88:             openings.push(Opening {
89:                 wall: wall_index,
90:                 kind: OpeningKind::Door,
91:                 width_metres: 0.95,
92:                 sill_metres: 0.0,
93:                 height_metres: 2.1,
94:             });
95:             occupied_walls.insert(wall_index);
96:         }
97:     }
98:     if sets.component_count() != 1 {
99:         return Err(GenerationError::DisconnectedStorey { level });
100:     }
101: 
102:     for (wall_index, wall) in walls.iter().enumerate() {
103:         if !wall.exterior() || occupied_walls.contains(&wall_index) {
104:             continue;
105:         }
106:         // The two-post HallHouse MVP keeps its roof-carrying transverse
107:         // frames uninterrupted. The large hall doors remain opening-first;
108:         // optional ordinary lights are deferred rather than allowing a
109:         // seed-dependent window to cut a roof brace.
110:         if archetype == BuildingArchetype::HallHouse {
111:             continue;
112:         }
113:         // A one-cell opening at a perimeter corner consumes the return pier:
114:         // its jamb/reveal then occupies the perpendicular facade's frame
115:         // plane. Keep corner cells solid; nearby bays still provide light.

