9: pub(super) fn generate_storeys(
10:     program: &BuildingProgram,
11:     edits: &[BuildingEdit],
12: ) -> Result<(Vec<StoreyPlan>, Option<StraightStairCore>), GenerationError> {
13:     if let Some(storey) = small_church::occupied_storey(program)? {
14:         if !edits.is_empty() {
15:             return Err(GenerationError::UnsupportedEdit(
16:                 "small church bays are edited through their service programme".to_owned(),
17:             ));
18:         }
19:         return Ok((vec![storey], None));
20:     }
21:     let footprint_cells = footprint_cells(program.footprint)?;
22:     // Preserve the public boundary's earliest programme-shape errors before
23:     // validating requirements that refer to those storeys.
24:     for (level, storey_program) in program.storeys.iter().enumerate() {
25:         if storey_program.rooms.is_empty() {
26:             return Err(GenerationError::EmptyStorey {
27:                 level: StoreyIndex::new(level),
28:             });
29:         }
30:         if storey_program.rooms.len() > footprint_cells.len() {
31:             return Err(GenerationError::TooManyRooms {
32:                 level: StoreyIndex::new(level),
33:                 rooms: storey_program.rooms.len(),
34:                 cells: footprint_cells.len(),
35:             });
36:         }
37:     }
38:     let core = resolve_straight_stair_core(program, &footprint_cells)?;
39:     let mut storeys = program
40:         .storeys
41:         .iter()
42:         .enumerate()
43:         .map(|(level, _)| {
44:             allocate_storey(
45:                 program,
46:                 edits,
47:                 &footprint_cells,
48:                 core.as_ref(),
49:                 StoreyIndex::new(level),
50:             )
51:         })
52:         .collect::<Result<Vec<_>, _>>()?;
53:     if program.church_program.is_some() || program.workplace_kind().is_some() {
54:         // These structural programmes own their envelopes; occupancy labels retain no duplicate grid walls.
55:         for storey in &mut storeys {
56:             storey.walls.clear();
57:             storey.openings.clear();
58:         }
59:     }
60:     Ok((storeys, core))
61: }
