1: //! Ordinal into the occupied storeys of a building programme.
2: //!
3: //! ```compile_fail
4: //! use adventuresim_building_generator::{RoomIndex, StoreyIndex};
5: //! let storey = StoreyIndex::GROUND;
6: //! let room: RoomIndex = storey;
7: //! ```
8: #[derive(Clone, Copy, Debug, Eq, PartialEq, Ord, PartialOrd, Hash, bevy::reflect::Reflect)]
9: #[reflect(opaque)]
10: pub struct StoreyIndex(usize);
11: impl StoreyIndex {
12:     pub const GROUND: Self = Self(0);
13:     pub const FIRST_UPPER: Self = Self(1);
14:     pub const fn new(index: usize) -> Self {
15:         Self(index)
16:     }
17:     pub const fn from_serialized(ordinal: u16) -> Self {
18:         Self(ordinal as usize)
19:     }
20:     pub fn serialized_ordinal(self) -> Result<u16, OrdinalError> {
21:         u16::try_from(self.0).map_err(|cause| OrdinalError {
22:             role: RecipeOrdinalRole::Storey,
23:             ordinal: self.0,
24:             cause,
25:         })
26:     }
27:     pub const fn index(self) -> usize {
28:         self.0
29:     }
30: 
31:     /// Classify an occupied elevation with the existing rounded station
32:     /// arithmetic. Admission rejects saturation of the packed storey ordinal.
33:     pub fn from_elevation(
34:         elevation: crate::spatial_geometry::Elevation<crate::Architectural>,
35:         storey_height: crate::spatial_geometry::PositiveLength,
36:     ) -> Result<Self, StoreyElevationError> {
37:         let ordinal = (elevation.metres() / storey_height.metres()).round();
38:         if !ordinal.is_finite() {
39:             return Err(StoreyElevationError::Overflow);
40:         }
41:         if ordinal < 0.0 {
42:             return Err(StoreyElevationError::BelowGround);
43:         }
44:         if ordinal > f32::from(u16::MAX) {
45:             return Err(StoreyElevationError::ExceedsRepresentation);
46:         }
47:         Ok(Self::new(ordinal as usize))
48:     }
49: }
50: impl serde::Serialize for StoreyIndex {
51:     fn serialize<S: serde::Serializer>(&self, s: S) -> Result<S::Ok, S::Error> {
52:         self.serialized_ordinal()
53:             .map_err(serde::ser::Error::custom)?
54:             .serialize(s)
55:     }
56: }
57: impl<'de> serde::Deserialize<'de> for StoreyIndex {
58:     fn deserialize<D: serde::Deserializer<'de>>(d: D) -> Result<Self, D::Error> {
59:         u16::deserialize(d).map(Self::from_serialized)
60:     }
61: }
