65:     #[error("elevation divided by storey height overflowed")]
66:     Overflow,
67:     #[error("rounded occupied storey lies below ground")]
68:     BelowGround,
69:     #[error("rounded occupied storey exceeds its packed u16 representation")]
70:     ExceedsRepresentation,
71: }
72: 
73: impl std::fmt::Display for StoreyIndex {
74:     fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
75:         self.0.fmt(f)
76:     }
77: }
