1: fn audit_vertical_circulation(plan: &BuildingPlan, issues: &mut Vec<AuditIssue>) {
2:     for (index, stair) in plan.stairs.iter().copied().enumerate() {
3:         let Stair::Straight {
4:             start,
5:             direction,
6:             base_height_metres,
7:             rise_metres,
8:             run_metres,
9:             ..
10:         } = stair
11:         else {
12:             continue;
13:         };
14:         let axis = direction_vector(direction);
15:         let lateral = Vec2::new(-axis.y, axis.x);
16:         let base_level = (base_height_metres / plan.storey_height_metres).round() as u16;
17:         audit_stair_landing(plan, index, start, base_level, axis, lateral, issues);
18:         let arrival_height = base_height_metres + rise_metres;
19:         let arrival_level = (arrival_height / plan.storey_height_metres).round() as u16;
20:         audit_stair_landing(
21:             plan,
22:             index,
23:             start + axis * run_metres,
24:             arrival_level,
25:             axis,
26:             lateral,
27:             issues,
28:         );
29:     }
30: }
31: 
32: fn audit_stair_landing(
33:     plan: &BuildingPlan,
34:     stair_index: usize,
35:     landing: Vec2,
36:     level: u16,
37:     axis: Vec2,
38:     lateral: Vec2,
39:     issues: &mut Vec<AuditIssue>,
40: ) {
41:     let Some(storey) = plan.storeys.iter().find(|storey| storey.level == level) else {
42:         issues.push(issue(
43:             "invalid_vertical_circulation",
44:             format!("straight stair {stair_index} reaches missing storey {level}"),
45:         ));
46:         return;
47:     };
48:     let Some(stair_hall) = storey.rooms.iter().find(|room| {
49:         room.kind == RoomKind::StairHall
50:             && room.cells.iter().any(|cell| {
51:                 let min = cell.centre() - Vec2::splat(crate::CELL_SIZE_METRES * 0.5);
52:                 let max = cell.centre() + Vec2::splat(crate::CELL_SIZE_METRES * 0.5);
53:                 landing.cmpge(min).all() && landing.cmple(max).all()
54:             })
55:     }) else {
56:         issues.push(issue(
57:             "invalid_vertical_circulation",
58:             format!("straight stair {stair_index} does not meet a stair hall on storey {level}"),
59:         ));
60:         return;
61:     };
62:     let landing_envelope_is_inside = [-0.45_f32, 0.0, 0.45].into_iter().all(|across| {
63:         [-0.45_f32, 0.0, 0.45].into_iter().all(|along| {
64:             let sample = landing + lateral * across + axis * along;
65:             stair_hall.cells.iter().any(|cell| {
66:                 let min = cell.centre() - Vec2::splat(crate::CELL_SIZE_METRES * 0.5 + 0.001);
67:                 let max = cell.centre() + Vec2::splat(crate::CELL_SIZE_METRES * 0.5 + 0.001);
68:                 sample.cmpge(min).all() && sample.cmple(max).all()
69:             })
70:         })
71:     });
72:     let has_room_door = storey.openings.iter().any(|opening| {
73:         if opening.kind != OpeningKind::Door {
74:             return false;
75:         }
76:         let Some(wall) = storey.walls.get(opening.wall).copied() else {
77:             return false;
78:         };
79:         wall.outside_room.is_some()
80:             && (wall.inside_room == stair_hall.id || wall.outside_room == Some(stair_hall.id))
81:     });
82:     if !landing_envelope_is_inside || !has_room_door {
83:         issues.push(issue(
84:             "invalid_vertical_circulation",
85:             format!(
86:                 "straight stair {stair_index} lacks a 0.90 m clear landing and room-graph doorway on storey {level}"
87:             ),
88:         ));
89:     }
90: }

