1: //! Room identity and priority at the wall-source ordinal boundary.
2: use super::*;
3: 
4: #[derive(Clone, Copy, Debug, Eq, PartialEq, Ord, PartialOrd)]
5: pub(super) struct RoomConnection {
6:     pub left: RoomIndex,
7:     pub right: RoomIndex,
8: }
9: 
10: pub(super) struct SharedBoundary {
11:     pub connection: RoomConnection,
12:     pub candidates: Vec<usize>,
13:     circulation_required: bool,
14:     preferred: bool,
15: }
16: 
17: pub(super) fn requirement(
18:     requirements: &[RoomRequirement],
19:     room: RoomIndex,
20:     storey: StoreyIndex,
21: ) -> Result<&RoomRequirement, GenerationError> {
22:     requirements
23:         .get(room.index())
24:         .ok_or(GenerationError::MissingRoomRequirement { storey, room })
25: }
26: 
27: pub(super) fn shared_boundaries(
28:     walls: &[crate::WallSegment],
29:     requirements: &[RoomRequirement],
30:     storey: StoreyIndex,
31: ) -> Result<Vec<SharedBoundary>, GenerationError> {
32:     let mut shared = BTreeMap::<RoomConnection, Vec<usize>>::new();
33:     for (wall_index, wall) in walls.iter().enumerate() {
34:         if let Some(other) = wall.outside_room {
35:             let inside = RoomIndex::from_serialized(wall.inside_room);
36:             let outside = RoomIndex::from_serialized(other);
37:             let connection = if inside < outside {
38:                 RoomConnection {
39:                     left: inside,
40:                     right: outside,
41:                 }
42:             } else {
43:                 RoomConnection {
44:                     left: outside,
45:                     right: inside,
46:                 }
47:             };
48:             shared.entry(connection).or_default().push(wall_index);
49:         }
50:     }
51:     let mut edges = shared
52:         .into_iter()
53:         .map(|(connection, candidates)| {
54:             let left = requirement(requirements, connection.left, storey)?;
55:             let right = requirement(requirements, connection.right, storey)?;
56:             Ok(SharedBoundary {
57:                 connection,
58:                 candidates,
59:                 preferred: left.preferred_neighbours.contains(&right.kind)
60:                     || right.preferred_neighbours.contains(&left.kind),
61:                 circulation_required: left.kind == RoomKind::StairHall
62:                     || right.kind == RoomKind::StairHall,
63:             })
64:         })
65:         .collect::<Result<Vec<_>, GenerationError>>()?;
66:     edges.sort_by_key(|edge| (!edge.circulation_required, !edge.preferred, edge.connection));
67:     Ok(edges)
68: }

