1: use super::*;
2: use crate::{BuildingPlan, OpeningUse, WallAssemblyId};
3: use bevy::math::Mat3;
4: 
5: const PANEL_WIDTH_METRES: f32 = 1.35;
6: const PANEL_HEIGHT_METRES: f32 = 0.62;
7: const MIN_PANEL_HEIGHT_METRES: f32 = 0.28;
8: const ENTRANCE_HEAD_GAP_METRES: f32 = 0.10;
9: const BRACKET_HEADROOM_METRES: f32 = 0.20;
10: const FACADE_OFFSET_METRES: f32 = 0.12;
11: const MAX_FACADE_PROJECTION_METRES: f32 = 0.8;
12: pub(super) const PANEL_THICKNESS_METRES: f32 = 0.06;
13: #[cfg(feature = "sign-render")]
14: pub(super) const PAINT_OFFSET_METRES: f32 = PANEL_THICKNESS_METRES * 0.5 + 0.001;
15: 
16: #[derive(Clone, Copy, Debug, Serialize, Deserialize)]
17: pub struct SignSite {
18:     pub wall: WallAssemblyId,
19:     /// Exterior wall face directly above a public entrance.
20:     pub attachment: Vec3,
21:     pub outward: Vec3,
22:     pub panel_size: Vec2,
23:     pub mounting: SignMounting,
24: }
25: 
26: impl SignSite {
27:     pub fn for_plan(plan: &BuildingPlan) -> Option<Self> {
28:         let (point, outward, head, wall_id) = if let Some(work) = &plan.workplace {
29:             let passage = work.passages.first()?;
30:             let point = Vec2::new(
31:                 (passage.bounds.min().metres().x + passage.bounds.max().metres().x) * 0.5,
32:                 0.0,
33:             );
34:             let wall = plan.wall_assemblies.iter().find(|wall| {
35:                 wall.frame.outward == Vec2::NEG_Y
36:                     && wall.base_elevation_metres > 0.0
37:                     && (wall.frame.origin.x - point.x).abs() < 0.1
38:             })?;
39:             (
40:                 point + wall.frame.outward * wall.thickness_metres * 0.5,
41:                 wall.frame.outward,
42:                 wall.base_elevation_metres,
43:                 wall.id,
44:             )
45:         } else {
46:             let opening = plan
47:                 .opening_assemblies
48:                 .iter()
49:                 .filter(|opening| {
50:                     matches!(opening.use_kind, OpeningUse::Door | OpeningUse::Gate)
51:                         && opening.sill_elevation_metres < 0.5
52:                         && plan.wall_assemblies.iter().any(|wall| {
53:                             wall.id == opening.host_wall
54:                                 && wall.frame.outside_room.is_none()
55:                                 && wall.storey_level == 0
56:                         })
57:                 })
58:                 .min_by(|a, b| a.frame.origin.y.total_cmp(&b.frame.origin.y))?;
59:             let wall = plan
60:                 .wall_assemblies
61:                 .iter()
62:                 .find(|wall| wall.id == opening.host_wall)?;
63:             (
64:                 opening.frame.origin + wall.frame.outward * wall.thickness_metres * 0.5,
65:                 wall.frame.outward,
66:                 opening.sill_elevation_metres + opening.profile.clear_height_metres(),
67:                 wall.id,
68:             )
69:         };
70:         let bottom = (head + ENTRANCE_HEAD_GAP_METRES).max(SIGN_PEDESTRIAN_CLEARANCE_METRES);
71:         let height =
72:             (plan.storey_height_metres - bottom - BRACKET_HEADROOM_METRES).min(PANEL_HEIGHT_METRES);
73:         if height < MIN_PANEL_HEIGHT_METRES {
74:             return None;
75:         }
76:         let outward = Vec3::new(outward.x, 0.0, outward.y);
77:         let panel_size = Vec2::new(PANEL_WIDTH_METRES, height);
78:         let attachment = facade_attachment(
79:             plan,
80:             Vec3::new(point.x, bottom + height * 0.5, point.y),
81:             outward,
82:             panel_size,
83:         );
84:         let mounting = SignMounting::find(plan, attachment, outward, panel_size)?;
85:         let attachment =
86:             attachment + outward * (mounting.contact - attachment).dot(outward).max(0.0);
87:         Some(Self {
88:             wall: wall_id,
89:             attachment,
90:             outward,
91:             panel_size,
92:             mounting,
93:         })
94:     }
95: 
96:     pub fn board(self, mount: SignMount) -> SignBoard {
97:         let right = match mount {
98:             SignMount::Wall => Vec3::Y.cross(self.outward),
99:             SignMount::Projecting => self.outward,
100:         };
101:         let projection = match mount {
102:             SignMount::Wall => FACADE_OFFSET_METRES,
103:             SignMount::Projecting => self.panel_size.x * 0.5 + FACADE_OFFSET_METRES,
104:         };
105:         SignBoard {
106:             centre: self.attachment + self.outward * projection,
107:             rotation: Quat::from_mat3(&Mat3::from_cols(right, Vec3::Y, right.cross(Vec3::Y))),
108:             size: self.panel_size,
109:         }
110:     }
111: 
112:     /// Physical overlap checks apply to the panel; its metal mounting foot touches the host wall.
113:     pub fn supports(self, plan: &BuildingPlan, mount: SignMount) -> bool {
114:         let board = self.board(mount);
115:         let half = Vec3::new(board.size.x, board.size.y, PANEL_THICKNESS_METRES) * 0.5;
116:         let extent = (board.rotation * Vec3::X).abs() * half.x
117:             + Vec3::Y * half.y
118:             + (board.rotation * Vec3::Z).abs() * half.z;
119:         let min = board.centre - extent;
120:         let max = board.centre + extent;
121:         if min.y < SIGN_PEDESTRIAN_CLEARANCE_METRES
122:             || !self.mounting.is_supported(plan, self.outward)
123:         {
124:             return false;
125:         }
126:         !plan.resolved_geometry.solids.iter().any(|solid| {
127:             let extent = solid_extent(solid);
128:             (max.min(solid.centre.metres() + extent) - min.max(solid.centre.metres() - extent))
129:                 .min_element()
130:                 > 0.005
131:         })
132:     }
133: }
134: 
135: /// Keep the panel clear of visible timberwork and masonry.
136: fn facade_attachment(
137:     plan: &BuildingPlan,
138:     attachment: Vec3,
139:     outward: Vec3,
140:     panel_size: Vec2,
141: ) -> Vec3 {
142:     let tangent = Vec3::Y.cross(outward);
143:     let mut projection = 0.0_f32;
144:     for solid in &plan.resolved_geometry.solids {
145:         let extent = solid_extent(solid);
146:         let offset = solid.centre.metres() - attachment;
147:         let side = offset.dot(tangent).abs();
148:         if side > panel_size.x * 0.5 + extent.dot(tangent.abs())
149:             || offset.y.abs() > panel_size.y * 0.5 + BRACKET_HEADROOM_METRES + extent.y
150:         {
151:             continue;
152:         }
153:         let face = offset.dot(outward) + extent.dot(outward.abs());
154:         if (0.0..=MAX_FACADE_PROJECTION_METRES).contains(&face) {
155:             projection = projection.max(face);
156:         }
157:     }
158:     attachment + outward * projection
159: }
160: 
161: pub(super) fn solid_extent(solid: &crate::ResolvedSolid) -> Vec3 {
162:     let rotation = solid_rotation(solid);
163:     let half = solid.size.metres() * 0.5;
164:     (rotation * Vec3::X).abs() * half.x
165:         + (rotation * Vec3::Y).abs() * half.y
166:         + (rotation * Vec3::Z).abs() * half.z
167: }
168: 
169: pub(super) fn solid_rotation(solid: &crate::ResolvedSolid) -> Quat {
170:     Quat::from_rotation_y(solid.yaw_radians.radians())
171:         * Quat::from_rotation_x(solid.crossfall_radians.radians())
172:         * Quat::from_rotation_z(solid.longfall_radians.radians())
173: }

