213:         .collect::<Vec<_>>();
214:     let mut height_breaks = vec![0.0, tower.wall_height_metres];
215:     height_breaks.extend(slit_ranges.iter().flat_map(|(low, high)| [*low, *high]));
216:     height_breaks.extend(portals.iter().flat_map(|portal| {
217:         [
218:             portal.sill_elevation_metres.max(0.0),
219:             (portal.sill_elevation_metres + portal.clear_height_metres)
220:                 .min(tower.wall_height_metres),
