232:         .find(|wall| wall.host_solids.contains(&solid.id));
233:     let Some(arch) = crate::arch_geometry::ArchGeometry::from_solid(solid, wall) else {
234:         return Ok(vec![solid.cuboid_envelope()]);
235:     };
236:     // Each convex arch section has a conservative box. This keeps the clear
237:     // crown traversable while retaining masonry above it, with bounded steps
238:     // along the curved intrados rather than one aperture-blocking host box.
239:     arch.strips()
240:         .into_iter()
241:         .map(|strip| {
242:             let outward = -strip.depth.normalize();
243:             let tangent = Vec3::Y.cross(outward);
244:             let local = |point: Vec3| Vec3::new(point.dot(tangent), point.y, point.dot(outward));
245:             let mut min = Vec3::splat(f32::INFINITY);
246:             let mut max = Vec3::splat(f32::NEG_INFINITY);
247:             for point in strip
248:                 .front
249:                 .into_iter()
250:                 .flat_map(|point| [point, point + strip.depth])
251:             {
252:                 min = min.min(local(point));
253:                 max = max.max(local(point));
254:             }
255:             let centre = (min + max) * 0.5;
256:             CollisionCuboid::from_metres(
257:                 solid.id,
258:                 tangent * centre.x + Vec3::Y * centre.y + outward * centre.z,
259:                 max - min,
260:                 (-tangent.z).atan2(tangent.x),
261:                 0.0,
262:                 0.0,
263:             )
264:         })
265:         .collect()
266: }
