54: impl<F: GeometryFrame> CollisionCuboid<F> {
55:     /// Native geometry adapter. Every field is checked before the solid exists.
56:     pub fn from_metres(
57:         source: ResolvedItemId,
58:         centre: Vec3,
59:         size: Vec3,
60:         yaw_radians: f32,
61:         crossfall_radians: f32,
62:         longfall_radians: f32,
63:     ) -> CollisionResult<Self> {
64:         let construct = || {
65:             Ok(Self {
66:                 source,
67:                 centre: Position::from_metres(centre)?,
68:                 size: CuboidDimensions::from_metres(size)?,
69:                 yaw_radians: Radians::new(yaw_radians)?,
70:                 crossfall_radians: Radians::new(crossfall_radians)?,
71:                 longfall_radians: Radians::new(longfall_radians)?,
72:             })
73:         };
74:         construct().map_err(|cause| CollisionError {
75:             source_id: source,
76:             cause,
77:         })
78:     }
79:     /// Separately rounded centre/half-extent envelope used by placement. Contact
80:     /// exclusion must instead use computed corners, which can reach Y=0 even
81:     /// when this expression rounds its minimum above the datum.
82:     pub fn bounds(self) -> CollisionResult<SpatialBounds<F>> {
83:         let half = self.size.metres() * 0.5;
84:         let orientation = bevy::math::Quat::from_rotation_y(self.yaw_radians.radians())
85:             * bevy::math::Quat::from_rotation_x(self.crossfall_radians.radians())
86:             * bevy::math::Quat::from_rotation_z(self.longfall_radians.radians());
87:         let rotated_half = (orientation * Vec3::X).abs() * half.x
88:             + (orientation * Vec3::Y).abs() * half.y
89:             + (orientation * Vec3::Z).abs() * half.z;
90:         SpatialBounds::from_metres(
91:             self.centre.metres() - rotated_half,
92:             self.centre.metres() + rotated_half,
93:         )
94:         .map_err(|cause| CollisionError {
95:             source_id: self.source,
96:             cause,
97:         })
98:     }
99: }
