15: pub(super) fn validate(
16:     lot: CityBuildingLot,
17:     placement: &TacticalBuildingPlacement,
18:     recipe: &Recipe,
19:     streets: &[CityStreetPatch],
20: ) -> Result<()> {
21:     let error = |issue| CityCompileError::Church {
22:         building: lot.id.into(),
23:         issue,
24:     };
25:     let plot = CityPlotBounds::try_from(lot)?;
26:     if !recipe.fits(placement, plot) {
27:         return Err(error(ChurchSitingIssue::GeometryOutsidePlot));
28:     }
29:     let door = recipe
30:         .door_point(placement, adventuresim_building_generator::Direction::West)?
31:         .ok_or(error(ChurchSitingIssue::MissingWestPortal))?
32:         .metres();
33:     let local_door = lot.orientation.world_to_local(door - lot.centre_metres);
34:     let apron = services::SERVICE_EDGE_CLEARANCE_METRES - ORDINARY_STREET_HALF_WIDTH_METRES;
35:     let street = lot.centre_metres
36:         + lot.orientation.local_to_world(Vec2::new(
37:             local_door.x,
38:             -lot.footprint_metres.y * 0.5 - apron,
39:         ));
40:     if !plot.contains(door) || !streets.iter().any(|patch| patch.contains(street)) {
41:         return Err(error(ChurchSitingIssue::StreetDisconnected));
42:     }
43:     let origin = recipe.collision.bounds.centre()?.metres();
44:     let physical = |p| {
45:         let point = placement
46:             .orientation
47:             .world_to_local(p - placement.centre_metres.metres())
48:             + Vec2::new(origin.x, origin.z);
49:         adventuresim_building_generator::spatial_geometry::Position::<
50:             adventuresim_building_generator::Architectural,
51:         >::from_metres(bevy::math::Vec3::new(point.x, 0.0, point.y))
52:     };
53:     // Door leaves are dynamic and excluded from static building collision.
54:     // This continuous body sweep includes the portal throat and its outer path.
55:     if !StandingClearance::new(
56:         &recipe.collision.cuboids,
57:         adventuresim_building_generator::spatial_geometry::Elevation::from_metres(0.0)?,
58:     )?
59:     .is_clear(physical(door)?, physical(street)?)
60:     {
61:         return Err(error(ChurchSitingIssue::ApproachBlocked));
62:     }
63:     Ok(())
64: }
