38: impl BuildingProgram {
39:     /// Search a bounded deterministic sequence and expose the structural error if it fails.
40:     pub fn validated_settlement(
41:         archetype: BuildingArchetype,
42:         usage: BuildingUse,
43:         initial_seed: Seed,
44:         size: Option<crate::ServiceBuildingSize>,
45:     ) -> Result<Self, crate::GenerationError> {
46:         let admit = |seed| {
47:             let mut program = Self::settlement(archetype, Some(usage), seed);
48:             if let Some(size) = size {
49:                 program = program.with_service_size(size);
50:             }
51:             crate::generate(&program).and_then(|plan| {
52:                 if plan.domestic_heating.is_some() {
53:                     crate::interior::validate_circulation(&plan)
54:                         .map_err(crate::GenerationError::BlockedDomesticCirculation)?;
55:                 }
56:                 Ok(program)
57:             })
58:         };
59:         let first_error = match admit(initial_seed) {
60:             Ok(program) => return Ok(program),
61:             Err(error) => error,
62:         };
63:         for attempt in 1..VALID_RECIPE_ATTEMPTS {
64:             let seed = RECIPE_ATTEMPT.seed(initial_seed, &[u64::from(attempt)]);
65:             if let Ok(program) = admit(seed) {
66:                 return Ok(program);
67:             }
68:         }
69:         Err(first_error)
70:     }
71: 
72:     /// The same compact recipe is used for playable buildings and distant shells.
73:     pub fn settlement(
74:         archetype: BuildingArchetype,
75:         usage: Option<BuildingUse>,
76:         seed: Seed,
77:     ) -> Self {
78:         let mut program = Self::fixture(archetype, seed);
79:         program.usage = usage.or_else(|| {
80:             (archetype == BuildingArchetype::ParishChurch).then_some(BuildingUse::ParishChurch)
81:         });
82:         if let Some(usage) = usage {
83:             program.assign_use(usage);
84:         }
85:         if usage == Some(BuildingUse::Dwelling)
