91:             program.domestic_heating = Some(crate::DomesticHeatingProgramme::HearthAndRearFedStove);
92:         }
93:         if matches!(
94:             archetype,
95:             BuildingArchetype::TownHouse
96:                 | BuildingArchetype::HallHouse
97:                 | BuildingArchetype::FachwerkCottage
98:                 | BuildingArchetype::FachwerkMerchantHouse
99:                 | BuildingArchetype::RenaissanceTownHall
100:                 | BuildingArchetype::ParishChurch
