102:             let roof = StreamId::new("building.roof-pitch")
103:                 .rng(seed, &[])
104:                 .range_f32(-1.0, 1.0);
105:             let height = StreamId::new("building.storey-height")
106:                 .rng(seed, &[])
107:                 .range_f32(-1.0, 1.0);
108:             // Half-hip gable framing needs the curated minimum pitch to clear
109:             // the opening heads below it. Vary those roofs upward from that seat.
110:             let roof = if matches!(
111:                 archetype,
112:                 BuildingArchetype::HallHouse | BuildingArchetype::RenaissanceTownHall
113:             ) {
114:                 roof.abs()
115:             } else {
116:                 roof
117:             };
118:             program.roof_pitch_degrees += roof * ROOF_VARIATION_DEGREES;
119:             program.storey_height_metres += height * STOREY_VARIATION_METRES;
120:         }
121:         if program.workplace_kind().is_some() || archetype == BuildingArchetype::ParishChurch {
122:             program = program.with_service_size(crate::ServiceBuildingSize::Medium);
123:         }
124:         program
125:     }
