1: fn audit_fortified_profile(plan: &BuildingPlan, issues: &mut Vec<AuditIssue>) {
2:     if !matches!(
3:         plan.archetype,
4:         BuildingArchetype::CourtyardCastle | BuildingArchetype::WalledKeep
5:     ) {
6:         return;
7:     }
8:     // These are declared game-profile gates for the modernized walled keep,
9:     // not universal measurements claimed for every sixteenth-century work.
10:     const MIN_MASONRY_THICKNESS: f32 = 1.2;
11:     const MAX_UNFLANKED_RUN: f32 = 36.0;
12: 
13:     for (index, wall) in plan.curtain_walls.iter().enumerate() {
14:         if wall.thickness_metres + 0.001 < MIN_MASONRY_THICKNESS {
15:             issues.push(issue(
16:                 "wall_too_thin_for_profile",
17:                 format!(
18:                     "curtain wall {index} is only {:.2} m thick",
19:                     wall.thickness_metres
20:                 ),
21:             ));
22:         }
23:         let delta = wall.end - wall.start;
24:         let length = delta.length();
25:         let axis = delta / length.max(0.001);
26:         let mut positions = plan
27:             .towers
28:             .iter()
29:             .filter_map(|tower| {
30:                 let projected = (tower.centre_metres() - wall.start).dot(axis);
31:                 let nearest = wall.start + axis * projected.clamp(0.0, length);
32:                 ((tower.centre_metres() - nearest).length() <= tower.radius_metres() + 0.25)
33:                     .then_some(projected.clamp(0.0, length))
34:             })
35:             .collect::<Vec<_>>();
36:         positions.extend([0.0, length]);
37:         positions.sort_by(f32::total_cmp);
38:         if positions
39:             .windows(2)
40:             .any(|pair| pair[1] - pair[0] > MAX_UNFLANKED_RUN)
41:         {
42:             issues.push(issue(
43:                 "unflanked_curtain",
44:                 format!("curtain wall {index} exceeds the declared flanking interval"),
45:             ));
46:         }
47:     }
48: 
49:     for (index, tower) in plan.towers.iter().enumerate() {
50:         if tower.wall_thickness_metres + 0.001 < MIN_MASONRY_THICKNESS {
51:             issues.push(issue(
52:                 "wall_too_thin_for_profile",
53:                 format!(
54:                     "tower {index} shell is only {:.2} m thick",
55:                     tower.wall_thickness_metres
56:                 ),
57:             ));
58:         }
59:         let interior_radius = tower.radius_metres() - tower.wall_thickness_metres;
60:         if plan.stairs.iter().any(|stair| matches!(
61:             stair,
62:             Stair::Spiral { centre, outer_radius_metres, .. }
63:                 if close_vec(*centre, tower.centre_metres()) && *outer_radius_metres > interior_radius - 0.1
64:         )) {
65:             issues.push(issue(
66:                 "insufficient_walk_clearance",
67:                 format!("tower {index} stair collides with its masonry shell"),
68:             ));
69:         }
70:     }
71:     if plan.archetype == BuildingArchetype::WalledKeep {
72:         audit_gate_defenses(plan, issues);
73:     }
74: }

