7: pub fn audit_plan(plan: &BuildingPlan) -> Result<Vec<AuditIssue>> {
8:     let mut issues = crate::heating::audit(plan)?;
9:     audit_battlement_runs(plan, &mut issues);
10: 
11:     for (index, walk) in plan.wall_walks.iter().enumerate() {
12:         if let WallWalk::Linear { width_metres, .. } = walk
13:             && *width_metres < 0.9
14:         {
15:             issues.push(issue(
16:                 "wall_walk_too_narrow",
17:                 format!("wall walk {index} is only {width_metres:.2} m wide"),
18:             ));
19:         }
20:         if let WallWalk::RectangularDeck {
21:             stairwell_centre,
22:             stairwell_size,
23:             elevation_metres,
24:             ..
25:         } = walk
26:         {
27:             if stairwell_size.min_element() < 0.9 {
28:                 issues.push(issue(
29:                     "stairwell_too_small",
30:                     format!("rectangular deck {index} has an undersized stairwell"),
31:                 ));
32:             }
33:             if !plan.stairs.iter().any(|stair| {
34:                 matches!(
35:                     stair,
36:                     Stair::Spiral { centre, base_height_metres, rise_metres, .. }
37:                         if close_vec(*centre, *stairwell_centre)
38:                             && close(*base_height_metres + *rise_metres, *elevation_metres)
39:                 )
40:             }) {
41:                 issues.push(issue(
42:                     "inaccessible_rectangular_deck",
43:                     format!("rectangular deck {index} has no stair reaching its stairwell"),
44:                 ));
45:             }
46:         }
47:     }
48: 
49:     audit_defensive_circuit(plan, &mut issues);
50:     audit_structural_assemblies(plan, &mut issues)?;
51: 
52:     if matches!(
53:         plan.archetype,
54:         BuildingArchetype::CourtyardCastle | BuildingArchetype::WalledKeep
55:     ) {
56:         audit_walk_roof_clearance(plan, &mut issues);
57:     }
58: 
59:     for (index, tower) in plan.towers.iter().enumerate() {
60:         if tower.battlement.is_some() && tower.roof.is_some() {
61:             issues.push(issue(
62:                 "obstructed_tower_deck",
63:                 format!("tower {index} has both a roof and an open fighting crown"),
64:             ));
65:         }
66:         let deck = plan.wall_walks.iter().any(|walk| {
67:             matches!(
68:                 walk,
69:                 WallWalk::Round { centre, elevation_metres, .. }
70:                     if close_vec(*centre, tower.centre_metres())
71:                         && close(*elevation_metres, tower.wall_height_metres)
72:             )
73:         });
74:         let access = plan.stairs.iter().any(|stair| {
75:             matches!(
76:                 stair,
77:                 Stair::Spiral { centre, base_height_metres, rise_metres, .. }
78:                     if close_vec(*centre, tower.centre_metres())
79:                         && close(*base_height_metres + *rise_metres, tower.wall_height_metres)
80:             )
81:         });
82:         if tower.battlement.is_some() && !deck {
83:             issues.push(issue(
84:                 "missing_tower_deck",
85:                 format!("battlemented tower {index} has no annular fighting deck"),
86:             ));
87:         }
88:         if tower.battlement.is_some() && !access {
89:             issues.push(issue(
