187:         self.0.fail_if_ack_stalled(now)
188:     }
189: 
190:     pub(crate) fn advance_presentation(&mut self, delta: Duration) -> Option<TacticalOutcome> {
191:         self.0.advance_presentation(delta)
192:     }
193: }
