195: pub(crate) fn presentation_outcome(resolution: TacticalMissionResolution) -> TacticalOutcome {
196:     match resolution {
197:         TacticalMissionResolution::Defeated
198:         | TacticalMissionResolution::DrivenOff
199:         | TacticalMissionResolution::Captured => TacticalOutcome::Victory,
200:         TacticalMissionResolution::Failed | TacticalMissionResolution::CaptureTargetKilled => {
201:             TacticalOutcome::Defeat
202:         }
203:     }
204: }
