301:         // the normal submit-and-wait path, nothing should ever be left
302:         // "pending acknowledgement" to retry - it must have resolved
303:         // synchronously within the single system run below (which would
304:         // also panic if `cmd.server_trigger` couldn't find its message
305:         // plumbing, proving that part of the local-resolve path runs too).
306:         let result: Result = app
307:             .world_mut()
308:             .run_system_once(check_mission_timeout)
309:             .expect("running the system should not fail");
310:         result.expect("check_mission_timeout should not return an error");
311: 
312:         let mut state = app.world_mut().resource_mut::<MissionState>();
313:         assert!(
314:             state
315:                 .terminal_retry_due(Duration::from_secs(9999), TERMINAL_ACK_TIMEOUT)
316:                 .is_none(),
317:             "standalone resolution should never leave a submission pending"
318:         );
319:     }
320: }

