175: impl CombatOutcomeHold {
176:     fn advance(
177:         &mut self,
178:         snapshot: TerminalCombatSnapshot,
179:         delta: Duration,
180:     ) -> Option<adventuresim_stdb_client::TacticalMissionResolution> {
181:         use adventuresim_stdb_client::TacticalMissionResolution;
182: 
183:         if snapshot.required_enemies == 0
184:             || snapshot.loaded_enemies < snapshot.required_enemies
185:             || !snapshot.enrollment_sealed
186:             || snapshot.loaded_party == 0
187:         {
188:             *self = Self::default();
189:             return None;
190:         }
191:         let enemies_defeated = snapshot.incapacitated_enemies >= snapshot.required_enemies;
192:         let party_defeated = snapshot.incapacitated_party >= snapshot.loaded_party;
193:         self.enemies = held_duration(self.enemies, enemies_defeated, delta);
194:         self.party = held_duration(self.party, party_defeated, delta);
195:         match (
196:             self.enemies >= COMBAT_OUTCOME_HOLD,
197:             self.party >= COMBAT_OUTCOME_HOLD,
198:         ) {
199:             (_, true) => Some(TacticalMissionResolution::Failed),
200:             (true, false) => Some(TacticalMissionResolution::Defeated),
201:             (false, false) => None,
202:         }
203:     }
204: }
205: 
206: fn held_duration(current: Duration, condition: bool, delta: Duration) -> Duration {
207:     if condition {
208:         current.saturating_add(delta)
209:     } else {
210:         Duration::ZERO
211:     }
212: }
