146: pub(crate) fn fail_stalled_terminal_submission(
147:     time: Res<Time>,
148:     mut state: ResMut<MissionState>,
149:     mut exit: MessageWriter<AppExit>,
150: ) {
151:     if state.fail_if_terminal_ack_stalled(time.elapsed()) {
152:         error!(
153:             timeout_seconds = TERMINAL_ACK_TIMEOUT.as_secs(),
154:             "Terminal reducer acknowledgement timed out; exiting without presenting an outcome"
155:         );
156:         exit.write(AppExit::Error(NonZeroU8::new(1).expect("one is non-zero")));
157:     }
158: }
