52: pub(crate) fn quest_generation_context_commitment(context_json: &str) -> Result<String, String> {
53:     let value: serde_json::Value =
54:         serde_json::from_str(context_json).map_err(|_| "Quest generation context is invalid")?;
55:     let canonical_json = serde_json::to_vec(&value)
56:         .map_err(|_| "Could not encode canonical quest generation context")?;
57:     let mut hasher = Sha256::new();
58:     for value in [
59:         b"adventuresim.quest-generation-context".as_slice(),
60:         QUEST_GENERATION_CONTEXT_COMMITMENT_VERSION
61:             .to_le_bytes()
62:             .as_slice(),
63:         canonical_json.as_slice(),
64:     ] {
65:         hasher.update((value.len() as u64).to_le_bytes());
66:         hasher.update(value);
67:     }
68:     Ok(format!("{:x}", hasher.finalize()))
69: }
