22: const TERMINAL_PRESENTATION_DELAY: Duration = Duration::from_secs(3);
23: const TERMINAL_ACK_TIMEOUT: Duration = Duration::from_secs(10);
24: /// Default grace for an empty party before the mission is abandoned. Overridable
25: /// per mission via `MissionState::new` (see the tactical server's
26: /// `--party-reconnect-grace` flag).
27: pub(crate) const PARTY_RECONNECT_GRACE: Duration = Duration::from_secs(10);
