52: fn commit_terminal_resolution(
53:     resolution: TacticalMissionResolution,
54:     now: Duration,
55:     conn: Option<Res<SpacetimeDb>>,
56:     consequences: Res<TacticalConsequenceAccumulator>,
57:     mut state: ResMut<MissionState>,
58:     cmd: Commands,
59: ) -> Result {
60:     let frozen = FrozenTerminal {
61:         resolution,
62:         receipt: super::receipt::tactical_consequence_receipt(&consequences),
63:     };
64:     let Some(frozen) = state.begin_terminal_submission(frozen, now, TERMINAL_ACK_TIMEOUT) else {
65:         return Ok(());
66:     };
67:     submit_frozen_terminal(frozen, now, conn, state, cmd)
68: }
69: 
70: fn submit_frozen_terminal(
71:     frozen: FrozenTerminal,
72:     now: Duration,
73:     conn: Option<Res<SpacetimeDb>>,
74:     mut state: ResMut<MissionState>,
75:     mut cmd: Commands,
76: ) -> Result {
77:     // Standalone mode (no SpacetimeDB connection): there is no strategic
78:     // authority to submit to, so resolve immediately and locally instead of
79:     // submitting-and-waiting. Nothing is ever left "pending" in this mode,
80:     // so `process_terminal_submission_results` is simply not scheduled.
81:     let Some(conn) = conn else {
82:         if let Some(outcome) = state.apply_terminal_submission_result(
83:             TerminalSubmissionResult::Accepted,
84:             now,
85:             TERMINAL_RETRY_BACKOFF,
86:             TERMINAL_PRESENTATION_DELAY,
87:         ) {
88:             cmd.server_trigger(ToClients {
89:                 targets: SendTargets::CLIENTS_ONLY,
90:                 message: TacticalOutcomeResponse { outcome },
91:             });
92:             info!(
93:                 ?outcome,
94:                 resolution = ?frozen.resolution,
95:                 "Mission terminal resolved locally (standalone mode)"
96:             );
97:         }
98:         return Ok(());
99:     };
100:     if let Err(error) = conn.submit_terminal(frozen.resolution, frozen.receipt) {
101:         state.terminal_enqueue_failed(now, TERMINAL_RETRY_BACKOFF);
102:         warn!(
103:             "Terminal result enqueue failed; retrying in {}s: {error}",
104:             TERMINAL_RETRY_BACKOFF.as_secs()
105:         );
106:     } else {
107:         info!(resolution = ?frozen.resolution, "Terminal result queued; awaiting reducer acceptance");
108:     }
109:     Ok(())
110: }
