314: /// Resolves direct containment and ultimate custody while validating every
315: /// persisted object and edge in the chain. Containment is the direct location;
316: /// the root character, party, or fixture remains the operational authority.
317: pub(crate) fn resolve_object_custody(
318:     ctx: &ReducerContext,
319:     object: &InventoryObject,
320: ) -> Result<ResolvedObjectCustody, String> {
321:     let object_id = object_id_from_u64(object.id)?;
322:     let initial_storage = persisted_location_custody(ctx, object)?;
323:     let direct_parent = ctx
324:         .db
325:         .inventory_containment()
326:         .child_object_id()
327:         .find(object.id)
328:         .map(|edge| edge.parent_object_id);
329:     let direct = match direct_parent {
330:         Some(parent_id) => OperationalCustody::Container(object_id_from_u64(parent_id)?),
331:         None => initial_storage.clone(),
332:     };
333:     let object_custody =
334:         ObjectCustody::try_new(object_id, direct).map_err(|error| error.to_string())?;
335: 
336:     let mut cursor = direct_parent;
337:     let mut visited = BTreeSet::from([object.id]);
338:     let mut carried_backing: Option<OperationalCustody> = match &initial_storage {
339:         custody @ (OperationalCustody::Character(_) | OperationalCustody::Party(_)) => {
340:             Some(custody.clone())
341:         }
342:         _ => None,
343:     };
344:     let mut depth = 0usize;
345:     loop {
346:         let Some(parent_id) = cursor else {
347:             return Ok(ResolvedObjectCustody {
348:                 object: object_custody,
349:                 root: initial_storage,
350:             });
351:         };
352:         depth = next_containment_depth(depth)?;
353:         if !visited.insert(parent_id) {
354:             return Err("Inventory containment custody contains a cycle".into());
355:         }
356:         let parent = ctx
357:             .db
358:             .inventory_object()
359:             .id()
360:             .find(parent_id)
361:             .ok_or("Inventory containment parent object is missing")?;
362:         let parent_storage = persisted_location_custody(ctx, &parent)?;
363:         if matches!(
364:             &parent_storage,
365:             OperationalCustody::Character(_) | OperationalCustody::Party(_)
366:         ) {
367:             if carried_backing
368:                 .as_ref()
369:                 .is_some_and(|expected| expected != &parent_storage)
370:             {
371:                 return Err("Contained objects have conflicting carried custody".into());
372:             }
373:             carried_backing = Some(parent_storage.clone());
