7: /// A nonempty, bounded roster with unique durable character IDs.
8: ///
9: /// Database and SDK adapters carry the IDs; scalar launch counts are derived
10: /// from this validated snapshot, never maintained as a second stored fact.
11: #[derive(Clone, Debug, Eq, PartialEq)]
12: pub struct TacticalPartyRoster {
13:     members: Vec<u64>,
14: }
15: 
16: #[derive(Clone, Copy, Debug, Eq, PartialEq)]
17: pub enum TacticalRosterError {
18:     Empty,
19:     TooLarge,
20:     DuplicateMember,
21: }
22: 
23: impl fmt::Display for TacticalRosterError {
24:     fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
25:         formatter.write_str(match self {
26:             Self::Empty => "A tactical mission requires at least one living party member",
27:             Self::TooLarge => "Party exceeds the tactical receipt participant limit",
28:             Self::DuplicateMember => "Tactical participant authority contains duplicate members",
29:         })
30:     }
31: }
32: 
33: impl std::error::Error for TacticalRosterError {}
34: 
35: impl TryFrom<Vec<u64>> for TacticalPartyRoster {
36:     type Error = TacticalRosterError;
37: 
38:     fn try_from(members: Vec<u64>) -> Result<Self, Self::Error> {
39:         if members.is_empty() {
40:             return Err(TacticalRosterError::Empty);
41:         }
42:         if members.len() > MAX_TACTICAL_RECEIPT_PARTICIPANTS {
43:             return Err(TacticalRosterError::TooLarge);
44:         }
45:         if members.iter().collect::<BTreeSet<_>>().len() != members.len() {
46:             return Err(TacticalRosterError::DuplicateMember);
47:         }
48:         Ok(Self { members })
49:     }
50: }
51: 
52: impl TacticalPartyRoster {
53:     pub fn expected_members(&self) -> NonZeroU32 {
54:         NonZeroU32::new(u32::try_from(self.members.len()).expect("the roster limit fits u32"))
55:             .expect("a validated roster is nonempty")
56:     }
57: 
58:     pub fn into_member_ids(self) -> Vec<u64> {
59:         self.members
60:     }
61: }
