492: /// Put a character in an existing [`TacticalServer`].
493: #[reducer]
494: pub fn enter_mission(
495:     ctx: &ReducerContext,
496:     character_id: u64,
497:     server: Identity,
498: ) -> Result<(), String> {
499:     if ctx.sender() != server {
500:         return Err("Only the owning tactical server can enroll characters".into());
501:     }
502:     crate::character::require_living_character(ctx, character_id)?;
503:     // Check character exists
504:     let mut character = ctx
505:         .db
506:         .character()
507:         .id()
508:         .find(character_id)
509:         .ok_or_else(|| format!("Character {character_id} not found"))?;
510:     // An unassigned character may join. An assignment to this server is an
511:     // idempotent retry, and a stale assignment whose server no longer exists
512:     // may be reclaimed. Never steal a character from another active server.
513:     if character.has_tactical_server_assignment()
514:         && character.server != server
515:         && ctx
516:             .db
517:             .tactical_server_authority()
518:             .identity()
519:             .find(character.server)
520:             .is_some()
521:     {
522:         return Err("Character is already assigned to another active tactical server".into());
523:     }
524: 
525:     let server = ctx
526:         .db
527:         .tactical_server_authority()
528:         .identity()
529:         .find(server)
530:         .ok_or_else(|| format!("Server {server} not found"))?;
531: 
532:     if !character.temporary {
533:         let enemy = server.enemy_character_ids.contains(&character_id);
534:         let character_party = character.party_id.as_deref();
535:         if !enemy {
536:             if !server.authorized_party_member_ids.contains(&character_id) {
537:                 return Err(
538:                     "Character was not authorized when this tactical mission was requested".into(),
539:                 );
540:             }
541:             if character_party != Some(server.party_id.as_str()) {
542:                 return Err("Character is not a member of this mission's party".into());
543:             }
544:         }
545:         let party = ctx
546:             .db
547:             .party_authority()
548:             .id()
549:             .find(&server.party_id)
550:             .ok_or("Mission party no longer exists")?;
551:         let mission = ctx
552:             .db
553:             .mission_authority()
554:             .id()
555:             .find(&server.mission_id)
556:             .ok_or("Mission authority no longer exists")?;
557:         if mission.party_id != party.id {
558:             return Err("Mission authority changed before enrollment".into());
559:         }
560:     }
561: 
562:     character.server = server.identity;
563:     ctx.db.character().id().update(character);
564: 
565:     Ok(())
566: }
