571:     let server = ctx
572:         .db
573:         .tactical_server_authority()
574:         .identity()
575:         .find(ctx.sender())
576:         .ok_or("Only a registered tactical server can remove characters")?;
577:     let character = ctx
578:         .db
579:         .character()
580:         .id()
581:         .find(character_id)
