585: 
586: fn leave_mission_for_server(
587:     ctx: &ReducerContext,
588:     mut character: Character,
589:     server: Identity,
590: ) -> Result<(), String> {
591:     if !character.has_tactical_server_assignment() || character.server != server {
592:         return Err("Only the character's owning tactical server can remove it".into());
593:     }
594:     let character_id = character.id;
595:     if character.temporary {
596:         log::info!("Leaving mission for character #{character_id}: removing temporary character..");
597:         crate::character::delete_temporary_character(ctx, character)?;
598:     } else {
599:         log::info!("Leaving mission for character #{character_id}: resetting server info..");
600:         character.server = Identity::ZERO;
601:         ctx.db.character().id().update(character);
602:     }
603: 
604:     Ok(())
605: }
