607: /// Retire an interrupted standalone development session before its persistent
608: /// profile is reused. The bootstrap capability is checked by the only caller;
609: /// keeping the cleanup here lets it share the authoritative mission teardown
610: /// primitives without exposing a new reducer.
611: #[derive(Clone, Copy, Debug, Eq, PartialEq)]
612: enum MissionCaseIdentity<'a> {
613:     Standalone { mission_id: &'a str },
614:     Other,
615: }
616: 
617: impl<'a> MissionCaseIdentity<'a> {
618:     fn parse(value: &'a str) -> Self {
619:         let mut components = value.splitn(3, ':');
620:         match (components.next(), components.next(), components.next()) {
621:             (Some("case"), Some("standalone"), Some(mission_id)) if !mission_id.is_empty() => {
622:                 Self::Standalone { mission_id }
623:             }
624:             _ => Self::Other,
625:         }
626:     }
627: }
