1026:     }
1027:     conn.reducers()
1028:         .enter_mission(join.character_id.0, ready.identity())?;
1029:     state.begin_enrollment();
1030:     let token = fresh_reconnect_token();
1031:     commands.entity(client).insert((
1032:         LoadingPlayer {
1033:             requested_character: join.character_id,
1034:         },
