1143:     use adventuresim_core::mission::*;
1144:     if receipt.party.len() > MAX_TACTICAL_RECEIPT_PARTICIPANTS
1145:         || receipt.equipment_contacts.len() > MAX_TACTICAL_EQUIPMENT_CONTACTS
1146:     {
1147:         return Err("Tactical receipt exceeds record limits".into());
1148:     }
1149:     let mut characters = HashSet::new();
1150:     for consequence in &receipt.party {
1151:         if !characters.insert(consequence.character_id) {
1152:             return Err("Tactical receipt contains a duplicate character".into());
1153:         }
1154:         if consequence.injuries.len() > MAX_TACTICAL_INJURIES_PER_PARTICIPANT
1155:             || !consequence.blood_loss_fraction.is_finite()
1156:             || !(0.0..=1.0).contains(&consequence.blood_loss_fraction)
1157:             || consequence.ammunition_used > MAX_TACTICAL_AMMUNITION_USED
1158:             || consequence.injuries.iter().any(|injury| {
1159:                 !injury.cut_damage.is_finite()
1160:                     || !injury.blunt_damage.is_finite()
1161:                     || !injury.max_single_hit_blunt_damage.is_finite()
1162:                     || !(0.0..=MAX_TACTICAL_DAMAGE_PER_HIT).contains(&injury.cut_damage)
1163:                     || !(0.0..=MAX_TACTICAL_DAMAGE_PER_HIT).contains(&injury.blunt_damage)
1164:                     || !(0.0..=injury.blunt_damage).contains(&injury.max_single_hit_blunt_damage)
1165:                     || injury.cut_damage + injury.blunt_damage > MAX_TACTICAL_DAMAGE_PER_HIT
1166:             })
1167:         {
1168:             return Err("Tactical receipt contains out-of-range consequences".into());
1169:         }
1170:     }
1171:     let mut contacted_items = HashSet::new();
1172:     for contact in &receipt.equipment_contacts {
1173:         if !contacted_items.insert(contact.inventory_item_id) {
1174:             return Err("Tactical receipt contains duplicate equipment contacts".into());
1175:         }
1176:         if !contact.contact_stress.is_finite()
1177:             || !(0.0..=MAX_TACTICAL_CONTACT_STRESS).contains(&contact.contact_stress)
1178:         {
1179:             return Err("Tactical equipment contact is not bounded to a receipt member".into());
1180:         }
1181:     }
1182:     Ok(())
1183: }
