258: pub(crate) fn check_mission_timeout(
259:     commands: Commands,
260:     time: Res<Time>,
261:     conn: Option<Res<SpacetimeDb>>,
262:     consequences: Res<TacticalConsequenceAccumulator>,
263:     mut state: ResMut<MissionState>,
264: ) -> Result {
265:     if !state.tick_timeout(time.delta()) || !state.terminal_is_running() {
266:         return Ok(());
267:     }
268:     info!("Mission timeout, committing bounded failure fallback");
269:     commit_terminal_resolution(
270:         TacticalMissionResolution::Failed,
271:         time.elapsed(),
272:         conn,
273:         consequences,
274:         state,
275:         commands,
276:     )
277: }
