619: fn mission_candidate_is_current(
620:     ctx: &ReducerContext,
621:     mission: &MissionAuthority,
622:     candidate: &MissionOutcomeCandidate,
623: ) -> Result<bool, String> {
624:     if mission.status != MissionAttemptStatus::Bound
625:         || candidate.mission_id != mission.id
626:         || candidate.case_id != mission.case_id
627:         || mission.case_site_id.as_ref() != Some(&candidate.case_site_id)
628:         || mission.hostile_group_id.as_deref() != Some(&candidate.hostile_group_id)
629:     {
630:         return Ok(false);
631:     }
632:     let Some(capability) = ctx
633:         .db
634:         .mission_approach_capability()
635:         .id()
636:         .find(&candidate.capability_id)
637:     else {
638:         return Ok(false);
639:     };
640:     if !capability.active
641:         || capability.observer_character_id != mission.observer_character_id
642:         || capability.case_id != candidate.case_id
643:         || capability.case_site_id != candidate.case_site_id
644:         || capability.hostile_group_id != candidate.hostile_group_id
645:         || capability.path_index != candidate.path_index
646:         || capability.objective_id != candidate.objective_id
647:         || capability.resolution != candidate.resolution
648:         || capability.weight != candidate.weight
649:         || capability.capture_subject_id != candidate.capture_subject_id
650:         || capability.capture_custody_version != candidate.capture_custody_version
651:     {
652:         return Ok(false);
653:     }
654:     let Some(case) = ctx.db.case_authority().id().find(&candidate.case_id) else {
655:         return Ok(false);
656:     };
657:     if case.resolution_status != CaseStatus::Open {
658:         return Ok(false);
659:     }
660:     let expression: adventuresim_core::case::ObjectiveExpression =
661:         serde_json::from_str(&case.objective_expression_json)
662:             .map_err(|_| "Case objective authority is invalid")?;
663:     let facts = ctx
664:         .db
665:         .case_outcome_fact()
666:         .case_id()
667:         .filter(&case.id)
668:         .map(|row| {
669:             serde_json::from_str::<adventuresim_core::case::OutcomeFact>(&row.fact_json)
670:                 .map_err(|_| "Stored outcome fact is invalid".to_string())
671:         })
672:         .collect::<Result<Vec<_>, _>>()?;
673:     let core_case_id =
674:         adventuresim_core::case::CaseId::new(case.id.clone()).map_err(|_| "Case ID is invalid")?;
675:     let evaluation = expression.evaluate(&core_case_id, &mission.party_id, &facts);
676:     let Some(path) = expression
677:         .alternatives
678:         .get(usize::from(candidate.path_index))
679:     else {
680:         return Ok(false);
681:     };
682:     let Some(objective_index) = path
683:         .objectives
684:         .iter()
685:         .position(|objective| objective.id.as_str() == candidate.objective_id)
686:     else {
687:         return Ok(false);
688:     };
689:     if evaluation
690:         .alternatives
691:         .get(usize::from(candidate.path_index))
692:         .and_then(|path| path.get(objective_index))
693:         .is_none_or(|progress| progress.state != adventuresim_core::case::EvaluationState::Pending)
694:     {
695:         return Ok(false);
696:     }
697:     if candidate.resolution != HostileResolutionKind::Captured {
698:         return Ok(true);
699:     }
700:     let (Some(subject_id), Some(version)) = (
701:         candidate.capture_subject_id.as_ref(),
702:         candidate.capture_custody_version,
703:     ) else {
704:         return Ok(false);
705:     };
706:     Ok(ctx
707:         .db
708:         .case_custody()
709:         .object_id()
710:         .find(subject_id)
711:         .is_some_and(|custody| {
712:             custody.case_id == candidate.case_id
713:                 && custody.object_kind == CustodyObjectKind::Subject
714:                 && custody.holder_kind == CustodyHolderKind::Site
715:                 && custody.holder_id == candidate.case_site_id.as_str()
716:                 && custody.version == version
717:         }))
718: }
