720: fn mission_outcome_draw(mission: &MissionAuthority, outcomes: &[MissionOutcomeCandidate]) -> Seed {
721:     let mut candidates = outcomes.to_vec();
722:     candidates.sort_by(|left, right| left.id.cmp(&right.id));
723:     let mut fields = vec![mission.outcome_entropy.to_le_bytes().to_vec()];
724:     for candidate in &candidates {
725:         fields.push(candidate.id.as_bytes().to_vec());
726:         fields.push(candidate.capability_id.as_bytes().to_vec());
727:         fields.push(candidate.weight.to_le_bytes().to_vec());
728:         fields.push(vec![candidate.resolution as u8]);
729:     }
730:     let fields = fields.iter().map(Vec::as_slice).collect::<Vec<_>>();
731:     fabelgeist_determinism::Seed::derive(
732:         mission.party_id.as_bytes(),
733:         fabelgeist_determinism::StreamId::new("mission.outcome-candidates"),
734:         &fields,
735:     )
736: }
