149: }
150: 
151: impl MissionAttemptState {
152:     pub fn parse(flat: FlatMissionState) -> Result<Self, StateParseError> {
153:         let FlatMissionState {
154:             status,
155:             case_site_id,
156:             hostile_group_id,
157:             resolution,
158:             subject_id,
159:             custody_version,
160:         } = flat;
161:         let binding = match (case_site_id, hostile_group_id) {
162:             (None, None) => None,
163:             (Some(case_site_id), Some(hostile_group_id)) => Some(MissionBinding {
164:                 case_site_id,
165:                 hostile_group_id,
166:             }),
167:             _ => {
168:                 return Err(StateParseError(
169:                     "mission binding must contain both identifiers",
170:                 ));
171:             }
172:         };
173:         match (status, resolution, subject_id, custody_version) {
174:             (MissionAttemptStatus::Bound, None, None, None) => Ok(Self::Bound { binding }),
175:             (
176:                 MissionAttemptStatus::Committed,
177:                 Some(HostileResolutionKind::Defeated),
178:                 None,
179:                 None,
180:             ) => Ok(Self::Committed {
181:                 binding,
182:                 resolution: HostileResolution::Defeated,
183:             }),
184:             (
185:                 MissionAttemptStatus::Committed,
186:                 Some(HostileResolutionKind::DrivenOff),
187:                 None,
188:                 None,
189:             ) => Ok(Self::Committed {
190:                 binding,
191:                 resolution: HostileResolution::DrivenOff,
192:             }),
193:             (
194:                 MissionAttemptStatus::Committed,
195:                 Some(HostileResolutionKind::Surrendered),
196:                 None,
197:                 None,
198:             ) => Ok(Self::Committed {
199:                 binding,
200:                 resolution: HostileResolution::Surrendered,
201:             }),
202:             (
203:                 MissionAttemptStatus::Committed,
204:                 Some(HostileResolutionKind::Captured),
205:                 Some(subject_id),
206:                 Some(version),
207:             ) => Ok(Self::Committed {
208:                 binding,
209:                 resolution: HostileResolution::Captured {
210:                     subject_id,
211:                     custody_version: CustodyVersion::new(version),
212:                 },
213:             }),
214:             (
215:                 MissionAttemptStatus::Committed,
216:                 Some(HostileResolutionKind::CaptureTargetKilled),
217:                 Some(subject_id),
218:                 None,
219:             ) => Ok(Self::Committed {
220:                 binding,
221:                 resolution: HostileResolution::CaptureTargetKilled { subject_id },
222:             }),
223:             (MissionAttemptStatus::Failed, None, None, None) => Ok(Self::Failed),
224:             (MissionAttemptStatus::Cancelled, None, None, None) => Ok(Self::Cancelled),
225:             _ => Err(StateParseError(
226:                 "mission status and resolution fields disagree",
227:             )),
228:         }
229:     }
230: }
