779: pub(crate) fn complete_bound_mission_success(
780:     ctx: &ReducerContext,
781:     mission_id: &str,
782: ) -> Result<bool, String> {
783:     let mut mission = ctx
784:         .db
785:         .mission_authority()
786:         .id()
787:         .find(mission_id.to_string())
788:         .ok_or("Mission authority not found")?;
789:     mission.parsed_state().map_err(|error| error.to_string())?;
790:     if mission.status == MissionAttemptStatus::Committed {
791:         return Ok(false);
792:     }
793:     if mission.status != MissionAttemptStatus::Bound {
794:         return Err("Mission attempt is no longer eligible for completion".into());
795:     }
796:     let mut candidates = Vec::new();
797:     for candidate in ctx
798:         .db
799:         .mission_outcome_candidate()
800:         .mission_id()
801:         .filter(&mission.id)
802:     {
803:         if mission_candidate_is_current(ctx, &mission, &candidate)? {
804:             candidates.push(candidate);
805:         }
806:     }
807:     let Some(selected) = sample_mission_candidate(&mission, candidates) else {
808:         mission.status = MissionAttemptStatus::Failed;
809:         mission.parsed_state().map_err(|error| error.to_string())?;
810:         ctx.db.mission_authority().id().update(mission);
811:         return Ok(false);
812:     };
813:     let group = ctx
814:         .db
815:         .hostile_group_authority()
816:         .id()
817:         .find(&selected.hostile_group_id)
818:         .ok_or("Bound mission hostile group no longer exists")?;
819:     if group.disposition != HostileGroupDisposition::Active {
820:         return Err("Bound hostile group is already resolved".into());
821:     }
822:     let dropped_items = if selected.resolution == HostileResolutionKind::Defeated {
823:         mission
824:             .drop_item_id
825:             .clone()
826:             .map(|item| vec![(item, mission.drop_quantity)])
827:             .unwrap_or_default()
828:     } else {
829:         Vec::new()
830:     };
831:     let battle_id = format!("battle:{mission_id}");
832:     let outcome_source_id = format!("outcome:{mission_id}");
833:     let committed = commit_hostile_battle_resolution(
834:         ctx,
835:         HostileBattleCommit {
836:             outcome_source_id: &outcome_source_id,
837:             battle_id: &battle_id,
838:             party_id: &mission.party_id,
839:             mission_id: Some(mission_id),
840:             hostile_group_id: Some(&selected.hostile_group_id),
841:             resolution: selected.resolution,
842:             capture_subject_id: selected.capture_subject_id.as_deref(),
843:             dropped_items,
844:             include_random_gold: selected.resolution == HostileResolutionKind::Defeated,
845:         },
846:     )?;
847:     mission.status = MissionAttemptStatus::Committed;
848:     mission.committed_resolution = Some(selected.resolution);
849:     mission.committed_capture_subject_id = selected.capture_subject_id;
850:     mission.committed_capture_custody_version = selected.capture_custody_version;
851:     mission.parsed_state().map_err(|error| error.to_string())?;
852:     ctx.db.mission_authority().id().update(mission);
853:     Ok(committed)
854: }
