2: use std::{collections::BTreeSet, fmt, num::NonZeroU32};
3: 
4: /// A nonempty unique enemy snapshot. Its cardinality is derived for launch
5: /// projections; party receipt limits do not constrain hostile enrollment.
6: #[derive(Clone, Debug, Eq, PartialEq)]
7: pub struct MissionEnemyRoster {
8:     enemy_ids: Vec<u64>,
9: }
10: 
11: #[derive(Clone, Copy, Debug, Eq, PartialEq)]
12: pub enum EnemyRosterError {
13:     Empty,
14:     DuplicateEnemy,
15:     CountOverflow,
16: }
17: 
18: impl fmt::Display for EnemyRosterError {
19:     fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
20:         formatter.write_str(match self {
21:             Self::Empty => "A bound mission requires at least one enemy",
22:             Self::DuplicateEnemy => "Mission enemy authority contains duplicate identities",
23:             Self::CountOverflow => "Mission enemy count exceeds its transport representation",
24:         })
25:     }
26: }
27: impl std::error::Error for EnemyRosterError {}
28: 
29: fn checked_count(length: usize) -> Result<NonZeroU32, EnemyRosterError> {
30:     let count = u32::try_from(length).map_err(|_| EnemyRosterError::CountOverflow)?;
31:     NonZeroU32::new(count).ok_or(EnemyRosterError::Empty)
32: }
33: 
34: impl TryFrom<Vec<u64>> for MissionEnemyRoster {
35:     type Error = EnemyRosterError;
36: 
37:     fn try_from(enemy_ids: Vec<u64>) -> Result<Self, Self::Error> {
38:         checked_count(enemy_ids.len())?;
39:         if enemy_ids.iter().collect::<BTreeSet<_>>().len() != enemy_ids.len() {
40:             return Err(EnemyRosterError::DuplicateEnemy);
41:         }
42:         Ok(Self { enemy_ids })
43:     }
44: }
45: 
46: impl MissionEnemyRoster {
47:     pub fn enemy_count(&self) -> NonZeroU32 {
48:         checked_count(self.enemy_ids.len()).expect("constructor validates cardinality")
49:     }
50: 
51:     pub fn enemy_ids(&self) -> &[u64] {
52:         &self.enemy_ids
53:     }
54: 
55:     pub fn into_enemy_ids(self) -> Vec<u64> {
56:         self.enemy_ids
57:     }
58: }
