175 pub(crate) fn check_terminal_combat_outcome(
176     mut commands: Commands,
177     time: Res<Time>,
178     conn: Option<Res<SpacetimeDb>>,
179     consequences: Res<TacticalConsequenceAccumulator>,
180     mut state: ResMut<MissionState>,
181     enemies: MissionEnemyQuery<'_, '_>,
182     combatants: MissionCombatantQuery<'_, '_>,
183     loading_players: Query<(), With<LoadingPlayer>>,
184 ) -> Result {
185     if let Some(frozen) = state.terminal_retry_due(time.elapsed(), TERMINAL_ACK_TIMEOUT) {
186         return submit_frozen_terminal(frozen, time.elapsed(), conn, state, commands);
187     }
188     if !state.terminal_is_running() {
189         return Ok(());
190     }
191     let mut loaded_party = 0;
192     let mut incapacitated_party = 0;
193     for (entity, side, combat_state, player_id, yielded) in &combatants {
194         if *side == TacticalCombatSide::Party {
195             if state.observe_loaded_party_member(*player_id) == AdmissionResult::RejectedAfterSeal {
196                 error!(
197                     character_id = player_id.0,
198                     "Rejecting unseen Party character projected after enrollment sealed"
199                 );
200                 commands.entity(entity).despawn();
201                 continue;
202             }
203             loaded_party += 1;
204             incapacitated_party += u32::from(combat_state.is_incapacitated() || yielded.is_some());
205         }
206     }
207     let has_loading_player = !loading_players.is_empty();
208     if has_loading_player {
209         state.begin_enrollment();
210     }
211     let reconnect_grace = state.reconnect_grace();
212     match state.advance_enrollment(
213         loaded_party,
214         has_loading_player,
215         time.delta(),
216         reconnect_grace,
217     ) {
218         EnrollmentEffect::Sealed => info!(
219             expected = state.expected_party_members().get(),
220             "Party enrollment sealed"
221         ),
222         EnrollmentEffect::Abandoned => {
223             return commit_terminal_resolution(
224                 TacticalMissionResolution::Failed,
225                 time.elapsed(),
226                 conn,
227                 consequences,
228                 state,
229                 commands,
230             );
231         }
232         EnrollmentEffect::None => {}
233     }
234     let snapshot = TerminalCombatSnapshot {
235         required_enemies: state.required_enemy_defeats(),
236         loaded_enemies: enemies.iter().count() as u32,
237         incapacitated_enemies: enemies
238             .iter()
239             .filter(|(combat_state, yielded)| combat_state.is_incapacitated() || yielded.is_some())
240             .count() as u32,
241         loaded_party,
242         incapacitated_party,
243         enrollment_sealed: state.enrollment_ready(has_loading_player),
244     };
245     let Some(resolution) = state.advance_combat_outcome(snapshot, time.delta()) else {
246         return Ok(());
247     };
248     commit_terminal_resolution(
249         resolution,
250         time.elapsed(),
251         conn,
252         consequences,
253         state,
254         commands,
255     )
256 }
