904: /// First authenticated registration claims the singleton. Subsequent package
905: /// rotations must be made by the same SpacetimeDB identity.
906: #[reducer]
907: pub fn register_strategic_gateway(
908:     ctx: &ReducerContext,
909:     terrain_package_digest: Option<String>,
910:     terrain_schema: u32,
911: ) -> Result<(), String> {
912:     if ctx.sender() == Identity::ZERO {
913:         return Err("Strategic gateway registration requires authentication".into());
914:     }
915:     if terrain_package_digest
916:         .as_deref()
917:         .is_some_and(|digest| !valid_route_digest(digest))
918:         || (terrain_package_digest.is_some() && terrain_schema != 3)
919:         || (terrain_package_digest.is_none() && terrain_schema != 0)
920:     {
921:         return Err("Strategic gateway terrain package metadata is invalid".into());
922:     }
923:     let authority = StrategicGatewayAuthority {
924:         id: 0,
925:         identity: ctx.sender(),
926:         terrain_package_digest,
927:         terrain_schema,
928:     };
929:     if let Some(existing) = ctx.db.strategic_gateway_authority().id().find(0) {
930:         if existing.identity != ctx.sender() {
931:             return Err("A different authenticated identity owns the strategic gateway".into());
932:         }
933:         ctx.db.strategic_gateway_authority().id().update(authority);
934:     } else {
935:         ctx.db.strategic_gateway_authority().insert(authority);
936:     }
937:     Ok(())
938: }
