31: /// A case site is inside its origin settlement only when it has no travel
32: /// distance from that settlement. The origin is a provenance relationship; it
33: /// does not by itself make a wilderness site part of the settlement scene.
34: pub(crate) fn case_site_is_inside_origin_settlement(case_site: &CaseSiteAuthority) -> bool {
35:     case_site.distance_m == 0
