38: pub(crate) fn tactical_settlement_snapshot(
39:     ctx: &ReducerContext,
40:     case_site: &CaseSiteAuthority,
41: ) -> Result<Option<TacticalSettlementSnapshot>, String> {
42:     if !case_site_is_inside_origin_settlement(case_site) {
43:         return Ok(None);
44:     }
45:     let origin_settlement_id = &case_site.origin_settlement_id;
46:     let settlement = ctx.db.settlement().id().find(origin_settlement_id);
47:     let Some(settlement) = settlement else {
48:         return Ok(None);
49:     };
50:     if settlement.scene_key != case_site.scene_key {
51:         return Ok(None);
52:     }
53:     crate::settlement_population::ensure_settlement_population(ctx, origin_settlement_id)?;
54:     let mut operators = ctx
55:         .db
56:         .settlement_business_operator()
57:         .settlement_id()
58:         .filter(&origin_settlement_id.to_owned())
59:         .map(|assignment| {
60:             if assignment.business_id.settlement_id != origin_settlement_id.as_str() {
61:                 return Err("Business operator crosses the tactical settlement boundary".into());
62:             }
63:             ctx.db
64:                 .settlement_resident_profile()
65:                 .character_id()
66:                 .find(assignment.operator_character_id)
67:                 .filter(|resident| resident.home_settlement_id == origin_settlement_id.as_str())
68:                 .ok_or("Business operator is not a resident of its settlement")?;
69:             let operator_name = ctx
70:                 .db
71:                 .character()
72:                 .id()
73:                 .find(assignment.operator_character_id)
74:                 .ok_or("Business operator is missing its Character")?
75:                 .name;
76:             Ok(TacticalBusinessOperator {
77:                 business_id: assignment.business_id,
78:                 operator_character_id: assignment.operator_character_id,
79:                 operator_name,
80:             })
81:         })
82:         .collect::<Result<Vec<_>, String>>()?;
83:     operators.sort_by(|left, right| left.business_id.cmp(&right.business_id));
84:     Ok(Some(TacticalSettlementSnapshot {
85:         id: settlement.id,
86:         population_level: settlement.population_level,
87:         population_estimate: settlement.population_estimate,
88:         economy: settlement.economy,
89:         operators,
90:     }))
91: }
