8: #[derive(Clone, Debug, Default, PartialEq)]
9: pub struct Image {
10:     pub data: Arc<Vec<u8>>,
11:     pub width: u32,
12:     pub height: u32,
13: }
14: impl Image {
15:     // Decoding a URI is the only thing here that needs an image decoder and a
16:     // filesystem, so it is the only thing behind `image-io`. Without the
17:     // feature an `Image` is still a perfectly good pixel buffer -- it just has
18:     // to be handed its pixels rather than fetching them.
19:     #[cfg(feature = "image-io")]
20:     pub async fn new(_context: WgpuContext, uri: String) -> Result<Image> {
21:         let bytes = fabelgeist_fs::read_bytes(&uri).await?;
22: 
23:         let img = image::load_from_memory(&bytes)?;
24:         let img = img.to_rgba8();
25:         let (width, height) = img.dimensions();
26: 
27:         Ok(Image {
28:             data: Arc::new(img.into_raw()),
29:             width,
30:             height,
31:         })
32:     }
33: 
34:     pub fn from_pixels(pixels: Vec<u8>, width: u32, height: u32) -> Result<Image> {
35:         Ok(Image {
36:             data: Arc::new(pixels),
37:             width,
38:             height,
39:         })
40:     }
41: }
42: 
43: // Its own block: the one above is a graph node definition, and packing pixels
44: // for a format is plumbing that no graph should have a node for.
45: impl Image {
46:     /// The pixels, laid out for a texture of this format.
47:     ///
48:     /// No transfer function is applied, on purpose. An `Image` is eight-bit
49:     /// pixels and they reach the GPU as they are; all this does is reorder the
50:     /// channels a BGRA texture wants and widen them for a float one. Which
51:     /// space the pixels are read in is what the format is for: the hardware
52:     /// hands a shader sampling an sRGB texture linear light, at full
53:     /// precision, and one sampling a plain texture the stored value.
54:     ///
55:     /// Converting here instead would mean rounding linear light back into the
56:     /// eight bits it came from, and eight bits have no room for it -- the
57:     /// darkest thirteen levels of a picture all land on zero, and its shadows
58:     /// go flat black. It would also be wrong for half the pictures that arrive
59:     /// here: a normal map or a roughness map is measurements, not colour, and
60:     /// was never sRGB-encoded to begin with.
61:     ///
62:     /// A caller that does want linear light out of an image -- to fill a float
63:     /// texture with it, say -- converts it itself, where the precision is
64:     /// there to hold it: see [`fabelgeist_color::srgb_to_linear`].
65:     pub fn packed_for(&self, format: TextureFormat) -> Result<Vec<u8>> {
66:         let pixels = self.data.as_ref();
67:         Ok(match format {
68:             TextureFormat::Rgba8Unorm | TextureFormat::Rgba8UnormSrgb => pixels.clone(),
69:             TextureFormat::Bgra8Unorm | TextureFormat::Bgra8UnormSrgb => pixels
70:                 .as_chunks::<4>()
71:                 .0
72:                 .iter()
73:                 .flat_map(|rgba| [rgba[2], rgba[1], rgba[0], rgba[3]])
74:                 .collect(),
75:             TextureFormat::Rgba32Float => {
76:                 let widened: Vec<f32> = pixels.iter().map(|&v| v as f32 / 255.0).collect();
77:                 bytemuck::cast_slice(&widened).to_vec()
78:             }
79:             _ => {
80:                 let expected = (self.width * self.height * format.pixel_size()) as usize;
81:                 if pixels.len() == expected || format.pixel_size() == 4 {
82:                     pixels.clone()
83:                 } else {
84:                     anyhow::bail!(
85:                         "an image of {} bytes cannot fill a {format:?} texture of {}x{}, which wants {expected}",
86:                         pixels.len(),
87:                         self.width,
88:                         self.height
89:                     );
90:                 }
91:             }
92:         })
93:     }
94: }
